window.POEM_DB=window.POEM_DB||{};POEM_DB["song_028"]={"n":"郭祥正","dyn":"宋","poems":[{"t":"城东延福禅院避暑五首 其四","f":"七言绝句","c":["碧玉枝柯柑橘林，开花结子未成金。","何当烂熟经霜露，更约提壶一访寻。"]},{"t":"和杨公济钱塘西湖百题 其九十四 杨梅坞","f":"五言绝句","c":["红实缀青枝，烂漫照前坞。","不及杏繁时，林间有仙虎。"]},{"t":"墨染丝","f":"七言律诗","c":["缲丝自喜如霜白，输入官家吏嫌黑。","手持退印竞传呼，倏见长条染深墨。","墨丝归织家人衣，别买输官吏嗔迟。","寄言夷狄与三军，汝得丰衣民苦辛。"]},{"t":"将至慎邑寄鼎","f":"七言绝句","c":["踏尽琼瑶百里山，欲投城郭暮云间。","红炉速置一壶酒，故岁离家新岁还。"]},{"t":"倚楼","f":"五言古诗","c":["官闲何所之，倚楼纵远目。","田畴耒耜出，高下春雨足。","人家有生意，慰我苦幽独。","忆昨水沴馀，海气荡坤轴。","蛟龙坼川原，舟楫造溪谷。","禾麻安更论，未能保骨肉。","有子杀为食，何以厚风俗。","上赖天子圣，诏书勤抚育。","虽使发仓廪，饱岁实无畜。","郡县徒仓黄，论丁具糟粥。","所救无几何，往往委沟渎。","今兹气候正，逋民稍来复。","楚风重祠庙，才归竞巫祝。","此物岂有灵，焉能助丰熟。","渺思济时策，慎择良宰牧。","金缯斥诛求，教化行比屋。","祖宗德泽深，万岁长沐浴。","题诗起高兴，飘然跨鸿鹄。"]},{"t":"和杨公济钱塘西湖百题 其二十六 西村","f":"五言绝句","c":["远近皆僧刹，西村八九家。","得鱼无卖处，沽酒入芦花。"]},{"t":"寄东坡","f":"七言绝句","c":["君恩浩荡似阳春，海外移来住海滨。","莫向沙边弄明月，夜深无数采珠人。"]},{"t":"追和李白登金陵凤凰台二首 其二","f":"七言律诗","c":["高台不见凤凰游，望望青天入海流。","舞罢翠娥同去国，战残白骨尚盈丘。","风摇落日催行棹，潮卷新沙换故洲。","结绮临春无觅处，年年芳草向人愁。"]},{"t":"访隐者","f":"七言绝句","c":["一径沿崖踏苍壁，半坞寒云抱泉石。","山翁酒熟不出门，残花满地无行迹。"]},{"t":"金山行","f":"七言古诗","c":["金山杳在沧溟中，雪崖冰柱浮仙宫。","乾坤扶持自今古，日月彷佛躔西东。","我泛灵槎出尘世，搜索异境窥神功。","一朝登临重叹息，四时想像何其雄。","捲帘夜阁挂北斗，大鲸驾浪吹长空。","舟摧岸断岂足数，往往霹雳搥蛟龙。","寒蟾八月荡瑶海，秋光上下磨青铜。","鸟飞不尽暮天碧，渔歌忽断芦花风。","蓬莱久闻未成往，壮观绝致遥应同。","潮生潮落夜还晓，物与数会谁能穷。","百年形影浪自苦，便欲此地安微躬。","白云南来入我望，又起归兴随征鸿。"]},{"t":"春日独酌十首 其二","f":"五言古诗","c":["江草绿未齐，林花飞已乱。","霁景殊可乐，阴云幸飘散。","且致百斛酒，醉倒落花畔。"]},{"t":"春日独酌十首 其一","f":"五言律诗","c":["桃花不解饮，向我如情亲。","迎风更低昂，狂杀对酒人。","桃无十日花，人无百岁身。","竟须醒复醉，不负花上春。"]},{"t":"醉翁操","f":"词","c":["泠泠潺潺，寒泉。","泻云间，如弹。","醉翁洗心逃区寰，自期猿鹤俱閒。","情未阑，日暮向深源。","异芳谁与搴，忘还。","琼楼玉阙，归去何年。","遗风馀思，犹有猿吟鹤怨。","花落溪边，萧然。","莺语林中清圜，空山。","春又残，客怀文章仙。","度曲响涓涓，泛商回徵星斗寒。"]},{"t":"古松行","f":"七言古诗","c":["空山古松阅人代，黛色铜姿终不改。","蚴蟉诘曲还相向，千寻气结云叆叇。","风雨冥冥秋气深，耳边往往苍龙吟。","蓬莱仙子有无间，往来白鹤昼常阴。","百尺樛枝拓金戟，山中十月飞霹雳。","千年化作虬龙形，流脂下见成灵珀。","方今楼阁连飞甍，斧斤未敢来相倾。","晦冥神物共诃护，一物钟灵无不轻。","我来抚此重叹息，造物由来贵孤直。","趺坐松前日将暝，谡谡寒风落巾帻。"]},{"t":"醉歌行","f":"词","c":["明月珠，不可襦，连城璧，不可餔。","世间所有皆虚无，百年光景驹过隙，功名富贵将焉如。","君不见北邙山，石羊石虎排无数。","旧时多有帝王坟，今日累累蛰狐兔，残碑断碣为行路。","又不见秦汉都，百二山河能险固。","旧时宫阙亘云霄，今日原田但禾黍，古恨新愁迷草树。","不如且买葡萄醅，携壶挈榼閒往来。","日日大醉春风台，何用感慨生悲哀。"]},{"t":"古剑歌","f":"词","c":["古有名剑似秋水，龙盘虎拿焰欲起。","鸡林削铁不足言，昆吾百炼安足齿。","淬花曾瑩鸊鹈膏，掉箾却敲鸾凤髓。","忆昔破敌如破竹，带霜飞渡桑乾曲。","电光昼闪白日匿，魑魅走逃罔魉伏。","于今锈涩混铅刀，夜凉风雨青龙哭。","冰翼云淡雪花白，血痕冷剥苔花绿。","我来拔鞘秋风前，毛发凛凛肝胆寒。","书生无用暂挂壁，夜来虎气腾重泉。","酒酣闻鸡起欲舞，明星错落银河旋。","吾闻神物不终藏，丰城紫氛斗牛旁。","及时与人成大功，岂肯弃置钝锋铓。","会当斩蛟深入吴潭里，不然仗汝西域击名王。"]},{"t":"渔舟歌","f":"七言古诗","c":["四山飒沓江水流，两岸西风芦荻秋。","渔歌杳杳隔港浦，烟波冥冥来孤舟。","渔人举网得赤鲤，鱼尾筛筛相顾喜。","撑船就岸维树旁，夕阳篷底炊烟起。","白鹭洲边随意浴，孤云岩际无心逐。","月明烟岸撇波去，格磔一声山水绿。"]},{"t":"楚江行","f":"楚辞体","c":["吾生磊落无滞留，一生好作大江游，任尔龟鼍跋浪蛟龙愁。","昨夜天风下荆楚，我来此地重怀古。","洛妃湘女不足数，渺渺兮三闾在何所。","浩荡烟波江水阔，冥寞神交两相许。","倒提金斗倾浊醪，滴沥招魂寂无语。","斜阳衔山暝潮退，两两渔舟迷向背。","便欲因之垂钓竿，六鳌一掷天门外。"]},{"t":"九华山行","f":"词","c":["群山秀色堆寒空，九华一簇青芙蓉。","谁云九子化为石，聚头论道扶天公。","深岩自积太古雪，烛龙缩爪羞无功。","湍流万丈射碧落，此源直与银河通。","尘埃一点入不得，烟雾五色朝阳烘。","有时昏昏雷电怒，崩崖裂壁挥长松。","龙作雨，虎啸风。","白日变明晦，九子亦惨容，褐冠释氏胡为笑傲于其中。","我将学彼术，卷舌切愧求童蒙。","天公信玉女，号令不尔从。","嗟尔九子竟何补，非泰非华非衡嵩。"]},{"t":"谷帘水行","f":"七言古诗","c":["崭崭青壑仙人居，水精帘挂光浮浮。","中有天乐振天响，真珠琤淙碎珊瑚。","嫦娥拥月夜相照，天光地瑩倒玉壶。","又云玉皇醉玉液，琼簟千尺从空铺。","卧来北斗谏以起，惊风吹落青山隅。","溶溶万古万万古，竟谁能辨为真虚。","我来吟哦不知晚，山云四暗山魈呼。","安得长鲸驾天险，下视灵源知有无。"]},{"t":"鹦鹉洲行","f":"词","c":["猛虎磨牙齿九州，祢生何事来揶。","黄云屯屯宴宾客，故衣脱去更岑牟。","渔阳掺挝曲声苦，壮士衔悲寂无语。","汉朝社稷四百年，海泻涛淙一抔土。","嗟哉鼓史狂而痴，天运往矣安能追。","四方血战殊未已，三尺棁杖真何为。","君不见武昌之国鹦鹉洲，至今芳草含春愁。","可行则行止则止，死无所益令人羞。","死无所益令人羞，黄祖曹公均一丘。"]},{"t":"潜山行","f":"词","c":["笑别姑熟州，来作潜山游。","潜山闻名三十载，写望可以销吾忧。","晴云如绵挂寒木，广溪镜静涵明秋。","山头石齿夜璨璨，疑是太古之雪吹不收。","信哉帝祖驻銮跸，异景怪变谁能求。","若非青崖见白鹿，安得此地排珠楼。","群仙长哦空洞绝，绿章封事乘虚辀。","灵鸟盘旋老鹤舞，华灯散采祥飙浮。","噫吁嚱，汉武登坛求不得，明皇夜梦推五百。","宁知司命抱真符，为宋真人开社稷。","诏书数下修琳宫，殿阁缥缈平诸峰。","六朝德泽施愈远，九天福祐来无穷。","君不见潜山之下，潜水之涯。","菖蒲有九节，白术多紫花。","采之百拜献君寿，陛下盛德如重华。"]},{"t":"山中吟","f":"词","c":["山中吟，白日长，碧霄泉暖菖蒲香。","仙翁劝我采为食，登高遂觉足力强。","登高望远远思发，春风浩浩天茫茫。","美人一别隔沧海，青鸟寄与双明珰。","青鸟东飞亦不返，草色绿缛云徜徉。","草色几回绿，云飞无故乡。","魂迷梦断意何在，山中吟，白日长。"]},{"t":"山中乐","f":"词","c":["寻山佳兴发，一夜渡江月。","首到庐江元放家，水洞清光数毫发。","爱之便欲久栖息，又闻灵仙之境敞金阙。","清风吹我衣，不觉过皖溪。","危梁千步玉虹卧，松行十里青龙归。","烟霞绕脚变明晦，忽见殿阁铺琉璃。","重檐却在迥汉上，倚栏俯视白日低。","虚庭自作箫籁响，屋角更无飞鸟飞。","霓幡重重蔽真御，彷佛遥见星文垂。","长廊纱笼绝笔画，老龟稳载青瑶碑。","更逢逍遥不死客，齿清发翠桃花肌。","箫台可到亦非远，云间况有白鹿骑。","细窥绝景辄大笑，吾曹何事尘中为。","安得良田三百亩，可以饱我妻与儿。","长年只在名山里，万事纷纷都不知。"]},{"t":"将归行","f":"楚辞体","c":["男儿四十无所成，可怜鬓发霜华生。","长书朝奏夕命相，此事故非言不行。","低徊却入邵陵幕，梅岭招降建城郭。","论功第一遭众谗，断木浮沈委沟壑。","噫吁嚱，数奇不独李将军，株坐桐乡三见春。","桐乡虽好大儿死，风物满眼唯悲辛。","迩来又赴肥上辟，碌碌随人亦何益。","法网深悬无纵鳞，敛翼饥禽忧弹射。","噫吁嚱，一寸丹心不堪折，扁舟却忆姑溪月。","溪如凝冰月如雪，天地清光迥交澈。","钓丝千丈入琉璃，六鳌一举三山随。","人生快意莫如此，腰束黄金多横死。","君不见日暮途穷逆行客，一饷荣华速诛殛。","又不见都市朝衣就剑人，谁道忠言能杀身。","休休休，归去来。","芝田石室云长在，瑶草琪花春不回。","收帆银涛即平陆，跨青牛兮驱白鹿。","莫向人间歧路行，岂有悲欢与荣辱。","休休休，归去来，计已决。","肯学腐儒空有言，辜负春鹃口流血。"]},{"t":"东林行","f":"词","c":["龙蟠大地藏山腹，瑞气蒙笼紫金屋。","香炉万丈擎碧霄，二涧斜飞落寒玉。","晋朝遗事唐人辞，皴斮龟螭尚堪读。","楼烦真人应梦来，夜斧丁丁神伐木。","安帝亲留步辇迎，灵运开池素华馥。","会随流转不成尘，灯焰明明自相续。","游人未达此理元，安得清凉灭贪欲。","我今弃官脱尘网，僧宝瞻依无不足。","跨黄牛，骑白鹿，时时自唱无生曲。","无生曲，君试听，五音六律和不得，为君写作东林行。"]},{"t":"韶石行","f":"楚辞体","c":["扁舟未下连虞滩，韶石罗列谁雕刓。","化工有意露怪变，待彼虞舜来观玩。","泊舟登岸始远览，两峰直裂诸峰巑。","青鸾低徊欲下饮，翠凤却舞抟修翰。","蛰龙钁雷怒奋角，帝子出震初峨冠。","日光扑扑散金蕊，莲花透澈琉璃盘。","行衣十里仙雾湿，暝色一抹轻绡寒。","我将仙崖想韶乐，北风忽变阴漫漫。","松摇长空吼万壑，溪走石脚淙惊湍。","遗音自与天地响，听不以耳精神完。","重曈一去无复还，随风波兮陟云间。","潇湘洞庭亦何有，竹上血泪千年斑。","九成不作至道息，纷纷后世畴能攀。","登韶石兮情飘飘而未尽，饬彼柴车兮且将造乎苍梧九疑之深山。"]},{"t":"武溪深呈广帅蒋修撰","f":"楚辞体","c":["滔滔武溪一何深，源源不断来从郴。","流到泷头声百变，谁将玉笛传馀音。","潺潺泠泠兮可以冰人心，胡为其气兮能毒淫。","汉兵卷甲未得渡，飞鸢跕跕堕且沈。","天乎此水力可任，蛮血安足腥吾镡。","功名难成壮心耻，马革裹尸亦徒尔。","伏波一去已千年，古像萧萧篁竹里。","风来尚作笛韵悲，宛转悠扬逐船尾。","如今天子治文明，柔远怀忆昌黎氏。","始末缘何不相类，能言佛骨本无灵。","可惜咨嗟问泷吏，湘妃之碑尤近怪。","颇学女巫专自媚，固当褒马聊黜韩。","湘妃之碑尤近怪，颇学女巫专自媚。","固当褒马聊黜韩，补葺须令贤者备。","元戎喜遇蓬瀛仙，武溪探古传新篇。","东君吁嘻龙蜃走，北斗挹酌河汉悬。","劝君莫倚陇笛之悲音些，劝君清歌兮投玉琴些。","琴声为出尧舜心，尧舜爱民无远迩。","君不见薰风来自南些。"]},{"t":"松门阻风望庐山有怀李白","f":"七言古诗","c":["北风阻船泊湖漘，北望庐阜青无痕。","晴云自舒仍自卷，白龙欲眠犹宛转。","秋空漠漠秋气浅，碧天蘸水如刀剪。","篙师畏浪不敢行，却忆李白骑长鲸。","倒回玉鞭击鲸尾，锦袍溅雪洪涛里。","霓光溢目精神閒，终日高歌去复还。","飞流直下三千尺，风吹银汉落人间。","天送醇醪倾北斗，群仙吹箫龙凤吼。","李白一饮还一醉，醉来岂知生死累。","倏然却返玉皇家，不骑鲸鱼驾鸾车。","留连自摘蟠桃花，嚼花吐津染朝霞。","不信如今三百载，顽鲸骇浪空相待。"]},{"t":"苦寒行二首 其一","f":"七言律诗","c":["江南饶暖衣絺绤，今岁春寒人未识。","溪流冰合地成拆，一月三旬雪三尺。","去年大潦民无食，子母生离空叹息。","只今道路多横尸，安忍催科更诛殛。"]},{"t":"苦寒行二首 其二","f":"七言律诗","c":["下溪捕鱼一丈冰，上山采樵三尺雪。","人人饥饿衣裳单，骨月相看眼流血。","乾坤失色云未收，雕鹗无声翅将折。","官仓斗米馀百金，愿见春回二三月。"]},{"t":"武夷行寄刘侍郎","f":"词","c":["平生爱仙山，最闻武夷好。","千峰巑岏月倒挂，万木阴森春不老。","群仙浮舟出寥廓，未济明河半空泊。","世人可见不可攀，静夜天风吹宝乐。","须信仙家日月长，尘埃下土空茫茫。","贤愚得失竟何益，坐十绿发催秋霜。","人感感悟有谁早，丈人寻真归故乡。","故乡宅在武夷址，山势回环碧城起。","仙棋一局一番春，几见桃花满流水。","他年功成趋帝阙，醉唤常娥拥明月。","照开三十六洞天，玉树瑶花恣攀折。","丈人之乐其无央，我今欲往亲在堂。","侧身南望未能到，耿耿寸心思梦长。"]},{"t":"姑熟堂歌赠朱太守","f":"词","c":["姑熟太守真贤豪，洗涤弊垢明官曹。","民閒吏竦郡无事，华堂新构临江皋。","朱檐斜飞傍星汉，碧瓦不动蟠鲸鳌。","酿成玉液宴宾从，手提大笔降风骚。","四时景物换耳目，万古治乱评秋毫。","嗟予末坐重感激，胸中茅塞时耘耨。","山鸡卑栖竟何取，岂合鸾凤返翔翱。","紫莼茸蕨味正美，鲜鲚玉缕鸣霜刀。","为公一饮直醉倒，坐看万室皆陶陶。","谁云江南地偏小，姑熟之堂天下少。","丹湖千里浸城东，蒲苇藏烟春渺渺。","牛渚对峙凌歊台，长江倒挂天门开。","风吹玉乌亿万疋，汉兵卷甲沙场回。","有时浪止皓月满，琉璃宇宙无纤埃。","帆樯隐隐鸟飞没，渔歌细下天边来。","谢元晖，李太白，一生好作江南客。","至今遗恨人不知，孤云尚锁青山宅。","请公沥酒一吊之，听我长吟壮灵魄。","人世百年能几何，高会难逢离别多。","一朝公去调鼎鼐，斯堂永作甘棠歌。"]},{"t":"宣诏厅歌赠朱太守","f":"词","c":["使君心画天下无，构厅宣诏西南隅。","晓光初散射檐桷，夜气欲合吞江湖。","甓甃摩挲滑瑶玉，重窗窈窕明青朱。","胡生画手出前辈，素壁为写巫山图。","一条江练澄碧落，十二峰色峨珊瑚。","元猿老虎啸彷佛，长松瘦石寒扶疏。","中间皓鹤最恬淡，九霄独立形神孤。","君去班春劝耕稼，君归命客同欢娱。","三冬垂帘醉春瓮，六月静坐临冰壶。","巴笺血色洒醉笔，五字七字排玑珠。","和风匝地怨气灭，险吏缩手穷氓苏。","地随人盛古今好，姑熟自此为名区。","君不见滕王阁庾公楼，樽罍千载誇风流。","又不见宴寝一诗尚不灭，至今人道韦苏州。","噫吁嚱，四座勿歌听我歌，宣诏之名君谓何。","守臣不壅帝王泽，六合长静无干戈。"]},{"t":"济源草堂歌赠傅钦之学士","f":"词","c":["秀气鸿濛济州曲，十歌清池万竿竹。","竹里修椽架草堂，不羡长安买华屋。","春生广野碧玉柔，月拥翠岚银粉扑。","低飞白鹭拣晴沙，闻晓黄鹂啭乔木。","明明长剑倚太行，拂拂愁烟蔽盘谷。","重冈渐远势愈高，云开青出分秋毫。","龙蛇鳞甲雪霜洗，壮士四顾空提刀。","阴晴万变恣吟写，三叠琴声猿夜嗥。","君不见古来功名输隐叟，种桃采芝皆皓首。","不将机械搅灵源，能使形骸颇长久。","明公何年归草堂，扁舟我即浮沧浪。","江鱼有味四时美，一蓑醉临芦花傍。","男儿彼此送终毕，自算此身无得失。","江东片月过河阳，为照两处无何乡。"]},{"t":"寄题蕲州涵辉阁呈太守章子平集贤","f":"词","c":["读君涵辉记，恍若登蓬莱。","天垂星斗数寻近，地卷云山千里来。","冰壶倒景露华洗，玉窦溶雪蟾光颓。","尘寰何处路歧绝，三十六洞森然开。","武夷真孙佩符印，选胜得此将金罍。","文章欲会造化手，藩屏暂屈岩廊材。","谢公寄意东山妓，严生把钓桐庐台。","功名谈笑出千古，长与泰华青崔嵬。","其馀龊龊何足数，百年易得成寒灰。","为君高吟岂知倦，十分美酒谁相陪。","我欲乘风一飞往，病翅零落秋霜摧。","涵辉阁，宁久游，重瞳法尧垂冕旒。","侧闻下诏十六相，真孙第一还瀛洲。"]},{"t":"宣州双溪阁夜宴呈太守余光禄","f":"词","c":["陵阳三峰压千里，百尺危楼势相倚。","海波不动蛟龙盘，叠玉无尘霜雪洗。","溪光冷浥山光润，色接金陵古名郡。","青猿啸断四五声，白鸟归飞两三阵。","四时之景皆可观，六月来游肤发寒。","有时下瞰北山雨，只道林林银竹竿。","贤哉光禄余太守，昨引佳宾列樽酒。","朝饮三百杯，暮吟三百首。","不为阴惨严刑诛，长吐阳春活残朽。","御史曾书治绩碑，州人尽祝灵椿寿。","沈沈罗幕更漏稀，灯如撒星公醉归。","丝篁前引后鼓鼙，珠履交错行迟迟。","丈夫得意不为乐，借问百年能几时。"]},{"t":"寄题洪州潘延之家园清逸楼","f":"词","c":["南昌城中潘令宅，清逸楼高二千赤。","斜飞四角河汉躔，密排万瓦鸳鸯碧。","楼中至乐无人知，扫尽寰区别名迹。","霜华吹月雁横空，湖水浸天秋一色。","橹声断，渔歌起，西山却在芦花里。","行客纷纷嗟白头，缨尘不解沧浪洗。","爱君年少先拂衣，古人归去无今时。","上有明明垂衣之尧舜，下有错落戴主之皋夔。","湟中不用一箫取，缭绕驿道通犍为。","更看牧马天山草，澡心雪耻幽燕儿。","朝廷大业昔未有，志士独往吾何讥。","陶彭泽，阮步兵，回首晋道方飘零。","丝桐欲弹悲思盈，岂如潘令逢升平。","倚栏一醉弦索鸣，红绡燃蜜烂华星，玉人舞彻东方明。"]},{"t":"寄题德兴余氏聚远亭","f":"七言古诗","c":["暗空风卷浮云落，万里秋毫瑩寥廓。","姮娥泛月中夜来，扑扑山川银粉薄。","天垂斗柄挂帘钩，地接明河浸栏角。","谁倾世界入冰壶，滉滉仙春迷海岳。","嗟予南望未能往，小宰尘劳真龊龊。","感君寄我群公篇，览记方惊子先作。","词源奔激吼波涛，笔画纵横挫矛槊。","搆名措意岂徒然，景物化为仁智学。","丈人教子惇义方，宴息时来命樽酌。","何当勇起挐扁舟，梦寐思陪众宾乐。"]},{"t":"留题潜山山谷寺","f":"七言古诗","c":["山如连环不可解，玉溜穿崖鲸尾摆。","中天化出清凉宫，汗漫琉璃翠光洒。","回头无路通人间，毛发森森神魄骇。","长碑突兀压巨鳌，字刻雄文入模楷。","乃知梁僧挈刀尺，来此幽栖聊脱屣。","地祗掣锁岩户开，纵有堆金岂能买。","粲祖传衣当第三，至今异骨藏斯岩。","我朝重赐七宝塔，舍利感应符至諴。","谁曾磨崖记名姓，习之健笔深镌镵。","盘鼍皴鳞想风概，云雾惨淡遮松杉。","至宝不独世所惜，定有山鬼长扃监。","愿借雷公霹雳斧，坚珉斫断载以函。","高僧邀我恐忘返，虎豹堪惊日将晚。","归来拂榻坐虚堂，软煮黄精荐香饭。","千年遗迹安足誇，幻妄非真生有涯。","奈何吾势未能已，梦想长在金仙家。"]},{"t":"留题九江刘秀才西亭","f":"词","c":["南出九江城，西下五老冈。","倏然一径二三里，流水散漫桃花香。","桃花回环蔽深屋，犬吠游人人扣竹。","青衣借问来何为，正是刘郎春酒熟。","刘郎不厌客，抚掌邀我曹。","西亭有榻醉可卧，下临大江万顷之洪涛。","长帆出没送孤鸟，月飞不过哀猿嗥。","更爱双剑峰，正落南窗外。","天公好仁不用武，太古光铓未磨淬。","谁怀邪佞心，见之胆应碎。","淮山在天末，寒青亦相对。","微风时一来，松柏摇苍佩。","顷刻神官驱黑龙，汹汹兴云变明晦。","地势虽高直可惊，酒行且止䏑休嘬。","刘郎顾我笑，为言向苦悲。","阴晴非汝职，不醉将畴归。","归来乎，频相过，西亭把酒共君歌。"]},{"t":"留题西林寺揽秀亭","f":"词","c":["行瞻香炉峰，未出二林口。","一区广地如席平，谁作新亭名揽秀。","秀色可揽结，正对香炉峰。","李白爱之忍去，便欲此地巢云松。","寂寥往事三百载，涧泉谷草依旧扬清风。","泉可掬，草可撷，清风洒面如冰雪。","閒来携手四五人，倒尽金壶颊不热。","寸心何独忘宠荣，形骸遗尽神超越。","寄语世上士，劝君早归来。","霹雳轰车胆欲落，忠愤虽死何为哉。","此时竟不悟，此心徒自知。","岚光向晚紫翠滴，杜鹃更在深林啼。","试拂横琴奏流水，指下忽作商声悲。","悲来乎，可奈何，推琴罢酒为君歌。"]},{"t":"郑州太守王龙图出家妓弹琵琶即席有赠","f":"词","c":["偶骑匹马游仙关，瑶池夜宴欢未阑。","邀予末坐闻清弹，琵琶十槽声正繁。","初疑饥鸾啄玉应天响，忽似霹雳数声春气还。","曲遍将终檀板急，舞袖裂霞随拍入。","踏碎琼筵鸾步娇，汗透香绡露桃湿。","解绦罢舞整花钿，宛转仙容雁行立。","主人使令持酒卮，香随罗袜成尘飞。","铜龙无声夜无极，煌煌烛焰回朝晖。","桃源花落长溪净，人着秦衣樽俎罄。","岂如此会绝风流，主人慇勤宾客敬。","我作短歌公听取，人世百年能几许。","乐极哀来古所悲，不如立功当此时。"]},{"t":"瑞昌双溪堂夜饮呈吴令","f":"七言古诗","c":["星斗阑干月未吐，但爱溪声似山雨。","青灯照室并银花，白酒倾来不知数。","子善评文我不如，我亦谈诗子深许。","酒酣索我须论兵，拔剑画地军阵成。","十万甲兵指掌取，五方应敌旋风生。","文武道判惜已久，圣贤相遇犹难并。","相如谩作长门赋，屈原虚著离骚经。","不知于世竟何补，可怜博得千年名。","韩信收身苦不早，功成伏剑真草草。","始终最爱严子陵，坐视乾坤任倾倒。","咄嗟语险气已伤，况复赋诗声调长。","卷纸连书不磨琢，子锋大峻非我当。","拨置万虑付江海，收拾寸心归老庄。","天地得一马喻马，谓思前事皆佯狂。"]},{"t":"寄吴著作","f":"词","c":["忆与君别时，君行朝北极。","浔阳江头车马骇，意气翩翩动秋色。","君还旧庐能寄书，谓我楚辞传上都。","是时盗贼正纷扰，日夜奔走承使符。","谢君后时闻已恶，交深岂必书问数。","诚明相照期无穷，但惜远别临春风。","春风来已老，落尽桃花红。","有时孤坐碧山里，弹指倏忽成衰翁。","文章不直一杯酒，功名付与千年松。","何时逢君谈，豁我此愁恨。","攀云不见麒麟踪，趋泥自笑驽骀钝。","儿女安否今何如，亲虽未成交莫疏。","愿君富贵情不改，敢将瓦砾赠明珠。"]},{"t":"将至江夏先寄太守李学士","f":"词","c":["二月发姑熟，三月到浔阳。","闻君解缆才五日，骥尾难追空断肠。","十年前作浔阳吏，老狡相逢犹引避。","中丞孤愤已沈泉，时事愈新谁敢议。","欲吐哀音写心曲，濛澒江声摇地轴。","横琴静夜按金徽，泛到商弦断还续。","忧能损气须忘忧，移船渐近黄鹤楼。","楼前芳草渍烟碧，君今贤过奇章侯。","试询乐部谁工笛，曹王旧曲何人识。","水中龙应云不飞，月华正在江心白。","满倾绿酒浓如油，为君吞却鹦鹉洲。","开帆快意出天外，可惜碍断长江流。"]},{"t":"蒋公桧呈淮南运使金部此桧系鲁侍郎漕淮日手植","f":"七言古诗","c":["淮南庭中有苍桧，仰视团团翠为盖。","直干每容鸾凤栖，盘根深压鲸鳌背。","北风夜作兵阵声，恐取蛟龙斩天外。","呼童出屋为我窥，摩飐清阴月光碎。","问谁植之前蒋公，得地倏经三十载。","不同种杏上青天，正似甘棠有遗爱。","使华今复见公孙，太平事业钟一门。","祖庙冠盖渐尘土，却嗟此桧春长存。","孤高岂忘栽培力，秀发兼承造化恩。","已看枝叶饱霜露，终作栋柱扶乾坤。","新诗编联尽珠玉，光大先烈听篪埙。","更忆丹青妙画手，进入明堂逢至尊。"]},{"t":"蜀道篇送别府尹吴龙图","f":"词","c":["长吟李白蜀道难，蜀道之难难于上青天。","长蛇并猛虎，杀人吮血毒气何腥膻。","锦城虽乐不可到，侧身西望泣涕空涟涟。","其辞辛酸语势险，有如曲折顿挫万丈之洪泉。","世人不识宝玉璞，每欲酬价齐刀铅。","求之往古疑未有，惜哉不经孔子之手加镵镌。","公今易节帅蜀国，为公重吟蜀道篇。","旌旗翻空度剑阁，甲光照雪参林颠。","云鳌连推谷声碎，画角慢引斜阳悬。","竹马争迎旧令尹，指公长髯皓素非往年。","蜀道何坦然，和气拂拂回星躔。","长蛇深潜猛虎伏，但爱雄飞呼雌响亮调朱弦。","时乎乐哉，公之往也，九重深拱尧舜圣，庙堂论道丘轲贤。","抚绥斯民赖良守，平平政化公能宣。","来宾兴学有源本，何必早夜开华筵。","尝闻家家卖钗钏，只待看舞青春前。","此风不革久愈薄，稔岁往往成凶年。","噫吁嘻，今我无匹马，安得从公游，尽书政绩表中州。","献之明堂付太史，陛下请损西顾忧。"]},{"t":"钱塘行送别签判李太博","f":"七言古诗","c":["东南会府唯钱塘，高门双开南斗傍。","门前碧瓦十万户，晓色满城烟雨香。","圣祖神宗造区宇，应命最先吴越王。","不经兵火二百载，地饶沃衍民康强。","莲花红白西湖芳，南山翠影临沧浪。","琼楼宝塔照日月，尘埃不到炎天凉。","画船罗幕尽高卷，白玉美人游冶郎。","年年中秋海潮过，万顷银山面前堕。","少年轻命争弄潮，手掣红旗逆潮簸。","闻君此行承辟书，伯乐能求汗血驹。","四时风物同吟啸，十郡兵民归卷舒。","公闲畜德聊自养，承平功业还吾儒。","况君登朝未四十，慎勿出处穷欢娱。","慎勿出处穷欢娱，临渊履冰佩琼琚。"]},{"t":"天台行送施山人","f":"词","c":["平生乐山水，听客谈天台。","盘石摩挲浸海月，瀑布淙射烟霞开。","山腰喷作千岩雨，潭底昼夜轰风雷。","诸峰攒丛护宝刹，地与世隔无纤埃。","仙葩灵鸟四时有，石矼玉洞清风来。","施夫子，欲长往，高谢功名脱尘网。","况有西来老佛师，了悟无生任消长。","若许陶潜载酒过，便驾苍虬逐真赏。"]},{"t":"踸踔行送裴山人","f":"词","c":["踸踔踸踔裴山人，破帽麻衣被埃尘。","忽来访我环峰市，醉倒不顾傍人嗔。","壮士不得志，污泥困修鳞。","谁倾沧海救枯泽，矫首奋鬣乘风云。","回头问燕雀，尔辈胡为群。","巢寄柏梁一朝火，孤栖风雨更谁邻。","踸踔踸踔裴山人，行路无穷鼻酸辛。","元通献甫傥不遇，况有特达朱纯臣。","踸踔勿踸踔，岂有壮士长遭迍。"]},{"t":"道林寺送别崔提刑","f":"七言古诗","c":["湘江倾泻明河源，湘山来落如骏奔。","寻幽乘兴莫辞远，白云中有黄金园。","佛师无心法愈密，徒众先后陈卑尊。","甘泉喷洒仙籁爽，此身已觉超笼樊。","高堂却见山外水，古鉴磨开苍藓昏。","长城深锁万家富，老木自作千营屯。","两洲半没鲸鼓鬣，双崖斗起天为门。","沧溟不识几番变，石泐犹有涛淙痕。","茯苓愈大愈堪食，深锄但惜伤松根。","登高览物亦徒尔，秋色况是当离樽。","崔侯才思锐无敌，苍鹰得兔霜翎翻。","嗟余染翰愧复正，累句何足先行轩。","故人柄政坐东府，请君献策安黎元。"]},{"t":"游石盆寺呈蒋殿院兼简余光禄","f":"七言古诗","c":["石盆古寺苍崖颠，断碑皴剥无人传。","其文仅识隐岩字，御史饱学能推研。","乃是郑董之别号，洛师易节来刺宣。","风流直欲继谢守，行春车马时联翩。","红粉行行杏花笑，旌幡烁烁雌霓悬。","松声飕飕杂箫鼓，薜围缭绕疑檀烟。","不知身世有轩冕，且将樽酒投林泉。","暂时乐事亦难遇，高文大字精磨镌。","可嗟榛棘一藏晦，清风零落三百年。","洎逢佳士始珍赏，洗涤尘垢邀神仙。","坐思往迹若梦寐，明河千丈倾辞源。","啼鸟至今不避客，上下啾聒两耳边。","山僧搆亭又高绝，群峰叶叶如青莲。","崔嵬宝塔挂落日，沆砀冰壶撑钓船。","余公胡为未尝到，美景若此宁弃捐。","请携吟笔窥造物，更向云中调管弦。"]},{"t":"凌敲台呈同游李察推","f":"七言古诗","c":["腊月欲尽春风来，壮士寻春上高台。","金乌慢飞光徘徊，照散冰霜天地开。","梅花披香柳烟袅，狂杀钱塘苏小小。","玉箫金笛鸣高楼，怅望传书落青鸟。","吾曹强饮三百杯，老去功名安在哉。","欲驾飞鱼入东海，王母为我倾金罍。","莲华变碧蟠桃熟，仙家四时应不速。","醉来拍手乘紫烟，游遍洞天三十六。","高歌杳渺春风里，我怀清澈西江水。","腐儒往往咍吾狂，犹幸扬雄作知已。","脱君身上蜀锦袍，解我腰下并州刀。","更沽美酒共君饮，不负今朝春思豪。"]},{"t":"凌敲台呈同游张兵部朱太守","f":"词","c":["江东使者武陵仙，姑孰太守南都贤。","同时文采耀场屋，今日宠荣分使权。","岁丰民乐官吏肃，登高望远开华筵。","凌敲古台压城北，天门牛渚遥相连。","六朝盛事竟何在，白云芳草空绵联。","黄鸟声酸落花雨，青蒲风送西江船。","鸟声缭乱帆影没，劝君莫负杯中物。","百岁荣华如转轮，一半光阴已仓卒。","宁须杂管弦，不必烦绮罗。","紫莼煮豉肥鲈鲙，更听江南贱士歌。","尧崩舜立天下治，庙室灵芝最为瑞。","岩穴自此无遗民，请把长戈铸农器。","功名来时如等闲，四皓去矣谁复还。","一朝攘臂揖太子，社稷不动安如山。","可笑屈夫子，憔悴长江滨。","欲将独醒换众醉，竟葬江鱼愁杀人。","古来得失既如此，今朝幸会青云士。","功成早晚归桃源，回首尘寰脱双屣。"]},{"t":"游道林寺呈运判蔡中允昆仲如晦用杜甫元韵","f":"七言古诗","c":["长沙城西湘水隅，道林古寺松门纡。","尝闻秀绝超五岳，果见气象吞重湖。","殿前衔花走白鹿，殿里沈烟焚玉炉。","何人塑出慈氏众，冠缨动活摇明珠。","高僧处处有遗迹，盘石坐禅龙虎俱。","唐人妙笔数欧沈，至今板上栖群乌。","五言七字又奇绝，此寺此堂天下无。","不缘薄宦岂能赏，勇往兼有儿孙扶。","贾生前席竟忧死，屈原怀沙终自诛。","投身及早卜幽隐，淡泊久乃胜甘腴。","云生岳峤月晦影，雨过橘洲猿夜呼。","细吟静境足自适，忠愤未合思捐躯。","趋玄饱读长者论，养真默合烟萝图。","千篇愧比老杜老，一节愿随孤竹孤。","况陪使者共游览，二谢弟昆真友于。","不知昔日杨常侍，何似今朝蔡大夫。"]},{"t":"舒州使宅天柱阁呈朱光禄","f":"词","c":["群山奔来一峰起，千丈芙蓉碧霄倚。","嫦娥却月愁推轮，王母呼烟结缯绮。","分明有路金阙通，翠滑无尘玉壶洗。","老松自作孤凤吟，骇浪时翻三井水。","峨嵋绝巅安足论，力不擎天亦徒尔。","懊恼茂陵客，白日求攀天。","遗坛犹在半芜没，隐约龙驭回瑶鞭。","直至唐家六皇帝，梦感异境开重玄。","真符预告后五百，佐佑宝历推鸿延。","城头建阁旧丞相，窗户再新光禄贤。","手携大笔恣吟览，老句气焰摩星躔。","当时数赴范公辟，秀骨照坐谁差肩。","功名自许出绝域，岁月漫往修途邅。","丈夫有命岂嗟戚，投老得地多云泉。","霜柑正熟蟹螯美，白蚁旋漉浮金船。","伊予困踬坐小邑，怅望珠履参华筵。","祝公自此早归隐，幅巾藜杖诗中仙。"]},{"t":"中秋登白纻山呈同游苏寺丞","f":"词","c":["平湖万顷浮青玉，嫦娥更揽寒光浴。","天高星稀鱼雁沈，风静云消丝管逐。","试听郭子今宵歌，对月不饮奈愁何。","上尽高山万丈之绝顶，侧身可以攀明河。","明河洗君耳，明月照君面。","暂来空洞无物逍遥乡，安用声名誇海县。","前年从军梅山下，林黑只忧偏弩射。","去岁点夫大河北，黄土吹衣无昼夜。","劳劳功业安在哉，出林之木风先摧。","有言不得见天子，卷舌却出金门来。","流光差池鬓垂雪，幸对南山值佳节。","更在桓公游处游，自纾悲歌更清越。","登高何必须重九，零落黄花污浓酒。","岂如桂子散秋香，采露金人举纤手。","举纤手，饮未休，月轮忽转西山头。","明年此会定南北，沈思使我增离忧。","荆榛满眼世路恶，恩忘水覆终难收。","田文昔日三千客，去住如今均一丘。","噫吁嚱，达亦不足恃，穷亦不足羞。","但愿明月照我酒，古来秉烛供遨游。","因谁为谢北海若，酩酊不辨马与牛。"]},{"t":"登王知白秀才跂贤亭呈同游余万二君","f":"七言古诗","c":["凿山构亭邻北郊，志慕贤哲忘喧呶。","豁然千里开林梢，地势不得藏嵌坳。","三峰重楼排卦爻，二溪聱浪飞怒蛟。","渔翁捕鱼船尾敲，稚子锤塼争胜抛。","小塘圆沙来雁鵁，茂橘间错黄金包。","主人情深漆与胶，美酒旋漉罗珍肴。","亦有麟脯脍海鲛，痒背只欠麻姑抓。","浮生胡为长系匏，不蹈圣城徒譊譊。","窃甘禄食忧谤嘲，有若夜鼠防饥猫。","羡君脱屣心无殽，笑傲自足追由巢。","猛饮未彻鸡鸣嘐，新诗下笔论卷抄。","余君酒量辞斗筲，醉帽堕地垂鬓髾。","万子能禅誇悟泡，我独爱酒流涎交，同趋至乐情何聱。"]},{"t":"德化默亭观雪呈郑令","f":"词","c":["霜风结海天云冰，夜寒断尽朱丝绳。","晓来何处看猛雪，郑令新亭最高绝。","倒披貂鼠一登临，飞鸟不飞旱光灭。","时吟杜甫苦寒诗，白鹄翅垂眼流血。","昆崙关折非吾忧，但愿春泥补地裂。","西南香炉万寻玉，远思飘然看不足。","欲骑鸾鹤飞其颠，身虽未往神明肃。","又疑梦向琼池过，王母楼殿高嵯峨。","粉图屏风画未竟，隐隐朽笔方森罗。","天工好奇人莫识，纵心壮观聊唧唧。","酒瓶倒沥万籁沉，客子狂歌主人默。","默胡为乎名斯亭，主人意深窥杳冥。","不为四时役，不择万象嘉。","与时穷通自消息，见我狂歌应笑耶。"]},{"t":"采石亭观浪","f":"词","c":["洞庭秋高北风起，怒浪排空日光眯。","坐见雪山飞从物外来，地轴天关恐将圮。","移沙裂石失浦溆，群龙呀牙鲸掉尾。","舟人但如鹳鸣垤，咫尺存亡隔千里。","嗟哉至柔物，澒洞安可当。","大禹没已久，巨浸谁为防。","须臾风收浪亦静，嫦娥洗月添寒光。","湘妃妙曲鼓未彻，汨罗之魄云徜徉。","而今君臣正相乐，法弊一一新更张。","监司精明郡县肃，国无忠愤惟循良。","洞庭怪变自出没，回首天边归雁行。"]},{"t":"祀南岳喜雨呈李倅","f":"词","c":["六月赤日方炎炎，云不行天龙遁潜。","阴阳失职帝怒赫，地下万物遭炮燖。","农夫争陂数斗死，驱沙掷土唯飞廉。","湖南本钱二十有四万，岁望何以安黎黔。","府官惶惶使台恐，祀坛祷岳惟精严。","君驰副车职其事，秘文在板香盈奁。","镮刀割牲荐肴酒，夜半奠玉抽灵签。","星河收光倏阴晦，雷声群群来山南。","斯须密点欲裂瓦，烛光出屋排龙髯。","鼪鼯哀啼晓色淡，碧涧久涸银涛添。","田田水足稻秀拔，旱暵一洗凉飔兼。","芬馨罗列报神贶，文实之论前贤佥。","兴云作雨乃谁柄，坐视焦灼悭濡沾。","待兹诚祷始感发，威福自任宁无嫌。","至理从来莫能诘，异景聊足开吾瞻。","孤峰翠滑犀露角，溢溜飞洒琼为帘。","烟藏拱木半吞吐，湘水倒影分毫纤。","庙门欲出尚回首，正似老笔图霜缣。","高吟成章又奇绝，睥睨韩杜君何谦。","嗟余适为簿书缚，不尔从往精神欦。","蚊蝇休飞夏将尽，清露收拾摧圆蟾。","何当结轨更一往，历览舜迹穷高尖。","群仙虽有路歧远，志士岂无岩谷淹。","收奇拔俊召和气，一国遂除灾眚占。","暂时响应未足数，此语非是君仍砭。"]},{"t":"寄题鄂州李屯田家园仁安亭","f":"词","c":["头陀楼阁坐青烟，画屏正落南檐前。","主人隐几写风物，幅巾瑩爽南昌仙。","仙翁读书五千卷，道与世背多聱邅。","安之不扰静以养，逸我寿老全于天。","帘栊疏疏白光透，栏槛寂寂花阴圆。","黄鹂弄巧子趁母，白酒酿熟金为船。","渊明醉矣客可去，细藤织榻闲攲眠。","君不见黄鹤楼，鹦鹉洲，碧云欲合天自晚，芳草无情春亦愁。","祢衡白骨瘗何处，曹王旧曲无人收。","沈吟往事变华发，不饮何以销吾忧。","销忧乎，君且饮，醉来天地真衾枕。"]},{"t":"金陵赏心亭","f":"七言古诗","c":["夹淮青城几百尺，城上高亭望无极。","南还北去千万艘，人生何苦恋惊涛。","百年易得变尘土，后世视今今视古。","此间风月最为多，莫辞把酒呈高歌。","前朝宫苑荒烟在，乐极悲来亦奈何。"]},{"t":"钟山宝公塔","f":"七言律诗","c":["盘盘钟山古城北，夹道青松两行直。","浮屠突兀倚云烟，绘事犹存旧刀尺。","刀裁尺量不可过，浮生不悟欲如何。","凭栏直下视千里，多少丘墟藏绮罗。"]},{"t":"徐州黄楼歌寄苏子瞻","f":"词","c":["君不见彭门之黄楼，楼角突兀凌山丘。","云生雾暗失柱础，日升月落当帘钩。","黄河西来骇奔流，顷刻十丈平城头。","浑涛舂撞怒鲸跃，危堞仅若杯盂浮。","斯民嚣嚣坐恐化鱼鳖，刺史当分天子忧。","植材筑土夜运昼，神物借力非人谋。","河还故道万家喜，匪公何以全吾州。","公来相基叠巨石，屋成因以黄名楼。","黄楼不独排河流，壮观弹压东诸侯。","重檐斜飞掣惊电，密瓦瑩静蟠苍虬。","乘闲往往宴宾客，酒酣诗兴横霜秋。","沉思汉唐视陈迹，逆节怙险终何求。","谁令颈血溅砧斧，千载付与山河愁。","圣祖神宗仗仁义，中原一洗兵甲休。","朝廷尊崇郡县肃，彭门子弟长欢游。","长欢游，随五马，但看红袖舞华筵，不愿黄河到楼下。"]},{"t":"留题吕学士无为军谪居廊轩","f":"七言古诗","c":["城头高轩跳千里，数里苍山兼寒水。","帆开半落有无间，鸟飞不断丹青里。","北斗疏疏河汉晓，蓬莱一登天下小。","心随境化形亦忘，谁道霜翎老华表。","曹公窥吴教水战，虎貔蹙踏鲸鼍转。","野父相传此渡头，鱼网时时得遗箭。","当场英气安在哉，千年绝景藏蒿莱。","地祗监护待贤者，栏干倚遍倾金罍。","目送白云望尧阙，忠功孝名坚一节。","明时不作离骚经，玉上青蝇解磨灭。","升沈偶然安足嗟，与君高咏思无邪。","数声长笛奏何处，微风吹落天之涯。","天涯桂树清辉发，万顷波澜冻冰雪。","若承紫诏返瀛洲，此地曾忘迁谪忧。"]},{"t":"漳南王园乐全亭席上呈同游诸君坐客刘公曰有水一池有竹千竿可以赋诗浪士勇起索笔即其言缀成长调文不加点","f":"词","c":["乐全有水一池，有竹千竿。","池通两潮信，密竹四时寒。","引子黄鹂弄语，探鱼碧鸟忘还。","复有佳宾命酌，水晶交错觥船。","空中闻玉箫，王母想乘鸾。","问君不醉当何适，百岁忧愁今夕欢。","嫦娥痴姑理冰盘，绛龙蜡泪痴不乾。","孰知大海腾波澜，自有人世藏仙源。","刘公八十精神全，留子造古风义全。","蔡阮名家文学全，王氏世医阴骘全。","兀兀浪士天机全，乐全乎，且饮酒，独醒怀沙亦何有。"]},{"t":"题毕文简公撰李太白碑阴","f":"词","c":["清风无根长不死，太白高名亦如此。","何人谓是王佐才，文简雄词泻秋水。","贤孙出守镌长碑，碑成字字生光辉。","宠胡妃子已萌乱，翩然凤鸟来非时。","出林秀木众欲杀，纳官赎命何其危。","画船载酒酌明月，不著渔蓑披锦衣。","醉眼天地即衾枕，至今荒冢人疑之。","丈夫阖棺事未定，后三百岁方逢知。","知太白，文简公。","不誇能诗与饮酒，惜其浩气突兀藏心胸。","青山老碧洗秋色，姑溪濯绿涵春容。","太白不见碑可见，螭盘鼍载传无穷。"]},{"t":"寄题湖州东林沈氏东老庵","f":"词","c":["东林沈郎真隐居，山环水绕开方壶。","何年濯足脱尘网，坐卧七言哦蕊珠。","有时隐几佚吾老，万事不到灵台虚。","瓮间绿蚁春欲活，仙翁夜降青云车。","自称山人号回客，为君猛饮留斯须。","蚊蝇驱尽烛还灭，清风扫地银蟾铺。","梨花蕉叶钟与鼎，倒卷锦浪吞鲸鱼。","双瞳湛湛剪秋碧，三山不动乔松孤。","歘然踊起拂素壁，笔洒二韵铿琼琚。","西邻已富忧不足，东老虽贫乐有馀。","白酒酿来缘好客，黄金散尽为收书。","瓮乾吟罢尚携手，寥寥天籁鸣笙竽。","渡桥掺袂忽无迹，东方渐白飞群乌。","世人寻仙不可得，仙人寓世情何如。","桃源归路杳难问，落花流水空踟蹰。","后来福祸固已验，生死往复犹坦途。","圜庵不坏子传业，玉琴遗韵寒泉俱。","以回易吕未可必，回生回生是亦刘方徒。"]},{"t":"舟经池州先寄夏寺丞","f":"七言律诗","c":["去年收帆贵池口，闻君高歌撞玉斗。","今朝至自大湖南，五溪新事为君谈。","一年往返七千里，乡国生还真可喜。","君家白醪应已熟，正好齐山泛黄菊。"]},{"t":"留题方伋秀才寿乐亭","f":"词","c":["君家有亭何壮哉，参差碧瓦鸳鸯排。","重窗静深门不闯，地布瑩甓光如揩。","斑斑帘竹轻风筛，日影射午疑琼阶。","叠山堕势危相挨，木人围棋或负柴。","虎卧洞壑猿攀崖，好鸟上下鸣声喈。","真假造物微毫差，玉葩照水绝纤埃。","丝篁调音众伎俳，水沈焚烟凝昼霾。","夜晦烂蜡非燃䕸，唱酬交错并诙谐，逢逢晓鼓传官街。","两入场屋随计偕，未得蓝绶持简槐。","吾宁汲汲同井蛙，弃去不顾如敝鞋。","沈潜自适江与淮，滔滔动静终无涯。","圆天方地安形骸，虽然此乐非吾怀。","严慈鬓发霜华皆，嗟今仕禄犹暌乖。","行闻投印早归来，亭上致宴罗吴娃。","吴娃醉唱敲玉钗，綵衣自舞心宁?。","心宁?，奉亲酒，寿乐之荣世希有。"]},{"t":"寄献荆州郑紫微","f":"七言古诗","c":["李白不爱万古侯，但愿一识韩荆州。","荆州太守古来好，至今文采传风流。","郑公辞赋天下绝，殿前落笔铿琳璆。","相如严谨反枯涩，宋玉烂漫邻倡优。","卓然风格出天造，冰盘洗露银蟾秋。","麻衣脱去未十载，宝犀饰带鱼悬钩。","道行言听遇明主，皂盖朱轓宁久留。","渚宫风物最潇洒，酒满金罍谁献酬。","公尝爱我如李白，恨不即往从公游。","醉看舞袖卷明月，夜听长笛临高楼。","词源感激泻江海，笔阵顿挫排戈矛。","驽骀蹇蹶固已困，勉之尚欲追骅骝。","一朝公归坐廊庙，致君事业如伊周。","门阑从卫愈严密，是时愿见应无由。","行当投印佩长剑，梦魂已附西江舟。"]},{"t":"姑熟乘月泛渔艇至东城访耿天骘","f":"词","c":["姑孰望东城，长江八十里。","思君半夜泛渔舟，明月随人渡寒水。","江南美酒君家无，携来相就倾一壶。","澄江如冰月如玉，拂拂清风生碧芦。","功名无成安足嗟，但令方寸无疵瑕。","炼丹辟谷亦琐琐，万物何处非生涯。","君不见鸿沟欲将天下裂，失道阴陵遽身灭。","玉帐周遭皆楚歌，金甲缤纷摧汉钺。","重瞳却传绘塑手，瓦鼓巫歌荐神酒。","庙前老木藏训狐，豪气英风亦何有。","沈吟往事君勿悲，我曹幸遇尧舜时。","田中谷稔牛羊肥，高会难逢易别离，今宵不醉欲安之。"]},{"t":"西山谣寄潘延之先生","f":"词","c":["男儿无成羁薄禄，日月相推犹转毂。","谁向生前悟此生，西山山人挂冠速。","买田筑室临西山，时来石上横琴弹。","千古万古治乱事，一曲两曲顿挫松风寒。","门前禾熟酝美酒，故人车马留盘桓。","荣亦不足贵，辱亦不我干。","但愿青山绿水两不变，醉醒自得穷观玩。","名落人间非所欲，闭门且喜辞忧患。","君不见李太白，朝为酒家仙，暮作金銮客。","醉里题诗宫妾扶，自谓遇君今古无。","一朝谗言入君耳，夜郎远谪吟魂孤。","到死空言竟何补，何如道行及妻子。","西山人，孰可比。","晴空矫矫孤云飞，欲往攀援无路歧。"]},{"t":"上赵司谏","f":"词","c":["弹剑思经纶，悲歌负阳春。","逢时不自结明主，空文亦是寻常人。","君不见太公辞渭水，谢安起东山。","日月再开天地正，龙虎感会风云闲。","又不见屈原泽畔吟离骚，渔翁大笑弗餔糟。","可行则行止则止，胡为憔悴言空劳。","夫君之名振朝野，道行谏听逢时者。","南州岂足舒君才，天门夜诏星车回。","紫皇之真人，造化无嫌猜。","往将和气辅舒惨，不令地下万物同寒灰。","功成收身綵云里，坐酌千觞浮玉蕊。","麻姑王母相经过，醉来共泛瑶池水。","乐亦不可尽，名亦不可穷。","愿学李贺逢韩公，他日不羞蛇作龙。"]},{"t":"赠张御史","f":"词","c":["我爱张御史，酒船打拍浮。","欲邀天下贤，尽向酒中愚。","世人虽饮酒，只知酒味不知酒意胡为乎。","又闻夜归东海头，抚掌唤月当金壶。","须臾虾蟆蚀月黑，公起磨刀代天诛。","虾蟆吐月入地走，玉兔还家，桂树不枯。","公方醉卧，嫦娥惊呼。","且语东方苍青龙，迟迟推出赫日车。","自然月光不灭，公饮不彻，是时应笑高阳徒。"]},{"t":"赠提宫谏议沈公","f":"七言古诗","c":["贤材间出万人杰，行脱麻衣趋紫阙。","三朝出入持使权，凛凛声名洒冰雪。","往年作镇来金陵，天子临轩宣老成。","问公书画几万卷，品秩入奏编瑶琼。","延阁往往未尝有，诏札奖与光华生。","佥言公归坐廊庙，易节暂刺玄晖城。","恳请仙宫遽知止，车盖翩翩还故里。","粉娥执乐四时春，窈窕芙蓉新出水。","嘈嘈弦管鸾凤鸣，玉卮献酒公解酲。","人生快意似公少，家园乃是真蓬瀛。","数峰飞来云雾湿，琪树玲珑晓寒入。","绿池水照百花明，芳亭小榭佳宾集。","有时自赋归来篇，幅巾藜杖诗中仙。","秦晋诸子因避世，种柳栽桃安足怜。","顾我登门二十载，贵势能忘竟相待。","数奇自笑无所成，亦欲浮舟往沧海。","沧海云涛人不争，忘机可以超神凝。","比公进退殊未足，若问逍遥无鴳鹏。"]},{"t":"赠孙郎中","f":"七言古诗","c":["江潮夜涨北风恶，双橹喜逢溪岸泊。","桂阳史君贤故人，借问慇勤吏来数。","浮桥倾危暗难渡，静枕不眠听晓角。","平明自笑仆乘无，破帽赤髯行踸踔。","袖持漫刺前起居，屡叹穷愁手频握。","婴儿连死瘦妻卧，病骨尚遭谗喙喙。","壮志消尽同寒灰，生事无涯委藜藿。","男儿有命何足论，斗酒贳衣评旧学。","爱君新篇溢千楮，突兀寒宵见南岳。","龙蛇千丈老松杉，霹雳一声挥电雹。","岂宜偃蹇处郎曹，固合透迤步台阁。","天子聪明继尧舜，庙堂论道皆伊霍。","拔茅连茹收时才，尺寸高卑应不错。","君驰亨路鹗横秋，我困污泥龟缩壳。"]},{"t":"赠张参军","f":"词","c":["宣城之人张待举，高才未得见明主。","强将樽酒娱天真，犹得狂名落寰宇。","陶陶复陶陶，意气蛟龙豪。","沧溟岂是远，银汉不为高。","路逢郭子陵阳津，平生未识如故人。","相欢握手辄大笑，共访瑶池寻玉真。","天门夜叉识虑恶，为我无钱谨关钥。","兴阑却驾彩云归，别入红窗共君酌。","醉来兀兀乘扁舟，长溪水碧芙蓉秋。","愿逢万丈龙须席，卷取月明归玉楼。"]},{"t":"赠彭明微判官","f":"词","c":["昔谒公家贤侍郎，一见许我能篇章。","俸粳兵酒屡持送，时时解榻令登堂。","今喜清风传令子，回首亨衢脱双屣。","北堂归养太夫人，水陆珍羞称甘旨。","深沈大第蟠蛇鳞，儿孙蓝绶何诜诜。","有时宴喜列宾客，洞房粉黛桃花春。","玉指纤纤拂弦索，轻云凝碧罗衣薄。","主人快意妾争妍，松上女萝知有托。","君不见景太傅，杀身本为功名误。","又不见张舍人，朝为近侍夕为民。","古来宠辱亦如此，安用浮云缠此身。","爱君进退真得所，不负青春领歌舞。","我方两鬓扑黄尘，梦寐江南思旧土。","别君去，将拂衣，扁舟若渡历阳月，愿听新歌酩酊归。"]},{"t":"赠陈懒散","f":"词","c":["懒散翁，何怪奇。","形容磊落似元亮，情性孤高如伯夷。","灵台瑩彻轩辕镜，妍丑默辨毫与釐。","生涯只寄一壶酒，万事掉头予弗知。","或乘烂醉说儒佛，风云座上腾蛟螭。","显晦自任不可测，头角变化将有时。","惊人一鸣，冲天一飞。","岂能龊龊事小隐，尧舜君臣方有为。","懒散勿懒散，石渠金马须翁来。"]},{"t":"赠舒州李居士","f":"词","c":["李居士，存心最慕韩伯休。","州城卖药不二价，世人求我我何求。","颜如渥丹眼如漆，和气酣酣吐朝日。","偶来握手为一言，照尽五脏平生疾。","箧中自取三粒丹，瘦骨坐使春阳还。","便当投印弃冠带，与君海上巢名山。","深锄茯苓酿酒，极饮形骸可长久。","乘槎鼓枻入云涛，醉放一丝携六鳌。"]},{"t":"谢杜倅职方兼简汤史君","f":"七言古诗","c":["李白昔游宣城时，谁为太守贤相宜。","掣铃交通唤六博，壮哉意气凌虹霓。","北望楼高气象古，遗风馀思犹依依。","我来正值青春半，杂花烂笑禽争飞。","轻烟缭绕淡白日，细风荡漾吹游丝。","高楼帘卷邻袖出，百尺栏干横酒旗。","银鞍白马不知数，龙筝凤管相追随。","杜陵远孙驾别乘，恩威得所名声驰。","华堂重搆唤宾客，风前共倒黄金卮。","我为下客最疏放，辱君许可能文词。","死生夤缘释氏说，但觉时换名姓非。","寄言太守勿感戚，共对佳人花下迷。","莫教流水落花去，空闻暮雨哀猿啼。"]},{"t":"谢刘察推","f":"七言古诗","c":["秋风吹霜入松柏，虚谷声遥寒刺刺。","月华正高星宿稀，独鹤不鸣觜插翼。","是时夫子为我吟，逸调雄才世无敌。","十年学诗自谓豪，一日逢君有惭色。","恍疑醉梦太帝家，宝藏珠楼不知极。","蟠桃结实九重春，金银琅玕万林直。","须臾收拾到平淡，雨洗高峰增老碧。","又如摩诘画思精，一幅霜绡数拳石。","鬼神怪变露形状，天地英华发胸臆。","我家江南谢朓山，山深流水长潺潺。","猕猴摘果趁不去，白云常在衣裳间。","断无车马送尘土，独与猿鸟期追攀。","一杯有酌醉复醉，万虑不到閒中閒。","欲邀君去咏此景，愿窥巨笔追扬班。","其馀功业未足数，天马安得趋尘寰。"]},{"t":"谢东城练尉","f":"楚辞体","c":["我闻武夷山，乃是神仙府。","灵丹插峭壁，异骨留深坞。","有时风高月色静，天乐琤淙散天宇。","飘飘秀气钟为人，往往声名迈前古。","练君头角杰然奇，少年折桂登云梯。","陆机才华恨羞涩，相如词调惭支离。","青衫一命东城尉，能使斯民歌恺悌。","鸾凤肯与鸡鹜争，万里云霄终自致。","东城烟水秋茫茫，览古高吟应断肠。","白蛇血溅赤龙剑，八千子弟同时亡。","而今战处无青草，庙门斜掩狐狸老。","群巫请雨摇镮刀，滴沥椒浆荐蘋藻。","力拔山兮安在哉，丹青壁画空尘埃。","因君吟想不能已，孤雁一声山月颓。"]},{"t":"谢淮西吴提举","f":"七言古诗","c":["瘦马徐行三百里，扑扑黄尘眼双眯。","手携簿法趋使台，惟恐瑕玼烦摘指。","蓝衫戚戚走廊庑，与坐抚循颜色喜。","琅琅先诵荆州吟，醉来捉住鲸鱼尾。","如今无复气凌云，垂首低徊逐泥滓。","须臾又忘按察尊，罗列壶觞瞰池水。","圆荷翻风碧玉软，幽鹭得鱼团雪起。","正当烦暑浩如秋，更听高谈清入髓。","君臣会合前世无，朝廷万事图新美。","甲花照日御营寒，胡命悬丝朔风里。","自嗟虽老力未衰，命未遇知甘摈死。","南山射虎竟残年，不得封侯亦徒尔。","感君欲引西江波，涸辙行将脱蝼蚁。","功名成就须报恩，莫道江南无壮士。"]},{"t":"仲春樱桃下同许损之小饮因以赠之","f":"词","c":["君不见古人悲歌愁杀人，一片花飞减却春。","径须沽取就花饮，暂时烂醉陶天真。","借令黄金大于斗，岂买人间百年寿。","但愿青春永不归，更得沧溟化浓酒。","朝酌弗乾，暮倾弗竭。","东向浮桑采日枝，西入瑶池浴明月。","枯桐三尺安足弹，重华去矣薰风寒。","夷齐耻食首阳粟，屈子徒佩潇湘兰。","噫吁嚱哉贤与愚，同归一死胡为乎。","共君极饮且烂醉，指点世路皆虚无。","许损之，尔为我满斟，我为尔高吟。","相逢莫恨晚，结交贵知心。","坐看南山一片雾，忽成千里万里之春阴。"]},{"t":"再游花山","f":"七言古诗","c":["去年来时春未归，枯林叉枒露老枝。","今日重来春已去，秀叶茂密藏黄鹂。","山家景物新换故，世事尘埃朝复暮。","白头迤逦谢轮蹄，青冢绵联老狐兔。","令人归兴如浮云，早向江山乐贱贫。","不须访道赤松子，但爱鲈鱼并紫莼。"]},{"t":"酬蔡尉秘校","f":"词","c":["环峰雨过烟岚披，君醉兀兀骑驴归。","明朝大字送满箧，乃是醉扫琅琊诗。","阳冰篆笔昔未有，铁索礧碨缠蛟螭。","禹称八咏不足数，永叔烂浸镌瑶碑。","山光水润洗出大古色，更后敢作知为谁。","爱君胆大少且锐，搀剔缺漏笔补之。","飘然一别今七载，取读往往生光辉。","宁知流落尚为尉，潇湘邂逅令人嚱。","又致新章溢编楮，遣仆买酒烹黄鸡。","伊予齿发更衰落，固异往昔相逢时。","举杯未尽辄醉倒，跟吻虽强难扶持。","人生老去百无益，谈新忆故惟伤悲。","劝君休吟亦勿饮，橛株拘坐真忘机。","死生终始了为一，清风为我炎天吹。"]},{"t":"酬李从道太博","f":"七言古诗","c":["秋水浸天无表里，间帆已过三千里。","鹦鹉洲前逢故人，往事新愁还可纪。","祖朝熙熙民物好，长忆联车游五老。","鸟啼花舞送春归，倏忽官书满三考。","从兹南北趋尘劳，往往遭嗤儿女曹。","斗筲之禄未能弃，回首空羡严陵高。","相逢彼此惊迟暮，笔下琳琅写心素。","荷花十顷绕君家，岂是荒榛碍归路。","悲歌不觉青衫湿，酒杯未满愁先入。","闻说明朝趋玉京，直节如今恐难立。"]},{"t":"公择鄂守学士三堂请雨","f":"七言古诗","c":["庙门斜开压江浦，红裳小巫未击鼓。","太守焚香令致词，愿驾苍龙作霖雨。","三神鼎峙名谓何，子胥范蠡马伏波。","图经莫载碑字灭，忠魂血食应不讹。","朝廷日夜传新令，辅弼贤良元首圣。","阴阳调燮神相之，忍使斯民饥以病。"]},{"t":"酬魏炎秀才","f":"七言古诗","c":["碧云暮合庐山头，夜蛩声撼乡园愁。","忽然一见旧游客，贳酒不惜千金裘。","高谈稍听吐胸臆，歘如野烧光难收。","虎豹哀嗥走不彻，猎网四面谁能搜。","嗟予慄慄畏事者，兀坐视予劳双眸。","主人欣欢亟扫室，雁榻旋列横霜秋。","两溪倒碧泻明月，松窗左右风飗飗。","长篇赠我不可和，和声酸涩令人羞。"]},{"t":"和懒散赠葫公","f":"七言古诗","c":["葫公家在东园隅，世族蕃衍今仍孤。","平生嗜酒少知者，请说懒散提携初。","杖头世界迷日月，豁然心地无榛芜。","人人未饮公辄醉，坐卧只与樽罍俱。","章华开口泄上旨，毛颖秃发非中书。","贪官虽得后乃辱，智虑可惜于身疏。","岂如葫公泛沧海，不用鼓枻并乘桴。","蓬莱顶上受玉液，酣酣至乐忘荣枯。","劫火任灭公未醒，不复愿进承明庐。","承明侍宴尽金玉，君岂有意来相呼。"]},{"t":"月下独酌二首 其一","f":"词","c":["长空无云江水净，月出东方挂金镜。","我时有酒何处斟，破碎寒光借渔艇。","便邀玉兔乞灵药，一粒为医天下病。","玉兔既不报，我亦醉不知。","舟人解事唤我起，月轮已转西山西。","人间万事不可了，且与明月閒相随。"]},{"t":"月下独酌二首 其二","f":"楚辞体","c":["明月不解饮，何事解照琉璃钟。","金波荡漾使我惜不彻，一酌万事逃心胸。","良时忍自弃，圣代真难逢。","生平不知耕与战，唯知猛饮大笑吟清风。","竹林七子岂足数，渊明五柳方途穷。","一身不为万乘屈，傲矣严陵垂钓翁。","明朝官满，归去来兮，但愿月轮不缺，樽酒不空。","吾君万岁坐法宫，四海长静无兵戎。"]},{"t":"魏武庙","f":"七言律诗","c":["濡须山头祠魏武，炫转红装按神鼓。","蘋藻盈筐酒满樽，呼吸风雷激春雨。","田畴高下春雨平，操牲饮福罗中庭。","吞吴成魏还归晋，血食犹参社鬼灵。"]},{"t":"向舜毕秘校席上赠黄州法曹杜孟坚即君懿职方之孙也","f":"七言古诗","c":["青天无云日华满，小妓楼中吹玉管。","卷帘不信夜霜寒，熏兰酌桂肌肤暖。","黄州之客最少年，醉来口角倾词源。","惊龙掣电绕沧海，沙场阵马成功旋。","殿赐新袍织春草，水溢双瞳犀插脑。","壮图伫结明主知，带束黄金应未老。","宣城忆拜乃翁时，幕中珠履皆雄奇。","至今名姓记僧壁，当年已识麒麟儿。","嗟予老人日零落，两鬓衰蓬眼生瘼。","寸心犹欲慕夷齐，险路无缘攀卫霍。","邂逅桐乡逢故人，槐槽泻酿追阳春。","形容若画凌烟阁，第一江南寻隐沦。"]},{"t":"怀青山草堂","f":"词","c":["三峰连延一峰尊，龙山白纻如儿孙。","重冈复岭控官道，北望金陵真国门。","淙流奔激洒河汉，两溪直接丹湖源。","松荒桧老古佛刹，鸡鸣春晚桃花村。","石崩废井谢公宅，龟仆断碣长庚坟。","斯人白骨已化土，英气往往成烟云。","我昔弃官结茅宇，九品青衫安足数。","竹筒盛酒骑白牛，醉眠看天与天语。","如何蹭蹬随辟书，十年又向风尘趋。","只今两鬓满霜雪，功业不成思旧庐。","山花解忘忧，山鸟名提壶。","四邻未必便弃我，三径荒草还堪锄。","乌泥田肥种秫稻，紫莼味美饶嘉鱼。","盈缸酿酒邀客饮，林下散发时时梳。","谁人絷尔不归去，自问此心无乃愚。"]},{"t":"忆五松山","f":"词","c":["江南富山水，忽忆五松山。","梁僧种松夺造物，至今千丈凌云间。","上有寒蟾吐魄凝冰雪，下有铜陵碧涧倾潺潺。","雷公睥睨不可以挥斧，老鹤飞来势欲止而复还，猿猱侧望何由攀。","琉璃殿阁若化出，四天之众说法鸣金镮。","我尝脱屣往栖息，六月清风无汗颜。","浓阴可爱坐盘石，绿酒酌尽横琴弹。","命宫叩徵天地变，听之以气往往生羽翰。","纷埃不到佛净国，岂识人间行路难。","尘劳忽起旧缘想，倒骑匹马来长安。","修鳞掉尾业已困，涸辙孰与西江澜。","发疏齿缺形将残，畏涂足蹑心胆寒。","屈原怀沙贾谊贬，身后忠名何足观。","不如宴坐碧山里，笑傲每携云月欢。","明朝却欲渡江去，五松岩户无人关。","方壶员峤太殊绝，幸有此山容我闲。"]},{"t":"清明望藏云山怀旧游","f":"七言古诗","c":["忆昔清明出郊去，藏云寺前花正开。","蜜蜂衔蕊异香散，时时洒面微风来。","溪泉甘滑碧玉色，晴山倒影无纤埃。","红粉佳人十七八，踏青唱歌云鬓颓。","黄犊行牵载酒瓮，到处便倾三百杯。","或逢浓阴藉草坐，口横玉笛吹落梅。","傍人问我乐何事，我心无事同婴孩。","谁令束带入官府，触网修鳞难再回。","清明依旧好时节，朱颜憔悴无由陪。","藏云之山亦非远，隔江东望青崔嵬。"]},{"t":"洛中王秀才谈刘伯寿动静慕其潇洒作诗识之","f":"词","c":["客来说刘翁，嵩山跨黄犊。","青衣二双鬟，颜色若明玉。","手携绿牙笛，随轩奏新曲。","倒倾酒榼松下饮，旋开毡帐云中宿。","少年富贵老安闲，自道此生无不足。","令人慕高标，神魄顿萧爽。","何当插两翼，乘风一飞往。","永结斯人交，逍遥恣真赏。","长哦紫霞篇，洞户琼瑶响。","胡为恋青衫，壮节空肮脏。","尘埃一閧城郭卑，波澜万顷沧溟广。","明朝未作嵩少游，且向江南结鱼网。"]},{"t":"逍遥亭歌一首赠太守王君章","f":"词","c":["逍遥之亭在何许，城角西南小溪浒。","水仙粉面浮清波，羽林兵仗森三亩。","六月微风拂面寒，不信人间有烦暑。","借问逍遥真隐徒，西山看雪倒骑驴。","形骸兀兀天壤俱，画手争以丹青模。","大言得罪仅免诛，斥参军事来当涂。","传云此地旧结庐，百年荆棘遗荒墟。","公来相址呼犁锄，双亭化出琼璃铺。","栏干斗角明青朱，四座瑩彻纤埃无。","兰芬麝裂陈罂盂，珠履珊珊陪后车。","东瞻宣诏西浮图，晓光夕景迷蓬壶。","爱公心昼如明珠，落成之乐政事馀。","为公歌，劝公醉。","留连亭上能几时，行促星轺还玉陛。"]},{"t":"投献省主李奉世密学","f":"词","c":["祖朝相国之真孙，轩轩冠盖宜高门。","拔身州掾入政府，议论挺特穷根源。","颜渊必用孔丘铸，自此声名闻至尊。","熙宁神化迈前古，屡诏驰车外循抚。","大河之北淮之壖，民起疵瘝勇歌舞。","枢庭进直腰横金，君臣道合同一心。","货泉交汇指诸掌，老吏缩手随规箴。","如公之才世希有，突兀千丈辉乔林。","徐冠貂蝉坐廊庙，重见成王得周召。","泰山镂牒天垂休，却笑鸿濛首频掉。","贱生流落何可言，四十栖迟埋冗员。","涸鳞怅望一杯水，安用西江浩渺之波澜。","愿公吐和气，稍回岩谷春。","养成尺寸木，为公车下轮。","他年青史上，报德岂无人。"]},{"t":"俞俞堂寄鄂州李裕老","f":"词","c":["黄鹤楼南大湖侧，芙蕖深绕谁家宅。","云是裕老之宴居，高堂独榜俞俞额。","春山抱翠入平檐，夏竹引凉吹广陌。","秋江澄月天镜开，冬雪拥林昆阆白。","世间万事不挂心，瓮拨香醪欣有客。","客来乎，伴我饮，不醉无归醉还寝。","问君欲达逍遥乡，信哉天地真衾枕。","觉来何物能解酲，试作琵琶打面声。","俞俞和气淡四体，安用辟谷求长生。","君不见鹦鹉洲前杀祢衡，三赤棁杖当雄兵。","才名误身不自觉，恬淡晦迹无人争。","南北相望二千里，梦逐高帆逆秋水。","为翁持酒听翁歌，衣濯黄尘眼除眯。"]},{"t":"前云居行寄元禅师","f":"楚辞体","c":["忆云居，乃在汇泽西南修川之隅。","山盘盘兮，石门屹立磴道绝，飞瀑万丈淙冰壶。","云沈沈兮方昼而忽暝，古木交错兮藏鼪鼯。","攀崖欲上复自止，投险却忆骑鲸鱼。","崖向时复造平野，绝顶乃有百顷之膏腴。","群山下瞰若聚米，殿阁枕藉非人区。","露华洗出太古月，桂子摇落阴扶疏。","清风欲借羽仪展，秽念顿觉秋毫无。","老禅底事不度我，红日东上还驱车。","如今正似武陵客，放舟已远嗟迷途。","青春一往二十二，白雪渐变千茎须。","西来忽遇归飞鸟，青纸远寄黄金书。","灵茶香味胜粉乳，满箧所赠遇琼琚。","玉川七椀吃不得，灌顶未识真醍醐。","南暹北讷惜已死，唯师秀出孤峰孤。","潜深隐密自得所，岂不悯我栖榛芜。","倒影射岩犹入石，异日三椽容野夫。"]},{"t":"后云居行寄和禅师","f":"楚辞体","c":["我所思兮，欧山之巅。","白石苍木蔽窥而隔世兮，路通乎兜率之天。","层楼复阁，触峙绚烂。","往即造兮，云渤兴而澶漫。","徙倚恍惚，若夺吾魄兮，聊枚睫以盘桓。","徐风生而雾散，卷绡縠于林端。","洎天清而日上兮，瀑峻飞而潺湲。","畜而为潭，泄而为涧。","运之以车兮，盈乎大田。","然复度石桥，登重门。","睹篆玉之榜，谒金仙之尊。","徒众五百，厖眉皓首。","形仪静而不杂兮，语言要而不烦。","齐兴止以钟鼓兮，善后先而靡难。","举正眼而谛瞬兮，了无一法之可观。","寂兮乐兮，妙复妙兮，其惟真如之禅。","我请弃冠释带以投依兮，师则指乎未契之缘。","于是曳屣却步，循磴道而复返兮，岁眇眇而屡残。","触网罗以系累兮，方伤羽而戢翰。","怅昨游而欲再兮，庶已创而复完。","乱曰：畴将归兮，卧龙之室。","依人道师，成佛而出。"]},{"t":"赠潜山伊居哲先生","f":"七言古诗","c":["伊君头戴星文冠，遨游五岳何时还。","结茅却在潜山里，闭息自养丹田丹。","闻说年龄七十九，发如鸦青亦稀有。","生平读尽道藏书，寓兴成诗仅千首。","清风生我太古弦，弹罢时倾一壶酒。","门前手植数本松，看尔凌云比予寿。","高奔日月瞻玉京，阴气鍊尽阳气成。","行闻北帝呼六丁，紫书下诏鸾凤迎。","潜山空留千载名，白云不断溪长清。"]},{"t":"赠桐城青山隐者裴材","f":"七言古诗","c":["青山为主身为客，主人借客青山宅。","白云自在千里飞，长松不换三冬碧。","藤枯谁与写作龙，龟老何年化为石。","落花随水眷深源，鸣雁过江悲晚色。","家无妻子心无累，顶冒寒霜踵藏息。","月明舞影聊尽欢，一点尘寰不留迹。","傥来轩冕真可嗟，朝为公卿暮遭谪。","屈原贾谊尔为谁，问君何似青山客。"]},{"t":"寄刘继邺秀才","f":"词","c":["忆昔重游乐，寻春之宛陵。","天机织出万山锦，虹桥倒影银河明。","游丝萦空白日暖，好鸟乱响清风生。","叠嶂楼中索美酒，坐上客子皆豪英。","诸姬合杂奏弦管，一人妙唱为井琼。","玉板斜开厚冰裂，鸳鸯索拍秋波横。","酒盏贪欢不知数，梦入瑶池逃宿酲。","谁知一别万事错，荷衣倒着来江城。","青云散尽落青野，长丝掣断无长鲸。","乡山好在却归去，当共故人吟此情。"]},{"t":"题杏山阮氏高居","f":"七言古诗","c":["仙翁得仙朝玉皇，当时种杏盈山冈。","传闻落英堰流水，每到三月溪泉香。","白云霏霏出幽谷，独鹤沉沉唳乔木。","寒潭深处睡蟠龙，灵草芳时跃青鹿。","丈人何年居此间，诜诜孙子如芝兰。","抱才求进十五六，亦有随计乡书还。","步兵傲世逸千载，谁道风流至今在。","软炊玉粒烹黄鸡，客子虽多竟相待。","我爱长吟登好山，到此便欲辞尘寰。","可能筑室辄延我，为君鍊熟黄金丹。","丹成大笑分一粒，坐令绿发回朱颜。","浮生百岁不早悟，日月扰扰空循环。"]},{"t":"铜山寺","f":"七言古诗","c":["田塍行尽苍山转，溪水滔滔晴曝练。","马蹄怯石鞭不行，十步九蹶令人倦。","黄昏到寺亟就榻，山僧苦来邀我饭。","香粳新炊野菜肥，一饱令人百忧散。","篆香欲尽象灯暗，林声敲敲苦霜霰。","暂来福地能清虚，何用致身居诤谏。"]},{"t":"隐静寺 其一","f":"七言律诗","c":["门横大溪溪净碧，人不捕鱼鱼稳潜。","哀猿长啸雾垂地，饥虎一声风动帘。","金仙像古苔藓剥，铁磬夜敲规矩严。","道师达性傲时辈，不信书生来养恬。"]},{"t":"隐静寺 其二","f":"七言律诗","c":["碧霄峰下车轮停，道师未返谁逢迎。","山云情着雨正急，春水满田人不耕。","饥虎啸风大石裂，倦鸟唤雏深涧鸣。","客心欲去且复止，坐饱香饭馀何营。"]},{"t":"浮丘观","f":"七言古诗","c":["仙翁得仙二千载，沧海变田田变海。","浮丘却接番禺西，鐏迹蒿痕至今在。","朱明之门敲不应，荆榛满地谁重兴。","史君举意要卜筑，楼观矗云如化城。","李白骑鲸下蓬岛，嫦娥洗月来沧溟。","相逢且劝百壶酒，蟠桃结实何时成。","史君自有神仙骨，往往前身寻旧物。","手探树穴求玉环，肩拍洪崖犹彷佛。","更提椽笔挥长篇，至理直欲追玄元。","行当跨凤返金阙，回首番禺空紫烟。"]},{"t":"明皇十眉图","f":"七言古诗","c":["明皇逸事传十眉，正是唐家零落时。","霓裳曲调虽依旧，阿蛮终不似杨妃。","画工貌得非无意，欲使流传警来世。","翠翘红粉尚争春，隐约香风起仙袂。","六龙真驭竟何之，泰陵荒草长孤狸。","空将妙笔劝樽酒，醉觉人间万事非。"]},{"t":"九疑山图","f":"词","c":["噫吁嚱，九疑山色何雄奇。","坡陁诘曲不足状，九峰万丈排天扉。","崭崭俨若九老坐，乾颠坤弱能扶持。","崖回时复见华尘，原本旋有山经题。","白云绵联芳草歇，拱木夭矫狂风吹。","上有源源不绝之寒泉，下有沄沄不断之深溪。","初疑青铜照碧落，忽见云汉飞虹霓。","丹青画出尚如此，而况高步穷岖崎。","或云重瞳一来不复返，二妃血泪斑竹枝。","惜哉不经孔子辨，后世谁能公是非。","尧非幽囚，舜不野死。","尧崩民如丧考妣，舜非游仙而幸此。","群猪耸耳听童子，游人击之变风雨。","见豕负涂圣所恶，仙人护之亦何补。","我知神仙术已卑，但爱此山雄而奇。","背图南望未能到，高吟尽日长吁嚱。"]},{"t":"魏中舍家藏王摩诘海风图","f":"七言古诗","c":["只闻王公画山水，未识王公沧海图。","魏侯矜誇我家有，取出十幅堂中铺。","谁知东海群龙力，神妙能以一笔驱。","洪涛翻天雪成陇，黑分云雾藏空虚。","高低数寸折万丈，势以意会无差铢。","却嗟流传数百载，绢素何以当涵濡。","王公之心壮莫比，其工欲出造化初。","惜哉已死不复得，怅望尽日将何如。","魏侯魏侯重藏秘，直恐变化成江湖，我歌不足徒呜呼。"]},{"t":"王元当家藏钟隐画三害图","f":"词","c":["老钟笔法何奇古，三害精灵一图聚。","周生自握苍精龙，白额长蛟甘丧沮。","危桥跨水压波涛，巨木翻风瞑烟雾。","挺然独往知忘躯，敢谓诛邪天地助。","三日生还动闾里，千载遗踪存绢素。","薄蚀已更人仰之，自古贤豪遗细故。","何独今人无此人，已觉丹青有深趣。","江南印玺尚如新，国破苍忙画谁付。","一图分裂藏三家，离合悠悠岁时度。","只今皆属丞相孙，挂向高堂邀客顾。","倏然风云驾霹雳，雨来平地银潢注。","珍绨收藏卷不彻，直恐变化复入江湖去。"]},{"t":"燕待制秋山晚景","f":"词","c":["我朝妙画能山水，燕公笔法精无比。","燕公山水工平远，一幅霜绡折千里。","潇湘洞庭日将晚，云物萧萧初满眼。","虞帝之魂招不返，霜树冥冥红叶卷。","二妃血泪知几多，竹上遗痕深复浅。","渔舟片帆风已满，渔父横眠思犹懒。","时时白鹭聚圆沙，亦有行人下前坂。","江回岸断数峰青，彷佛灵妃曲可听。","却逢深崦见茅屋，只欠桃花如武陵。","世间何物人争诧，请说奇书并妙画。","一时鉴赏安足论，流转千年愈增价。","珍绨一袭藏至珍，卷尾长篇更入神。","呜呼粉墨终成尘，唯有文章道德能日新。"]},{"t":"夏公酉家藏老高村田乐教学图","f":"词","c":["高生妙画世所知，君藏两幅尤瑰奇。","春回老柳未全绿，和气盎盎微风吹。","负暄当案谁氏子，坐以训诂传童儿。","麻鞋破穿十指露，纻衫短袖乌巾攲。","眼吻开张手捉笔，叱怒底事扬其威。","两童分争迭相挽，彼二稚子傍观窥。","一童独卧守书卷，性习已见分醇醨。","皤然老叟醉兀兀，二孙侧立犹扶持。","馀皆伶官杂村妓，插笛放鼓陈威仪。","三犬奔来吠欲齧，二人惊顾方攒眉。","伶家有子少亦黠，两手据鞍驴载之。","尊卑向背极精妙，精妙得以意思惟。","田翁丰年固取乐，又能教子勤书诗。","德泽涵濡赋敛绝，致我鼓腹咸熙熙。","画工亦画太平事，谁欲扰之生乱离。","高生高生，不独爱尔之妙笔，对此颇思三代时。"]},{"t":"寂照大师匣藏相国寺坏壁秋景","f":"词","c":["京城车马多尘埃，一见妙画心眼开。","深山老木秋思静，苦雾郁郁诸峰埋。","客骑蹇驴打不动，懊恼似忧寒雨来。","崖平路转斗然绝，笔力未断空徘徊。","胡为皴剥仅盈尺，鐍以大箧过琼瑰。","师云昔是殿堂壁，治平大水馀皆摧。","恰如卢仝玉碑子，中路扑折令人哀。","玉碑一折乃无用，此画虽缺犹堪裁。","君不见，山前路，路长不独忧风雨。","前有毒蛇后猛虎，磨牙矫尾藏深坞。","圣人皇皇嗟逆旅，画工意思非无补。","非无补，谁信之，纷纷门外誇轻肥。"]},{"t":"泗水雍秀才画草虫","f":"七言古诗","c":["蜻蜓点水蝶扑花，螳螂捕蝉蜂趁衙。","营营青蝇争腐糁，趯趯阜螽沿草芽。","馀生骨朽不复得，雍子笔老谁能加。","卷开却掩恐飞去，绨袭爱护行随车。","况君才力日清敏，胡不放手为龙蛇。","龙蛇逼真看腾跃，出入天地藏烟霞。"]},{"t":"谢冲雅上人惠草书","f":"七言古诗","c":["上人胸腹包琅玕，醉目睥睨临冰纨。","墨池顷刻波澜翻，虬龙尾尾垂云间。","摇曳天矫若可攀，霹雳轰斧电火骞。","卒章雨雹霏漫漫，澒洞恐惧坤轴掀。","白沙纵横仆鼍鼋，屋漏壁折安足言。","鸟惊出林避弹丸，斗高复下腾修翰。","朽木欲折枯藤攒，逸兴不顾长毫乾。","客如堵墙争纵观，讵知垩尽吾鼻端。","黄金论斗珠走盘，数字不售尤为难。","尔尝爱我说玄理，为我落笔动盈纸。","张颠怀素嗟已矣，上人之书无与比。"]},{"t":"谢钟离中散惠草书","f":"七言古诗","c":["丈人行草天下无，体兼众善精神俱。","少年弄翰今悬车，一幅不博千明珠。","墨池翻澜化鲸鱼，老木半折倾藤枯。","霜天一阵来雁鹜，荒陂数点眠鸥凫。","换鹅瘗鹤虽已矣，折钗剑舞成须臾。","心通造化乃神速，伯英怀素真其徒。","迩来作我醉吟赞，宝藏二妙归江湖。","要将垂法数百载，摩挲青玉亲传模。","丈人善吟仍善奕，名誉岂止专能书。","名誉岂止专能书，皎如浩雪盈冰壶。"]},{"t":"谢蒋颖叔惠澄心纸","f":"七言古诗","c":["李氏三世皆名书，古今笔法谁能如。","澄心堂中畜妙纸，敲冰捣楮惟恐粗。","当时文物称第一，教敕往往亲涵濡。","赫然真龙跃中国，僭迹甘就雷霆诛。","论功行赏尽金玉，唯有此物多赢馀。","流传既久乃珍绝，一轴不换千明珠。","乐安御史辄寄我，二十五幅无纤污。","却疑织女秋夜醉，素段割裂天所须。","又如美玉才出璞，瑩采射目争阳乌。","文章未到一王法，宝纸谩对明窗铺。","廷圭煤麝铜雀瓦，气象嵂兀尤相于。","坐思厚贶欲为报，累旬安得论锱铢。","况君才力似韩愈，尽当返赠诛奸谀。"]},{"t":"谢馀干陆宰惠李廷圭墨","f":"七言古诗","c":["集仙昔与文忠游，文采声鸣喧九州。","鲲鹏未化忽拓翼，地老天荒云海幽。","箧中尝秘上赐墨，紫金泥印双脊虬。","名题廷圭姓氏李，此物未省何年留。","纹如坚犀刮不动，铿铿触砚苍烟浮。","蜀笺洒落黑胜漆，欲论所直真难酬。","麟儿字法肖家学，珍绨宝匣深藏收。","并刀截断辄分我，始信明珠今暗投。","嗟予吟笔久已阁，辩舌倒卷刚肠柔。","书陈北阙上印绂，志乐南亩亲锄耰。","得君赐墨竟安用，捧玩反覆增予羞。","况君绿发眸子瑩，才业自副朝廷求。","研磨煤麝染谏草，扶擿世病苍生瘳。","名成功遂取上笏，世阀光焰垂千秋。","莫如老钝默将死，再拜谢贶长江头。"]},{"t":"谢李公择惠妙墨二饼","f":"词","c":["南山来松节，北山割麝脐。","烧烟扫煤和胶漆，篆记岁月形蛟螭。","集贤学士久珍玩，云初得自扶桑枝。","张翁所作又精绝，磨刮不动犹坚犀。","邺台古瓦汲水试，黑云随手生冰池。","况君学术老益富，六经秘法穷无遗。","明窗静几列毫楮，而与此物真相宜。","草玄著就垂万世，忠厚自任陈安危。","嗟予吏役久零落，至宝暗赠宁非痴。","呜呼大禹已往不复见，一尺浑厚疑玄圭。"]},{"t":"谢王公济节推惠砚","f":"七言古诗","c":["歙溪之仙洗山骨，一轮琢出秋潭月。","摩挲清润无纤痕，不学寒光有时缺。","玉川辄莫忧虾蟆，纵尔觜吻何由齧。","阴天著手泉脉生，三伏临之冰炎热。","又如明镜当晴窗，对面森森数毛发。","端江品格直顽贱，邺台片段多皴裂。","中山有客先得之，獬豸峨冠为忠血。","窜身南过洞庭湖，覆舟几葬蛟龙穴。","君今赠我诚谓何，自愧閒官非补阙。","松烟和漆法廷圭，玉兔长毫妙诸葛。","敲冰捣楮出乌田，四物收藏岂虚设。","乾坤俯仰存赤心，诛贬奸谀佑臣节。","独刊五传扶春秋，肯趁时文校工拙。","更衰更老心更坚，与砚相将不仓卒。"]},{"t":"谢方彦德奉议惠罗文砚","f":"楚辞体","c":["歙溪古源凿龙尾，一片寒冰瑩无比。","珍绨藏护知几年，赠我题诗草堂里。","骊珠失色悲暗投，再拜置之枯木几。","砚兮不似在君家，捧来自有纤纤指。"]},{"t":"中秋泛月至历阳访太守孙公素","f":"词","c":["中秋挐轻舟，西泛采石月。","初疑擢碎冰壶冰，又如飞度雪山雪。","若非身世出尘寰，底事清光透毫发。","袁宏谢尚久磨灭，含情欲就何人说。","历阳太守孙公素，竹冒寒霜松屈铁。","昔从赤县守仪真，再上天门请符节。","紫皇诏长鸡笼仙，惠浃春阳威凛冽。","开仓出粟赒民饥，夜户不扃无窃发。","咄哉此事安足论，斯人自养班夔卨。","且闻兵厨酝浓酒，桂子秋香月中有。","请君置我三百杯，我为君吟一千首。","垆锤七窍完混沌，能使颓龄遂长久。","饥横镆铘鲙鲸肉，渴引明河倾北斗。","凭谁为问陶渊明，胡为种菊仍栽柳。","岂如永夜无纤云，江光月色铺黄银。","唤取三千珠履客，陶然一饮情无垠。","刘项输赢亦安在，笑杀今宵月下之醉人。"]},{"t":"二月十一日倪倅敦复小园留饮","f":"七言古诗","c":["残梅零落同寒灰，屏翳忍驱斜雨来。","濛濛点滴夜连晓，园馆寂寞生青苔。","墨云四卷山露碧，日毂照耀天衢开。","妖桃映竹烟酩酊，细柳拂水风徘徊。","倪公要我共行赏，小亭草草排樽罍。","盈筐菊芽青玉软，满盘鲚缕红丝堆。","兴来一笑且为乐，春光半被莺啼催。","百年已往五十八，借问馀生真可咍。","平原豪客散烟雾，东山舞妓埋蒿莱。","眼前不肯饮五斗，身后安能倾一杯。"]},{"t":"和州连云观留题呈太守王纯父","f":"七言古诗","c":["连云之观何寥廓，碧瓦危侵天一角。","深排柱础贯九江，返挂帘钩吞五岳。","风樯北去烟溟溟，雁阵南飞秋漠漠。","白衣每从栏下回，金盆正在檐前落。","蔡公书榜妙入神，剑戟纵横挫矛槊。","主君自是蓬莱仙，分符暂与民同乐。","卷舒当为天下霖，一钓能令六鳌跃。","滕王庾亮尔何人，回视规模太卑削。","我从姑孰飞轻舟，欲陪珠履登斯楼。","与公酣歌相献酬，兰亭俗饮安足求。","手摇麈尾拂斗牛，为君千载扬风流。"]},{"t":"谢历阳王守惠新酿","f":"词","c":["卓荦英才历阳守，年来不得音书久。","隔江知我岩户寒，赤泥封送兵厨酒。","碧玉壶，黄金斗，雪树云峰作宾友。","为君一醉歌阳春，空山霹雳龙蛇走。","只愁君返紫皇家，西望连云谩搔首。"]},{"t":"寄历阳张宗孟隐士","f":"七言律诗","c":["历阳张君心好古，冰不为寒蘖非苦。","我欲见之波浪阻，安得邻巢接飞羽。","百年营营竟埋土，进退趑趄亦何补。","今岁秫田收几亩，烂醉高吟馀不数。"]},{"t":"送余秘校","f":"七言古诗","c":["苍山冻云犹未消，君骑瘦马来飘飘。","入门下马与我语，琅琅满室鸣箫韶。","一官初得遭猛守，十年困辱朱颜凋。","恨无田园即长往，醉卧白日歌唐尧。","去干斗粟活妻子，谁念尘滓污琼瑶。","相逢太息不能已，解衣贳酒愁魂消。","红梅零落雪霜洗，苍雁蹭蹬狐狸蹻。","男儿功名顾有命，太公七十方渔樵。","否极泰来如覆手，阔步自此凌烟霄。","侧闻丞相开东阁，肯使斯人重折腰。"]},{"t":"送梅直讲","f":"词","c":["青风吹天云雾开，仙人骑马天上来。","吟出人间见所不可见，常娥织女为之生嫌猜。","织女断鹊桥，常娥闭月窟，从兹不放仙人回。","一落人间五十有四载，唯将文字倾金罍。","李白佯狂古来少，骑鲸鬣鬣飞沿洄。","杜甫问讯今何如，应为怪极罹天灾。","公乎至宝勿尽吐，吐尽吾恐黄河水决昆崙摧。","天穿地漏补不得，女娲之力何可裁。","长安酒价不苦贵，风月但惜多尘埃。","醒来强更饮百盏，酣酣愚智宁论哉。"]},{"t":"送袁殿丞","f":"词","c":["与君六年别，愁见云开露明月。","樽中有酒虽独倾，万古情怀共谁说。","思君弹瑶琴，琴声为君咽。","孤鸿高飞不可攀，北风一送何时还。","欲问鲤鱼更难得，江头白浪高于山。","天书彼此绝，令人肠百结。","昨日闻君来，我心如凿龙门开。","拂拭囊中白玉璞，请君辨之为磨琢。","感君酬价过南山，即见名声摇海岳。","烹羊买酒邀吴姬，今朝会合明朝离。","莫嗟两鬓白雪满，请看舞袖红云飞。","云飞酒阑君遂起，篙子催行趁潮水。","君行汲汲过西山，手植松篁春正美。","我亦归青山，白云相伴闲。","若驾鸾凰赴瑶阙，先到临川与君别。"]},{"t":"送钱贤良","f":"词","c":["去年六月梓山里，与子披襟弄泉水。","高谈直出尧舜前，长林为我清风起。","金船满满倾醇醪，吴娥玉指拈樱桃。","君令劝我尽百盏，肝肠但觉翻江涛。","醉来骑白鹿，大笑还青山。","倏忽岁月往，思君鬓成斑。","今朝邂逅芜江头，论心握手忘离忧。","暂时会合复言别，安得弹剑从之游。","我闻紫微荐君策，男儿事业岂易得。","金门慎勿闲经过，为奏天下弊穴如蜂窠。"]},{"t":"送章秘书","f":"词","c":["君心抱太古，不肯屈世人。","匹马遍朔方，扬帆出天津。","九疑连天洞庭阔，长歌愁杀苍梧神。","更将美酒吊楚屈，离骚继作疑前身。","两姬不洒望夫泪，一笑岳阳楼上春。","丈夫得意且为乐，百年变化随埃尘。","如何南还过我别，却言北去朝天阙。","上书力诉元兄冤，洗眼看君成一节。","劝君事直还收身，速返东南弄白云。","功名汲汲竟何益，韩彭取笑武陵人。"]},{"t":"送杨主簿","f":"七言古诗","c":["浪花卷雪秋风起，开帆日行三百里。","问君此去安所之，佐邑南城风俗美。","夫君才业真雄奇，四十青衫能养卑。","世无孔子礼乐坏，君独勇起勤扶持。","书成未遇聊自哂，暂向南城为吏隐。","閒入麻源倾酒卮，仙家好景无忙时。","瀑绡千丈挂苍壁，玉华万柄摇清池。","嫦娥东来渡银汉，面面瑩彻皆琉璃。","谢公秀句发天籁，颜守老笔蟠蛟螭。","高风凛凛尚可揖，鸟声不断哀猿啼。","嗟予学道苦不早，壮岁形容已枯槁。","闻说名山心即飞，一生愿向山中老。","爱君逸兴何由攀，飘如孤鹤遗尘寰。","若见麻姑与王远，寄我一粒黄金丹。"]},{"t":"送耿少府","f":"七言古诗","c":["白沙岸上相逢时，困倚栏干醉似泥。","忽然听君诵新作，酒肉顿觉寒风吹。","今朝邂逅芜江涘，大轴蒙贶东城诗。","雷惊电掣露怪变，山崩海泻能扶持。","令人壮观不知己，倦翼欲接青云飞。","逸驾固当出尘滓，胡为一命东南驰。","洞庭波澜洗天吼，衡岳葱苍挂南斗。","穷幽历险诗魂醒，不倦青衫困趋走。","屈原贾谊杜子美，白骨荒丘今在否。","款骑瘦马一吊之，满眼斜阳入疏柳。","诗成寄我慎勿迟，侧望阳春活残朽。","暂时离异何足论，酩酊江楼一樽酒。"]},{"t":"送徐长官","f":"词","c":["徐夫子，能谈经。","不学俗儒事章句，白首役役劳骸形。","我尝洗耳听其说，寒泉漱玉声珑玲。","十年茅塞一朝拔，四体自豫神安宁。","交游得君已恨晚，历阳几日同醉醒。","新诗百韵忽赠我，满纸落落排明星。","使我目睛眩，又若遭雷霆。","自愧久灭没，安足烦褒称。","李翰林，杜工部，格新句老无今古。","我驱弱力谩继之，发词寄兴良辛苦。","几欲攀天门，击天鼓，女娲有志终难补。","低头帖耳逐驽骀，倒着青衫走尘土。","东风吹破江头春，绿杨红杏能笑人。","狂来且尽一壶酒，世无贺老谁相亲。","君今别我又远适，锦帆千丈迷空碧。","飘然去意凌昆崙，自古雄豪少知识。","我亦从今不复言，静看澄江浸寒璧。"]},{"t":"送李节推","f":"七言律诗","c":["昨对桃花与君别，共唱离人眼中血。","今见桃花君复来，似与东风趁时节。","北去南还何日休，书生道路多穷愁。","安得巨航满载酒，一帆风过蓬莱洲。"]},{"t":"送李察推","f":"七言古诗","c":["去年遇君陵阳峰，杜鹃声乱桃花红。","佳人玉指接玉板，劝我一醉三百钟。","醉来骑鲸赴瑶阙，不记当时与君别。","溪上扁舟破雪归，楼前芳草还春发。","白头太守重相过，开樽大笑呼琼娥。","向来十客七已去，唯与杜九闻清歌。","歌声绕梁离思苦，听不得终泪如雨。","回首茫茫天地中，聚散百年能几许。","今朝此地重相逢，秋汉无情江月空。","把酒与君须醉倒，已知后会皆衰翁。","陵阳乐事那复得，官贱食贫身愈迫。","击剑高吟非故乡，何时共作沧浪客。"]},{"t":"送姚太博","f":"词","c":["春风动地吹春去，行人不肯江边住。","片帆朝挂暮千里，烟雾苍茫宿何处。","夫君少年日，射策明光宫。","同时得意三百辈，上林曾醉桃花红。","十馀年间事超忽，几在青云几白骨。","君虽未甚荣，亦足有馀乐。","存心不负圣与贤，何须画影凌烟阁。","浔阳城头北楼壮，邂逅相逢观暝涨。","鱼龙奔走势莫分，却忆当年兵火愁杀人。","至今战场无绿草，冤魂夜哭寒蟾老。","临风沥酒一吊之，而我浮生何足道。","聊为君行歌数声，青山截断江流平。","晴云相对似能舞，野鸟好语如吹笙。","却送闲愁付沧海，身虽离异心无改。","若到蓬莱王母家，为攀桃树遥相待。"]},{"t":"送陈屯田知明州","f":"词","c":["屈指宛陵客，八九名世贤。","我亦驾白鹿，往往登俊筵。","昭亭自作老龙斗，叠嶂不碍明河躔。","馀霞散绮入高阁，澄江似练拖晴天。","黄金买酒不论价，壮心共许青春前。","丞相初为部使者，精选邑治君尤先。","业闻上书后荐达，玉陛引对亲承宣。","付之一节使淮浒，三十二县刑无冤。","嗟予末路最流落，哭儿清泪双眸穿。","感君不弃半面雅，取之涸辙投深渊。","稍回生意渐奋发，遽复舍我摇归船。","明朝敕拜四明守，四明山水君所怜。","奈何岁旱天下歉，岂容醉卧沧溟边。","我疑帝命养头角，乘春霹雳惊蛰眠。","白蘋风静湖月满，谩吊贺公怀谪仙。"]},{"t":"送刘继邺秀才之岳阳访木尉","f":"词","c":["群鸟栖霜羽毛缩，孤雁冥飞何处宿。","芦花糁白天无声，灵妃鼓彻潇湘曲。","此时归梦寻故乡，谁道行人鬓长绿。","平生所得惟悲歌，时命未遇君如何。","满怀策尽献不售，凤凰飘泊无嘉禾。","困鳞不借一杯水，异时安用西江波。","岳阳高楼挂星斗，楼中子真闻旧友。","请舒和气邀阳春，便酿重湖作浓酒。","山叶撩乱舞，山鸟纵横啼。","古人交道贵终始，乐酣醉倒君莫疑。","否极泰来不可测，岂有壮士长栖迟。","岂有壮士长栖迟，青云歧路看横飞。"]},{"t":"送吴龙图帅真定","f":"词","c":["读书曾不学腐儒，腐唇烂舌肠焦枯。","又不学一诗一赋轻薄子，屑屑场屋名声沽。","西州治邑克肖古令尹，险欲临水投神巫。","政成召来御史府，弹駮庸相请赐雷霆诛。","奸邪缩手不敢更侮祖宗法，又荐处士博士登石渠。","富财治水各称任，乃仗斧钺临湘湖。","兴学首教士子弟，作碑后吊屈大夫。","明年易节帅瀛莫，铁甲百万秋防胡。","公曰承平勿誇武，解藏弓剑宽民租。","诗筒交迎两朝使，镌金刻玉论欢愉。","深沈不动若山岳，节制似公谁可俱。","少年天子圣虑远，却顾南国成荒墟。","拜公学士往绥抚，曾未期月富民大姓争来居。","秦淮桥倾滞行迈，顷刻指画穷精粗。","斩材叠岸役兵校，一物不向民间须。","月光激水夜景午，长虹矫矫当通衢。","回思昔人政事美，尽求形像堂中图。","二十二人最豪杰，森森玉树临冰壶。","前题姓名后书赞，文章彷佛窥典谟。","昨朝除命下金阙，再备将印严边枢。","南民遮道留不得，老幼挽缆相携扶。","愿言早入天朝作丞相，调燮水旱苏寰区。","功成异日保身退，西江秋风熟鲈鱼。","犛尾黄雀更珍绝，白糯酿美倾醍醐。","醍醐一饮三百盏，琵琶啄木唤舞姝。","舞姝十八如明珠，石榴殷裙蝉翼裾。","舞彻轻汗潭香肤，桃花带露燕脂濡。","綵衣班班罗凤雏，问公此乐世有无。","此乐世有无，何必更访蓬莱山上神仙都。"]},{"t":"送朱王二秀才归江西","f":"七言古诗","c":["冰霜冻海海水黑，云雾崩腾大空塞。","饥猿哀啼虎噤啸，高鸿折翅鹰敛翮。","苦寒大苦吾正愁，二子胡为千里客。","自言失意西南归，十斛明珠已空掷。","庐山摩天瀑布雄，请把肝肠洗愁寂。"]},{"t":"送沈司理赴阙改官","f":"七言古诗","c":["捕寇治狱皆有闻，才力纵横真出群。","荐书交上三岁满，玉陛引对瞻吾君。","胸中策画烂星斗，笔写纸上虬龙奔。","完创补弊有捷理，此时歧路挐青云。","云霄问谁作霖雨，愿洗边城血中土。","和气油然熟禾黍，天下蒸黎免穷苦。","男儿事业当致主，我独沈沟亦无语。","离亭愁怀安可数，春风自在花飞舞。","船尾插旗轰画鼓，掺袂青山遮别浦。"]},{"t":"送方奉议倅保德","f":"七言古诗","c":["太行积雪三千尺，浑河连天厚冰塞。","天台词人不畏寒，携家直赴并州北。","越罗蜀锦置筐箱，狼帽毡裘付妻息。","边城虽道无战尘，塞草从来少春色。","马上题诗泣鬼神，何时归奏平戎策。","我欲为书叩相阍，唤取斯人侍君侧。"]},{"t":"送王主簿弃官归建昌","f":"七言律诗","c":["老着青衫羞望舶，自笑风船禁不得。","拂衣高咏归去来，我有麻源三亩宅。","朝餐太阳茹紫芝，时时更作方平客。","肯嗟垂橐少黄金，儿孙只用传清白。"]},{"t":"送陈大夫罢太平守还台","f":"七言古诗","c":["去年秋暮送东玉，今岁春残送子仪。","人生不老安可得，况复年年伤别离。","请说湓江初识面，已知磊落胸中奇。","桐乡之会愈相乐，是时解印予言归。","公乘扁舟过溪口，殷勤访我论新诗。","君章下车始命客，邀公与我同遨嬉。","开怀醉倒信莫逆，十年一梦音尘稀。","忽闻公来守吾土，馀生幸获仁贤依。","政成无扰威惠浃，白驹驰隙临瓜期。","梨花夺月烂银白，绘盘缕玉江鱼肥。","酒倾碧盏盏尝满，曲度晴云云不飞。","车轮未许生四角，且愿逆风东北吹。","留连更尽一壶酒，无使醒泪沾行衣。","十科应诏公第一，出入省寺非公谁。","欲陪后会定何许，咄嗟自此分云泥。"]},{"t":"峨嵋亭即席再送","f":"楚辞体","c":["长江奔来一山裂，两岸崔嵬耸双阙。","石人空老薜萝衣，夜夜孤猿啸寒月。","斯亭谁作名峨嵋，颦翠含愁惜离别。","浮生后会难再得，况复相看头雪白。","停杯执手聊逡巡，画鼓铜钲莫催客。","客行西望紫皇家，紫皇真人驾龙车。","海若驱鲸上金钓，玉女挟春妆宝花。","千官称觞祝天寿，箫韶九成奉肴酒。","青霄阔步随鹓鸾，肯向江头恋杨柳。","杨柳花飞春日迟，登峨嵋兮送君归。"]},{"t":"留别宣城李节推","f":"词","c":["君作宣城幕下吏，我尝筑室青山址。","三四相逢五六年，交情淡若秋江水。","水流到海无穷时，吾辈论交无衰期。","明主可结亦未晚，谢安四十功非迟。","低头感事复太息，汲汲功名亦何益。","君不见屈原言直沉湘水，韩信功高亦诛死。","穷达无过七十年，事业空存一张纸。","不如饮酒临春风，溪水绿净山花红。","金丝玉管乱两耳，一醉三百琉璃钟。","醉来辞君登海槎，四方上下皆吾家。"]},{"t":"投别发运张职方","f":"词","c":["萧萧乾叶欲辞柯，晓来更奈严霜何。","明知飘泊不得已，请君试听离人歌。","生平学尽经济策，宗工大匠亲琢磨。","三入长安献不售，困鳞怅望西江波。","感君聊借一杯水，六月炎蒸免枯死。","高谈雄辩为我倾，古恨今忧对君洗。","卖薪给家妻子羞，淮阴胯下未封侯。","故人骑龙不相助，子陵自欲追巢由。","拔山力尽真可伤，江湖安得重相忘。","恩仇必报乃壮士，如今孰是韩张良。","玉手纤纤把金盏，更听新声碎瑶板。","醉乡酩酊万事休，功名难成岁华晚。","噫吁嚱，秋风已老白云飞，乡关咫尺未能归。","倚瑟而歌悲帝子，南山遥望泪沾衣。","愿君闻此颇矜恻，许借长帆还泽国。","他日尧阶荐姓名，投老犹能奉鞭策。"]},{"t":"酬吴著作","f":"七言古诗","c":["醉乘黄犊穷山河，倏然遂向桃源过。","桃源尽处见城郭，万家欣欣闻弦歌。","主人喜扫溪上榻，爱我鬓发尘埃多。","旋呼琼液注玉斝，麟孙出拜能吟哦。","使令劝我须醉倒，不知与世为谁何。","醒来忽别未十日，敢期佳句传灵波。","千年不落一字俗，凛凛秋风吹太阿。","大才小用小有补，牛羊茁壮馀无他。","何时赴诏玉京去，万物待子能调和。"]},{"t":"康王洞呈同游讷禅师","f":"楚辞体","c":["康王洞口无尘埃，青山崭岩水邅回。","飞桥百尺渡天险，下听谷响如奔雷。","凭栏要识物外物，泬寥寥兮何有哉。","但见东阜耸楼阁，碧瓦鳞鳞何崔嵬。","虹电披猖雨新歇，金云点缀芙蓉开。","斜阳疏光照不入，异景万变谁能裁。","仙家遗象已可爱，是时况与禅宗来。","瞳人照耀骨森竦，皎如皓月凌寒梅。","险句卷起谷帘水，真珠万斛收苍崖。","猿不能啼鸟无语，巨石枯木为之摧。","达即善用用即妙，斯游何异登蓬莱。","回头碌碌利名士，日蠹日朽令人哀。"]},{"t":"酬李推官淮上见寄","f":"七言律诗","c":["霜寒水落平沙露，短艇悠悠寻泊处。","惊弦旅雁失群飞，贪饵修鳞随网去。","世情翻覆可沾巾，三千食客背田文。","不须更待年华老，便向东山卧白云。"]},{"t":"南雄除夜读老杜集至岁云暮矣多北风之句感时抚事命题为篇","f":"词","c":["岁云暮矣多北风，怒嗥万里吹惊鸿。","只今我亦在行旅，陟彼庾岭临苍穹。","霜寒不复瘴雾黑，酒贱颇得樽罍红。","鼓角看看变新律，烛泪璀璀随残冬。","一阶寄禄百无补，白发又送年华终。","鬼章虽获万国贺，防边未可旌旗空。","中原将帅谁第一，愿如卫霍皆成功。","庙堂赫赫用耆旧，熟讲仁义安羌戎。","我甘海隅食蚌蛤，饱视两邑调租庸。","呜呼不独夔子之国杜陵翁，牙齿半落左耳聋。"]},{"t":"广州越王台呈蒋帅待制","f":"七言古诗","c":["番禺城北越王台，登临下瞰何壮哉。","三城连环铁为瓮，睥睨百世无倾摧。","蕃坊翠塔卓椽笔，欲蘸河汉濡烟煤。","沧溟忽见飓风作，雪山崩倒随惊雷。","有时一碧渟万里，洗濯日月光明开。","屯门钲铙杂大鼓，舶船接尾天南回。","斛量珠玑若市米，担束犀象如肩柴。","越王胡为易驯服，陆生辩与秦仪偕。","当时贡物竞何有，汉家宫殿今蒿莱。","邦人每逢二月二，熙熙载酒倾城来。","元戎广宴命宾客，即时海若收风霾。","群心愈喜召和气，百伎尽入呈优俳。","乐声珊珊送妙舞，春色盎盎浮樽罍。","鬼奴金盘献羊卨，蔷薇瓶水倾诸怀。","嗟余老钝已茅塞，坐视珠履惭追陪。","青蝇何知附骥尾，伯乐底事矜驽骀。","番禺虽盛公岂爱，亭亭自是岩廊材。","千年故事写长句，指画造化回枯荄。","昌黎气焰遂低缩，瓦砾未足当琼瑰。","仙姿劝公莫妄想，元鼎久待调盐梅。"]},{"t":"蒲涧奉呈蒋帅待制","f":"七言古诗","c":["菖蒲涧底生九节，流水遂作菖蒲香。","安期服之已仙去，漫脱双舄留秦皇。","秦皇杀伐自无度，年龄社稷何由长。","蓬莱毕竟不可见，十祠千载聊相望。","散发追之又无迹，后来诡谲传崔郎。","至今正月二十五，城北夹道珠帘张。","元戎要宾锤大鼓，老蛮献馔烧肥羊。","倾城尽作蒲涧饮，美俗眷恋神仙乡。","穿云丝竹度别浦，绕山金翠明残阳。","我乘款段到已晚，越台仅得参壶觞。","公携大句使我读，冰澌戛齿清琅琅。","张侯继作亦精敏，兰茝相倚传芬芳。","却寻陈事考僭迹，死佗称帝鋹称王。","基山控海恃远崄，大明一出旋消亡。","岂如戴主效臣节，白骨虽朽忠名彰。","只今神孙太母圣，天下击壤歌时康。","佳期不邀墓中鬼，乐民之乐真循良。","勒词苍崖告万古，蒲涧之会无淫荒。"]},{"t":"石屏台致酒呈蒋帅待制","f":"七言古诗","c":["石屏台下玉池水，绕岸石屏青齿齿。","镌劖初自人力成，一石十牛车不起。","辇置应须费万金，园囿森罗供宴喜。","苍藓昏埋岁月远，修藤缠络根相倚。","刘鋹族氏已无馀，此物犹存旧基址。","曾经战鼓轰雷霆，屡对春风阅罗绮。","老榕交阴不透日，客袂生寒冰雪洗。","小桥断处栈梯连，一线崎岖劣容跬。","未知深窟藏龙蛇，但见枯荷阁蝼蚁。","摩挲题字考前人，名姓班班少奇伟。","请公椽笔赋大篇，歌颂永平诛僭拟。","光焰须令万丈长，一时行乐何足纪。"]},{"t":"朝汉台寄呈蒋帅待制","f":"七言古诗","c":["鹿入望夷秦欲灭，真剑先流白蛇血。","尉佗椎髻尔何为，漫占海隅蛟蜃穴。","祝融之符天下归，岂假陆生三寸舌。","千金装橐未为多，更上高台拜尧阙。","至今人说朝汉台，不知此地藏蒿莱。","使君好事一登赏，譬若古镜初磨开。","香炉烟生石门晓，三山翠拥浮丘来。","风松自作笙箫响，暮霞却捲旌旗回。","长空无碍鸟无迹，人事宁须问今昔。","琼浆且泛琉璃船，满眼夕阳留不得。","登台何似登金门，烂吐文章侍君侧。","愿公归作老姚崇，莫学江东穷李白。"]},{"t":"白玉笙","f":"词","c":["白玉笙，咸通十三年琢成。","琢成匠人十指秃，进奉明堂声妙曲。","当时应赐恩泽家，流传至煜煜好奢。","高堂日日听吹笙，不知国内非和平。","仁兵万众一旦至，国破苍黄笙堕地。","虽然讹缺未苦多，却落人间为宝器。","管长纤纤剥笋束，况值吴姬指如玉。","不见排星换掩时，自然天韵来相续。","昔时祸乱曲，今日太平歌。","兴亡不系白玉笙，但看君王政若何。"]},{"t":"金熨斗","f":"词","c":["金熨斗，酌醇酒。","熨开万斛之愁肠，赠尔千年之眉寿。","酣酣笑脸坐生春，安用逢人嗟白首。"]},{"t":"翠碧杯","f":"词","c":["翠碧杯，满酌正是桃花开。","一年三百六十日，几人待得春归来。","春归来，不饮酒，翠碧之杯尔何有。"]},{"t":"魏王台","f":"词","c":["金城东，百尺高台临远空。","长江浩荡剑门险，欲平吴蜀难为功。","谁倾黄金建佛庙，击鼓撞钟夜还晓。","香厨供办老僧閒，玉栏花谢游人少。","我来独立想英雄，战舰连云气概中。","犹有斯台存旧址，可怜铜雀起悲风。"]},{"t":"藏舟浦","f":"词","c":["金城北，荒荒野水连云白。","岛屿相望一径通，绕堤杨柳迷春色。","天下三分血战秋，张辽凿浦暗藏舟。","吴蜀虽亡晋已起，山川自结寒烟愁。","永平只作寻春处，关门锁断春归路。","画船载酒歌白纻，不忍醒时送春去。"]},{"t":"悲阳春","f":"词","c":["悲阳春，阳春可乐胡为悲。","桃花枝上开未足，数片已逐狂风吹。","阳春能来不能久，年少看花今白首。","击毬驰马力已疲，欲傍樽罍先怕酒。","佳人如皓月，顾我犹衰蓬。","相倚不相似，两心何可同。","请折并蒂花，更看鸳鸯鸟。","容华与毛羽，相鲜乃为好。","挥手谢佳人，浩歌悲阳春。","阳春易衰歇，尔貌岂长新。"]},{"t":"江上游","f":"七言古诗","c":["我乘逸兴浮扁舟，杨花渡江飞满头。","河豚初熟鲚鱼烂，借问春光须少留。","人间乍听黄金鸟，物外谁怜白雪鸥。","但愿沧波化为酒，青山两岸皆糟丘。","人生快意天地小，登览何必须瀛洲。","渔歌声断自起舞，酩酊更看江月流。"]},{"t":"望夫石","f":"词","c":["杜鹃啼血春林碧，妾有离愁异今昔。","上尽高山第一峰，目乱魂飞化为石。","化为石，可奈何，泪悬白露衣薜萝。","千古万古望夫恨，一江秋水寒蟾多。","汉家天子点征役，良人荷戈归不得。","此身未老将何从，不似山头化为石。"]},{"t":"两山间","f":"七言律诗","c":["江南南山连北山，苍藤翠水水潺潺。","水深藤老木拱矣，不知游子何时还。","白云孤飞岁华晚，独鹤一声星斗残。","两山秀色手可揽，嗟我不得山中閒。"]},{"t":"莲根有长丝","f":"词","c":["莲根有长丝，不供贫女机。","柳梢有飞绵，不暖寒者衣。","朝歌悠悠暮歌短，下地沉沉上天远。","东生白日还西流，志士长怀万古愁。"]},{"t":"朝出青闺里","f":"词","c":["朝出青闺里，自汲井华水。","井水如磨铜，妾面似芙蓉。","照影返自叹，净洗铅华浓。","郎骑白马玉关去，令人绣被冷春风。","春风欲尽来何迟，蚕蛾散子鸦哺儿。","写得短书无寄处，幽恨填膺泪如雨。"]},{"t":"苦雨行","f":"七言古诗","c":["阴风黑塞云漫漫，虚空昼夜腾波澜。","群龙淫怒烦神官，银河源源来未乾。","日月暗行天岂安，地下万物泥潦汍。","角鹰快鹄摧羽翰，小鱼为凤蛙为鸾。","君子有忧心盘盘，欲上问天造化端。","苍天无路不可干，哀歌空屋声何酸。"]},{"t":"晓晴歌","f":"词","c":["霜风刮刮侵人肤，宿云卷卷归江湖。","天开碧幕万里铺，飞出东来三足乌。","羽毛浑丹光焰敷，地下万物冻以舒。","我今踊跃行樵苏，白粳可籴酒可沽。","乌为母，吾为雏，致我之暖，令我之餔，嗟不能报乌区区。"]},{"t":"麟州叹","f":"七言律诗","c":["边兵不觉西人至，麟州仓卒城门闭。","城中带甲仅防城，城外生灵任凋毙。","元戎底事不防秋，千里郊原战血流。","谩说知兵范仆射，未免君王西顾忧。"]},{"t":"云月歌 其一","f":"七言律诗","c":["白云微散月华生，月下白云和月明。","白云犹解背人去，明月只知随我行。","我行不停月未落，心期白云出寥廓。","披云揖月邀嫦娥，愿携素手濯银河。"]},{"t":"云月歌 其二","f":"七言律诗","c":["月下听吟云月歌，歌声寥亮舞婆娑。","劝君一酌千万寿，今宵云月情偏多。","不知云月谁为主，愁看月落云飞去。","愿如明月有圆时，不学白云无定处。"]},{"t":"劝酒二首呈袁世弼 其一","f":"五言古诗","c":["湛湛酒杯绿，酣酣炭炉红。","佳人放玉板，拂镜照芙蓉。","四海无波澜，吾曹方宴閒。","大笑凌白日，高吟动南山。","百岁能几何，会少别离多。","少年嗟贾谊，壮士忆廉颇。","不如醉魂魄，冠巾任倾侧。","冥然逍遥乡，杳与尘寰隔。"]},{"t":"劝酒二首呈袁世弼 其二","f":"词","c":["阴云蔽白日，长风卷惊涛，江上峥嵘百怪嗥。","挽君船缆劝君住，且饮百盏之醇醪。","吴姬笑脸如樱桃，鲤鱼红丝落霜刀，醉来不识天为高。","共君攀天跨鲸鳌，下视万物皆劳劳。"]},{"t":"牡丹吟","f":"七言律诗","c":["三月金张启仙馆，百种名花此尤罕。","昭君晓怯胡地寒，太真昼卧华清暖。","梦为庄叟蝴蝶狂，散作襄王云雨短。","莫笑空山芝与兰，冷艳不随金剪断。"]},{"t":"左真观","f":"七言律诗","c":["逸士骑鱼入沧海，石坛遗迹今犹在。","桂烟散景夜寥寥，玉露凝华春璀璨。","重来旧隐经几年，挈笠携锄姓名改。","主人不识何当留，墨洒梁尘烂星彩。"]},{"t":"杂言寄耿天骘","f":"词","c":["耿夫子，闻悬车。","齿清发绀殊未老，璨璨满腹怀明珠。","耻随黄雀啄官粟，矫翼直与冥鸿俱。","东城之下，言还旧庐。","田有秫稻，池有嘉鱼。","林有美木，圃有青蔬。","笑傲樽俎，俯仰琴书。","与其折腰以群辱，孰若洁身而自娱。","予将蹴滔天之高浪，跨横海之长鲸。","揽午夜之明月，邀逸驾于赤城。","酌王母之琼液，献商皓之玉觥。","于是挥手景驻，长啸风生。","投冠缨于下土，化鳞鬣于北溟也。"]},{"t":"琅琊行","f":"词","c":["琅琊异他山，坡陀晦诸峰。","惟有山下水，其源与天通。","寻源见楼阁，鸳瓦青重重。","宝镜递华灯，空岩散疏钟。","薰成香积界，回首非尘笼。","阳冰俗篆未足数，禹称八咏元无功。","我来独酌惜已晚，醉倒不见欧阳公。","摩挲苍崖读旧记，谁掣玉索缠蛟龙。","不忧石泐解磨灭，斯文自与元气同。","徘徊落日跨马去，老松为我摇悲风。"]},{"t":"交难","f":"词","c":["马萧萧，车轣轣，道上行人半相识。","识面虽多心友难，沧海可量人莫测。","君不见张陈昔日刎颈交，临阵弯弓返相射。","又不见坐中耳语程将军，背骂一钱犹不直。","噫吁嚱，休休休。","猿鸟可为伴，麋鹿可与游。","春日晴晖晖，春风思悠悠。","春泉滑涓涓，春林碧柔柔。","行止任所适，歌啸忘吾忧。","逢人辄掩口，语发多为雠。"]},{"t":"杨白花 其一","f":"词","c":["池水满，宫柳长，胡地沙晴日色黄。","自知憔悴容华改，朝来临镜懒梳妆。","却寻携手旧游处，拾得落花空断肠。"]},{"t":"杨白花 其二","f":"词","c":["秋风起，黄叶飞，宫门深锁日还西。","背人一去音书断，塞雁无情亦解归。","此恨此愁无处托，暗尘消尽缕金衣。"]},{"t":"灵芝宫","f":"词","c":["灵芝宫，乃在沧海之上，白云之中。","楼阁缥缈金间碧，玉花露湿香随风。","寒光长瑩别有月，笙箫间作春冲融。","来时不记梦中路，觉后唯闻长乐钟。","神仙谁云与世隔，暂游复返精诚通。","倏然物化岂真往，举杯彷佛声传空。","蓬莱异馆信非妄，罗池庙食今犹丰。","仕途机阱了可畏，天地虽广身不容。","低催至死寄僧榻，旷达一念超樊笼。","挥毫不似人间世，想见光焰如长虹。"]},{"t":"圆山谣","f":"七言古诗","c":["庙食圆山忘岁年，自言耽酒未能还。","身披羽衣手提药，时时混迹来人间。","七言四句又奇绝，固非俗士能追攀。","蓬莱却在漳水上，鳌头突起沧波环。","长萝秀木锁春色，石泉自泻秋声潺。","伊予来漳四十日，始造秘殿瞻威颜。","归鞍未解疾遽作，寒气束缚形骸跧。","夜梦青衣捧玉盘，琉璃十颗传灵丹。","欣然投齿咀三四，若饮沆瀣生修翰。","精神顿觉枕上醒，五鼓未送蟾光残。","明朝视事若平昔，僚吏争贺询其端。","真仙垂祐必终始，凡骨岂易当珍丸。","便思勇决谢尘网，往跨皓鹤参翔鸾。","吟诗卖药同至乐，安用包羞拘一官。"]},{"t":"芳草渡","f":"七言律诗","c":["落日渡头芳草碧，伤如之何送行客。","客行无尽草相随，塞北江南同一色。","秋霜野烧年年事，绿芽迸地先春力。","芳草多情不变常，行人自去无消息。"]},{"t":"我归矣","f":"词","c":["我归矣，江之南，一蓑一钓桃花潭。","桃花潭水深千丈，金鳞尾尾密如蚕。","得鱼辄笑放鱼去，我不贪饵尔何贪。","移船就月还一饮，天为方床月为枕。","水红芙蓉烂云锦，醉则纵横看花寝。","看花寝，如之何，向来忧患付烟波。"]},{"t":"卧龙山泉上茗酌呈太守陈元舆","f":"词","c":["君不见，欧阳公，在琅琊。","酿泉为酒饮辄醉，自号醉翁乐无涯。","醉来落笔驱龙蛇，电雹万里轰雷车。","浓阴却扫吐朝日，草木妍媚春争华。","斯人往矣道将丧，虽遇绝景谁能誇。","又不见卧龙山下一泓水，源接银河甘且美。","惜哉无名人不闻，唯有寒云弄清泚。","君携天上小团月，来就斯泉烹一啜。","不觉两腋习习清风生，便欲飞归紫金阙。","挽君且住君少留，人生难得名山游。","汲泉涤砚请君发佳唱，铿金戛玉摇商秋。","斯泉便与酿泉比，泉价诗名无表里。","自愧学诗三十年，缩手袖间惊血指。","君如欧阳公，我非苏与梅。","但能泉上伴君饮，高咏阁笔无由陪。","明年茶熟君应去，愁对苍崖咏佳句。"]},{"t":"酬运判毛正仲","f":"七言古诗","c":["明公青霄我平地，才不超群怀厚愧。","小邦苟禄度残年，侧望车尘掩玼疠。","海浪翻云古渡头，感公为我须臾留。","请说相逢在何处，上下梅山成昨游。","忽得新诗惊老格，飘飘真是金门客。","蹇驴已困何由攀，一夜微吟添鬓白。"]},{"t":"奉和运判吴翼道留题石室","f":"七言古诗","c":["双峡天开控江水，水自䍧牁来万里。","端州正在双峡间，石室嵩台压孤垒。","谁倾北斗酌明河，化作七山平地起。","修萝高张翠羽盖，锦壁深藏赤凤髓。","鸣禽交应杵臼声，驯鹿见人行复止。","一洞能容百两车，三溪却接沧溟底。","仰瞻圆顶碧玲珑，傍穿小窦阴迤逦。","不应融结施镌镵，浪磅乳滴何年始。","森然物象难悉名，古图脱落犹堪比。","老龟闯首龙缩角，猛虎磨牙鲸卷尾。","又如壮士披肺肝，戴主之忠死无已。","苍崖题字多唐人，彷佛银钩唯二李。","山祇不放云雾开，海神屡汲蟾光洗。","欧阳古录遗此碑，我渍香煤传以纸。","寂寥相望三百年，乃有高才继瑰玮。","滁阳吴公富文采，来拥皇华宣使指。","霜威暂霁持谦尊，许接清游携酒醴。","长丝千结盘彫梅，簌簌并刀脍赪鲤。","寻仙未遇饮正豪，落日岚烟催返轨。","明朝大句挥长篇，戛玉锵金轰两耳。","有灵持护归羊城，论价欲酬谁可拟。","蒋公毛公并诗伯，笔阵酣战秋风里。","越台朱明被题遍，鹄奔此洞重新美。","沈侯湘寺陪俊游，韩子连山书宴喜。","胜概遂令天下知，名齐五岳无由毁。","自怜羽翮久零落，只欲卑飞藏棘枳。","漫将俚语续公歌，投老那知遇知己。"]},{"t":"奉和广帅蒋颖叔留题石室","f":"七言古诗","c":["西江赴海穿双峡，十里寒青半天插。","晴空倒影连明河，滔滔不碍鲸鱼呷。","绞绡高覆紫微冠，翠簟平铺玉皇榻。","中藏石室与嵩台，巨壁棱层老鳞甲。","欲飞未去凤逶迤，将蛰还伸龙匼匝。","浪摇蓬岛何其危，桂塞广寒无乃狭。","大匠不由基构成，洞门大启无人扃。","六月来游乃挟纩，酌酒向口疑冰生。","三溪诘曲愈难涉，举烛但爱烟溟溟。","返似霜缣见山水，画手只许吴生是。","有谁文采如昌黎，物物为我从头记。","自惭才短空冥搜，俚语未足苍崖留。","元戎闻之索大笔，默坐远想书胜游。","凭凌风力若捕虎，窘束景象如缚仇。","那知子厚号雅健，不识谢守为风流。","桓桓斯人富学海，少陵重生谪仙在。","琮琤击玉敲黄金，倚马千言未尝改。","高下岂必世俗知，浩气已充天壤内。","又如淮阴善将略，不战能令敌先败。","暂辞侍从来东南，羊城异日为傅岩。","不唯巴笺吟咏足，即看玉牒功名镵。","滁阳吴公昔曾赋，落落文华精注措。","毛侯亦许送和章，马上横戈写长句。","孰云高要陋且遐，三篇入石神鬼嗟。","愿挥硬画夺剑戟，下视鸟迹初遗沙。","此心虽大虑转小，刻就颇忧龙作蛇。","譬之博奕仲尼与，群儿恶用相识哗。","端溪石工古称妙，年年琢砚供正衙。","刚刀截碑易于砚，龟螭相射生彤霞。","岐山石鼓久缺矣，苦县光和真瘦耶。","流传万本入中国，谁怜此乐瘴水涯。","共探泉石造淡漠，岂忆冠盖追荣华。","公思归乎欲致主，四方飘泊予为家。","予意无留亦无去，等将幻质随杨花。"]},{"t":"奉和梧守蔡希蘧留题石室","f":"七言古诗","c":["叠石棱层万寻碧，老仙自作琉璃宅。","翛然一径出人寰，北斗三台无咫尺。","大岩杳杳吞沧溟，小窦疏疏吐朝日。","芙蓉羃沥乳成花，鳞鬣摧颓龙蜕骨。","危弦脆管递仙飙，烂锦轻绡变云物。","二李能书玉钮悬，僭鋹未是真王质。","人亡国变今几年，唯有文章记崷崒。","胜游况遇中郎孙，诗拟杜陵相彷佛。","洪河喷作三门流，突骑长驱五千匹。","令人惊嗟但缩手，近世雄豪无此笔。","不唯险韵难追攀，学道输君先得一。"]},{"t":"奉和蔡希蘧鹄奔亭留别","f":"七言古诗","c":["栏干去天无一尺，帘外三山蘸天碧。","樽倾浊酒延故人，拂拂轻寒添暮色。","双鹄飞奔迹已陈，满庭细草自涵春。","孤城不复有冤气，法座垂衣逢圣神。","惟君万里分符去，苍梧之邦舜游处。","九疑七泽皆相连，墨海濡毫写长句。","又如李白才清新，无数篇章思不群。","挺特千松霜后见，孤高一笛陇头闻。","我于诗学非无意，黄芦不并琅玕翠。","漫甘薄禄养残年，两鬓垂丝成底事。","声出还吞泪如雨，同气相求别离苦。","老来频寄一行书，江边鱼雁无今古。"]},{"t":"南安刘太守席上劝曾叔达酒","f":"七言律诗","c":["金盏莫辞琼液满，宝檠休嫌灯焰短。","圆荷翻雨碧云香，小妓近人红玉暖。","百年流转能几时，一日相逢须款款。","扁舟明发下前滩，此会清吟应亦罕。"]},{"t":"劝君归示南康太守吴子正","f":"词","c":["劝君归，腰下悬金禄及儿。","家有良田秫稻肥，种菜结实栗与梨。","江山满目烟云披，长年之乐吾无羁。","何须七十乃言归，行将七十能几时，分符持节力已疲。","才德及人固无尽，此身抱病欲何为。"]},{"t":"槠溪重九阻风戏呈同行黎东美","f":"词","c":["不登高，不饮酒，漠漠黄沙翳衰柳。","扁舟系缆未敢行，江头白浪蛟龙吼。","故园菊花应烂漫，客路无穷但搔首。","却忆齐山小杜歌，人世难逢笑开口。"]},{"t":"左蠡亭重九夕同东美玩月劝酒","f":"词","c":["平生看月无今宵，一亭危在山之椒。","下瞰扬澜连左蠡，白琉璃地覆鲛绡。","欲披锦袍搥鼓过，世无贺老谁相和。","屈原憔悴湘水滨，夷齐自守西山饿。","且来登高望明月，拂拂霜风濯烦热。","身心都在清凉宫，一点无尘光皎洁。","与君同游执君手，况逢令节当重九。","不忧短发还吹帽，头上有巾先漉酒。","饮醇酒，望明月。","我归姑孰溪，君赴黄金阙。","明年此会知谁健，细看茱萸莫轻别。"]},{"t":"将游五峰度夏代别倪倅敦复","f":"七言古诗","c":["六月执热思云泉，五峰参差如绀莲。","修松杰柏上参天，老鹤栖唳哀猿悬。","嫦娥夜濯清冷渊，岩户晃白飞群仙。","胡不往矣逃尘缘，散发赤脚临风前。","高轩朱衣君自便，去住彼此遥相怜。"]},{"t":"和守讷上人五峰见寄之作","f":"词","c":["木杯足蹑浮惊湍，却爱五峰如戏鸾。","一锡飞来卓出苍玉髓，又有黄金百镒藏蒲团。","道人得道每如此，倏来忽往非生死。","丛林成就八百年，香厨日供三千指。","讷师今亦浮杯徒，问答言词泻秋水。","脱去儒冠披坏衣，一生长在名山里。","殷勤笑我骑鲸鱼，诗狂酒怪何时已。","七言哦罢欲无言，坐看峰头片云起。"]},{"t":"送上饶道士吴师韩复游淮西","f":"七言律诗","c":["水精之仙降人间，身披羽衣目澄澜。","或求福祸语必验，手中开阖阴阳关。","淮西太守喜宾客，鹤驾却欲乘风还。","劝君饮酒莫言术，龙虎收藏归抱一。"]},{"t":"重九日同修颙惠云二禅师游浮山访洪琏长老","f":"七言古诗","c":["邑城东南百馀里，穿尽荒山渡重水。","林倾路转大壑开，峭壁崔嵬半空倚。","上无勾连下无根，镌镵难成画难比。","回环岩窦碧玲珑，月华吞吐湖光洗。","石鼓昼鸣云雨垂，金鸡夜斗龙蛇起。","成公说法已千年，事载龟趺尚新美。","嗟予平生慕佛学，空洞忘机造玄理。","暂来福地神愈清，况接高禅挥麈尾。","晋颙悟道天下师，云琏声名自予始。","精蓝际会付三人，净众如归闻法喜。","今朝更结名山游，宝阁珠楼同践履。","达了无生无不生，一声猿啸清风里。"]},{"t":"龙眠行留别修颙禅师","f":"七言古诗","c":["桐乡山水天下名，龙眠气势如长城。","重冈复岭跨三郡，磐压厚地攒青冥。","东南佛寺号投子，寺门洞启原无扃。","雪峰三来道方契，凿井百尺穿重冰。","至今善利永不泯，辘轳夜转闻寒声。","慈济玄谈载金刻，龟趺鳞甲光荧荧。","谁忧怪变碎以斧，半落崖下莓苔青。","时移岁晚人事塞，高座窃据非真僧。","白云徒侣半凋落，泉石往往荒柴荆。","我来抉弊眼除眯，颙自寿至人天迎。","随车贝叶五千卷，宝藏突兀同时成。","张翁好施古亦少，助我福地还中兴。","老禅咒龙未三日，泉发石上吁可惊。","晨厨千僧用无尽，琅玕引溜何泠泠。","城中客少民事简，屡携茗酌来煎烹。","叩师玄关问至理，心地拂拭菱花明。","妙峰胜会岂殊此，迷即成凡随死生。","明朝官满重回首，别师写作龙眠行。"]},{"t":"留别金陵府尹黄安中尚书","f":"七言律诗","c":["扁舟载月入金陵，金陵尚书倒屣迎。","白发愧彼商山皓，青眼欣逢阮步兵。","开壶倾酒饮未已，卷纸连书吟不停。","愿如贺监怜太白，莫作曹公嗔祢衡。"]},{"t":"奉和安中尚书同漕宪登长干塔","f":"七言古诗","c":["揽衣登塔窥泬寥，黄金篆牌神所摽。","层梯转道二千尺，铃索交响风常飘。","天厨晓送阿育供，海月夜领飞仙朝。","南溟安在心欲化，九万一举期今朝。","我宋真人启阊阖，尧舜之运重昭昭。","佛老并儒鼎足盛，理归一善无烦条。","净缘胜赏固莫逆，足力强健朋侪要。","昌黎首唱城南句，东野继作芬兰椒。","诸公笔力斗颖发，七言纸上铿琨瑶。","聚沙叠甓付童子，秀实始自春之苗。","凌空得路未足恃，遇险惊魂安可招。","龙虎低沈凤鸟散，藉此弹压无祲妖。","四郊松柏列兵卫，万家弦管均咸韶。","广庄黔乌类蠛蠓，岁望已觉元鼎调。","晴川疏树历阳近，浮云蔽日长安遥。","贯轮巨木彻十地，斜飞八角穿重霄。","扶持故国肖父老，综领诸刹如孩髫。","循栏作礼共悲仰，绝顶进步谁腾超。","迹虽有为志颇壮，报且不尽功何辽。","挥毫题识未云毕，城头鲁角声迢迢。","兜绵铺舒换尘境，宝灯照耀银为桥。","乃知此会世稀有，请君审听长干谣。"]},{"t":"即席和酬金陵狄倅伯通","f":"七言古诗","c":["虎踞龙盘古名郡，势欲凌波予未信。","偶摇双桨下天门，白鹭三山随一瞬。","舍舟登岸青溪滨，濛濛柳眼初含春。","感君携酒唤小妾，要我一饮颓冠巾。","开怀猛酌宁辞醉，明朝且入梁朝寺。","刀裁赤量非扇迷，兴来欲跨横空使。","南风更送琳琅篇，明珠十斛投归船。","与君定交增浩然，谁谓此行垂橐还。"]},{"t":"治水谣","f":"七言古诗","c":["去年圩破官不救，阙食逋亡十八九。","今年大水如去年，民困适遭何令贤。","贤哉何令能治水，枪木编芦多准拟。","赏罚公平贫富均，赤脚亲临食亡匕。","每趋危垫必身先，往复连宵几百里。","浪头作恶工莫施，一拜能令二龙起。","白龙先去黑龙随，鳞鬣分明皆见之。","须臾浪定埂可禦，父老惊嗟咸涕洟。","西门投巫安足比，亦胜乘舆济溱洧。","活我生灵十万家，惠泽阴功浃神理。","天子临轩方用才，时时有诏搜草莱。","请歌何令能治水，愿采斯言献天子。"]},{"t":"游陵阳谒王左丞代先书寄献","f":"词","c":["布衣射策趋蓬莱，十年得志联三台。","怀仁附义天下悦，忠言屡叩宸聪回。","不唯尽赦息钱息，曾均惠泽覃枯骸。","先皇晏驾旧臣老，白云黄鹤空徘徊。","藩城六见换符节，直道自任宁嫌猜。","昭亭扶春入画戟，句溪洗月供吟杯。","佳宾三千集珠履，赤子十万登熙台。","玄晖比公固不足，我攀太白惭非才。","披云拂雾一何晚，泥滑不敢鞭驽骀。","明朝迤逦造宾榻，愿逢浩气吹寒灰。","玉上青蝇本无有，都人争望公归来。","公归来，至尊梦吉天颜开。"]},{"t":"谢王左丞惠冰酒十五斗","f":"词","c":["昨夕发姑孰，今朝泊敬亭。","轻云淡日天地暖，杏花吐萼梅飘零。","春光一瞬岂足赏，听公亹亹高谈倾。","昔年庭争动丹陛，君臣道合趋升平。","岩廊辞位已十载，气度杳杳涵沧溟。","公田种秫作新酒，槐槽旋注琉璃瓶。","不将歌舞效俗饮，时时一酌差独醒。","感公赠我十五斗，酒量安得如刘伶。","愿公归去庙堂上，尽使斯民醉醇酿。"]},{"t":"题横山陶弘景书堂寺","f":"七言律诗","c":["先生烧丹骑竹马，情恋萧公碧城下。","故物无馀只五泉，亦有松风伴潇洒。","谁来洗耳复洗心，寥寥千载闻遗音。","寺门不掩象灯暗，猿隔数峰时一吟。"]},{"t":"代先书寄庐郡朱龙图","f":"七言古诗","c":["杨花塞路春无声，鸣鸠唤妇留春晴。","扬鞭朝发浚遒县，卷帘暮宿金斗城。","城中主人汉贾谊，妙年射策都群英。","峨冠独立御史府，冰霜凛凛清朝廷。","忽乘白云渡银海，十年望阙心常倾。","只今淮西课异等，沉沉玉帐闲府兵。","神机照物辨毫发，提刀四顾新发硎。","行闻召节返西掖，至尊开阁思谈经。","岂容燕寝自颐养，画戟森卫清香凝。","陈公虽解豫章榻，白头重愧非徐生。","飘零渔艇荷蓑笠，揣摩旧学荒柴荆。","愿公一吐太和气，朽株岩下逢春荣。"]},{"t":"合肥李天贶朝请招钟离公序中散吴渊卿长官洎予同饮家园怀疏阁","f":"词","c":["一阁横空连野水，久客归来洗双耳。","二疏虽解散黄金，家园未必临清泚。","坐见纷纷烟雨入，千里潇湘画图湿。","鱼鸟相忘蒲荇深，两岸桃花为春泣。","钟离辞荣已三品，吴令早休今八十。","我亦弃官姑孰闲，邂逅相过手重执。","阁前旋解青板船，呼童移棹选清渊。","四人白发笑且饮，岸人疑是商山仙。","亦如贺监在东吴，醉下山阴弄镜湖。","月色莲香迷近远，且要李白骑鲸鱼。","古人今人乐如此，出处无瑕傲生死。","君不见功成不退人，重著蓝衫脱金紫。"]},{"t":"丽人曲赠钟离中散侍姬","f":"七言律诗","c":["发如盘鸦面如玉，飘飘罗袖长芬馥。","妙年得侍碧虚乡，自道一生心已足。","黄莺流语春日长，绿窗绣出金鸳鸯。","朝暮祝卿千万寿，不识相思能断肠。"]},{"t":"中书舍人陈公元舆以诗送吾儿鼎赴尉慎邑卒章见及遂次原韵和答","f":"七言古诗","c":["嚼君老句胜牛乳，又如旱稼濛甘雨。","龙眠一别鱼雁稀，几度看云与云语。","凤池摇笔赞帝龄，珠玑洒落黄金城。","鼻端去垩鬼胆破，霹雳轰车风雨惊。","事君以道非难事，不羡昔人囊有智。","柏梁屹屹汉庭材，宝鼎颙颙周庙器。","我在江湖寄此身，碧芦青荇远黄尘。","感君问我尚安否，病树前头万木春。","强汎月船追李白，无人爱客似田文。"]},{"t":"次韵和元舆待制后浦宴集三首 其一","f":"七言古诗","c":["往岁遭风洞庭浦，悔不携锄从老圃。","昨日金城逢故人，万丈虹蜺思一吐。","更在芙蓉池上游，桂枝为楫木兰舟。","舞妓相将棹歌去，疑是西施浣纱处。","皓腕翩翻雪藕丝，婉若游龙或惊鹜。","愿公对客少留连，早晚沙堤问归路。"]},{"t":"次韵和元舆待制后浦宴集三首 其二","f":"七言古诗","c":["欲飞太白嫌秋暑，约我留连菊花圃。","撷芳持酒听君吟，冰丝轧轧吴蚕吐。","只今且挈茗杯游，沧浪同泛采莲舟。","君当复入玉堂去，为吾还思采莲处。","叶间争看戏鸳鸯，花底谁曾爱鸥鹜。","柳州烟岛自迷人，员峤方壶岂无路。"]},{"t":"次韵和元舆待制后浦宴集三首 其三","f":"七言古诗","c":["谁为宓妃寻洛浦，且看芙蓉照秋圃。","烂漫折随罗袖归，芬香忍对西风吐。","官池不属野人游，画鼓喧喧驾鹢舟。","宾从欣陪史君去，筵开正在红云处。","独携椽笔发清唱，老鹤昂藏映鸡鹜。","敢辞倒载委篮舆，绛腊行行夹城路。"]},{"t":"醉歌谢太平李倅自明除夜惠酒","f":"词","c":["一年醉，三百六十日。","今朝年尽酒未尽，自顾形骸无得失。","浮生七十行六十，猛饮狂歌须汲汲。","吾邦倅贰李自明，爱我颓然荷蓑笠。","双壶满送琼瑶浆，春风争从四支入。","君不见刘项存亡安在哉，暂时龙虎轰风雷。","袁盎说行晁错戮，蹑蹝刺客横刀来。","又云舜野死，尧幽囚，九疑连延云雾愁。","不如饮酒醒复醉，抱瓮负锸渠无仇。","沧海化为酒，蓬莱作糟丘。","与君携手去，赤脚踏鳌头。"]},{"t":"同蒋颖叔林和中游郁孤台","f":"七言古诗","c":["匹马初从瘴岭来，登临喜上郁孤台。","郁然而孤插天半，乱山却出晴云堆。","双溪倒流玉绡飐，万屋蘸碧长城开。","扪参历井岂足数，俯栏引手持斗魁。","月空银浪试一酌，坐忧桂树生黄埃。","妙娥舞袖回白雪，琵琶十面轰春雷。","吟笺分轴造险语，酒令行赏无停杯。","哀猿不断片帆没，归鸟自送残阳颓。","脱身我作耕钓客，两翁均是岩廊材。","共游绝境发佳唱，骊珠射目精光皑。","升沈从此遂分手，愿借惠泽苏蒿莱。"]},{"t":"赠南康刘叔和秀才","f":"七言律诗","c":["俊才落落如君少，养之九年应大妙。","满怀骚雅辄见投，圭璧琮璜予所要。","劝君且学充其科，殿前笔陈挥长戈。","锦标夺取献天子，宠禄及亲荣耀多。"]},{"t":"姑苏行送胡唐臣奉议入幕","f":"词","c":["登姑苏，望五湖。","范蠡扁舟竟何在，吴王宫殿惟荒墟。","民贪吏狡郡多事，煮盐为盗无完肤。","使君谁何好平恕，宽则脂韦猛则虎。","只今卧治闻黄公，更得高才归幕府。","愿令里巷歌召南，风化流行成乐土。","昔年引对大明殿，国论轩轩动人主。","往持使节临朔方，威霁秋霜爱春雨。","玉上青蝇谁强指，鼻端白垩宁伤斧。","升沈偶尔非吾嗟，不用东方且为鼠。","岂闻绝代无佳人，何必西施妙歌舞。","盛倾绿酒鲙肥鲈，承诏还从大梁去。"]},{"t":"嵩山归送刘伯寿秘监","f":"楚辞体","c":["松荒菊老嵩山秋，翁将归兮邈难留。","幅巾短袖骑黄牛，翛然自作山中游。","山中游，谁与伴，两姬窈窕吹牙管。","千岩万壑鸾凤吟，嫦娥侧耳冰轮款。","五音和畅王道成，不是嵇康广陵散。","问公此曲谁为之，曲曲新翻公自为。","古人今人不到处，能与阴阳四序相推移。","我知公心通造物，岂止人间妙音律。","天子呼来换旧章，乐成四十有五日。","奏之明堂奉祖宗，天地清明和气溢。","至尊宠赐腰横金，自谓荣华非本心。","再拜辞魏阙，扬鞭归故林。","故林在嵩山，白云幽径深。","濯我衣上尘，重泻山水音。","只应王子晋，跨鹤每相寻。"]},{"t":"补到难","f":"词","c":["到乎难哉，碧落之洞天。","上有岚壁之瑶局，下有澄溪之碧澜。","碧澜之下，寸寸秋色。","目窥之而可量，手搴之而莫得。","窦容光而练飞，岩渍阴而乳滴。","如长人，如巨蛇，如翔龙，如镆铘，如倒植之莲，如已剖之瓜，如触邪之獬豸，如蚀月之虾蟆。","或断而卧，或起而立，或欲斗而抟，或惊顾而呀。","若斯石也，吁可怪耶。","何诡绝之异观，尝置之于幽遐。","到乎难哉，长萝美秀，瘦木竦直。","香撄寒而自媚，名概询而鲜识。","烟霏霏而引素，云悠悠而奋翼。","亟模似其变态，已灭然而无迹。","崩澌远响，罄落瑟续。","聆之愈深，咏之不足。","欲幽栖而忘返，尚徘徊而眷禄。","彼宁待乎世人，盖有要于仙躅。","到乎难哉，信夫到之难也。","匪到之难，知乐此以为难。","知乐此矣，能久处之又为难。","余故补到难以题篇些。"]},{"t":"巫山送吴延之出宰巫山","f":"楚辞体","c":["送子之邑兮，山之峨峨。","繄物之可赋兮，曰如之何。","虚徐恍耀兮，匪车匪马。","匪足匪翼兮，奋于岩阿。","薄万象兮周四海，烂五采兮扬天波。","倏然悄然以自敛，妥轻素兮萦翠螺。","容与兮窈窕，行止兮委蛇。","吐兮若英，攒兮若葩。","聚若白蚁，散若杨花。","爰有灵依兮，遂异于他。","对之自然，又不可求。","逐之无迹，怆我离忧。","上下无穷，变化周流。","乱曰：绵延夭矫兮竟何补，赞天工兮濡厚土。","舒则有时兮卷则有所，不为神女兮而为君子。"]},{"t":"山中","f":"楚辞体","c":["风萧萧兮云蔼蔼，泉淙淙兮石皑皑。","禽惊人兮，远飞去以复还。","客醉其间兮，殊不知为冠带。","发被衣颓以自顾兮，谁为吾仇。","山花为我一笑兮，山草为我以忘忧。","嗟世人之愚兮，竟营营以何求。","求百年之宠荣兮，取万世之奴囚。","怵谗舌之甚兮，尚毁孔而谤周。","咄何得而何失兮，孰为马而为牛。","歌数作兮饮未休，石骇以走兮泉凝而不流。","起挽石以道泉兮，尔何我尤。","吾将去乎世兮，结尔以长年之游。"]},{"t":"招遁","f":"楚辞体","c":["遁兮乐欤，吾能为子言之。","山高水长兮，遁岁月而忘归。","朝采木兮遁而食，暮葺蓑兮遁而衣。","云徜徉兮出岫，奋吾心兮与期。","日躅躅兮行天，吊吾影兮沉西。","委吾形兮自信，岂涂险之诘曲兮能屈伸而骛驰。","遁其乐兮，吾能为子重言之。","林之深则鸟兽遁而乐，水之深则鱼龙遁而乐，帝者之道备则生民遁而乐。","遁将独乐乎哉，吾弗与也。","于是作招遁之辞，辞曰：来。","马肥驭良兮迟子以归，虎豹齧人兮胡独为宜。","朝有好爵兮廪有好禄，遁勿遁兮于斯之时。"]},{"t":"言归","f":"楚辞体","c":["休欤归乎，何为而言哉。","予七龄而孤兮，托慈育以苟生。","捉手以笔兮，口授以经。","绪先子之素训兮，夜未央而丁宁。","既束发以就学兮，入必问其与游。","闻道之进兮，曰使我以忘忧。","课蚕而织兮，纫衣以先汝。","使弗坠业兮，我劳而汝处。","慨薄德之眇末兮，今愈壮而不扬。","吾母耄兮，恋故乡。","虽得邑而禄兮，曾寤寐之弗遑。","与音问之吉兮，孰若朝夕而在傍。","谁絷予足兮，眷白云之徜徉。","还印绶于有司兮，贤守足以往诉。","将俟代而返兮，念岁月之云暮。","休欤归乎，春山崺崺，春水瀰瀰，春蒲濯濯，春鱼尾尾。","吾亲在前，吾子在后，饮甘涤洁，以介眉寿。"]},{"t":"广言归","f":"楚辞体","c":["予将归兮而有言，德眇薄兮言弗见信。","孝乎为孝兮友于弟昆，奚为为政兮予之所存。","慨日月兮往而不返，吾亲八十兮事之云晚。","朝廷清明兮予忠曷施，道弗行于家兮何以教吾民之为哉。","呜呼，耕吾土兮足以食，条吾桑兮足以衣。","予奉亲兮孰不可乐，予治身兮尤以为宜。","蹇何忧兮何思，恬无闷兮无知。","休欤归乎，以退为进乎，予发诸诚乎，言谁弗信乎。"]},{"t":"泛江","f":"楚辞体","c":["士有以处兮，无亩以耕。","眷馀绪之尚抽兮，慨慈亲以迟荣。","徐虚缩瑟以内习兮，予实愧乎先民之心。","惚恍恻怆其不得已兮，被命于九江之浔。","戴皇天之休兮，廪足以饱。","度白日之难兮，谁察予情。","汹汹兮北风，怒浪兮滔天。","抚慈膝兮出门，泪涟洏兮就船。","事将有责兮，死岂予之所畏。","盖忠未足以尽报兮，孝未克以自信。","惟行止之坎坎兮，适简罪以冀生。","度白日之难兮，谁察予情。","蛟齧齿兮岸摧，蜃矫首兮渡分。","妖鳞怪鬣曾莫识其名兮，怒谺牙以相瞩。","数将倾而还复兮，予委命乎上灵。","幸生全而就泊兮，夜风止而月吐。","旷上下之澄澈兮，适纵观乎琉璃之府。","北斗扬光兮，百怪潜伏。","岸芷露翠兮，汀兰放芬。","起予思之无穷兮，既局影以自慰，又苦辞以招魂。","辞曰：始凶终吉，魂兮归来，奚往而失。"]},{"t":"殇愁","f":"楚辞体","c":["气氛氛兮隘如，魂飏飏兮宁居。","慧言在耳兮畴能舍诸，异质沈壤兮委夫顽虚。","鸿雁零飞兮若独何趋，兰茝早悴兮天孰与辜。","雄嗥雌啼兮巢失佳雏，天地黯黯兮风雨呼呼。","旐翩翩兮导衢，夜冥冥兮永殊。","樽有醑兮鼎有鱼，享弗享兮日月云徂。"]},{"t":"古思归引","f":"楚辞体","c":["昔人思归兮，宅林薮之邃深。","阻长堤而临清渠兮，芬翳翳以交阴。","有观阁池沼兮，通泉溜而附嵚崟。","蹇美羽之翔集兮，嘉鱼乐而浮沉。","时则命宴于芳晨兮，连亲戚与佳宾。","执乐而侍兮，列秦赵之艳人。","管弦奏兮，歌悠扬而绝尘。","浆兰桂兮，羞肴珍。","左琴右书兮，助为娱而养真。","又期于不朽兮，志慠然而陵云。","孰能婆娑于九列兮，顾牵羁于繁文。","曲有弦而无辞兮，述予怀以自信。","歌曰：日毂驰兮老将至，铄外纷兮中系累。","归去来兮予之思，放吾形兮聊逍遥以卒岁。"]},{"t":"补易水歌","f":"楚辞体","c":["燕云悲兮易水愁，壮士行兮专报仇。","车辚辚兮马萧萧，客送发兮酌兰椒。","击筑兮喑咽，歌变徵兮思以绝。","易水愁兮燕云悲，四座伤兮皆素衣。","歌复羽兮慷慨，发上指兮泪交挥。","又前为歌曰：风萧萧兮易水寒，壮士一去兮不复还。"]},{"t":"思嵩送刘推官赴幕府","f":"楚辞体","c":["我思嵩兮，三十六峰之葱苍。","云霞卷舒兮，纷五色而烂朝阳。","渺群仙之不可见兮，时有鸾鹤双翱翔。","穷崖断壑兮，飞泉吼怒舂琳琅。","俨修松与美竹兮，碧离离而低昂。","考周室之卜世兮，顾八表为中央。","天乃宠于吾宋兮，六陵相差而永藏。","惟传祚之亿万兮，岂八百以为之长。","引伊洛之二水兮，聿通汴而注扬。","回黄流于故道兮，灭湍射而汪洋。","横星桥于河汉兮，紫阙峙而炜煌。","列槐植之行秀兮，历五代而经唐。","承太平之雨露兮，幸不遭乎伐戕。","为众木之耆艾兮，如羽盖之迭张。","慨离彼而适此兮，亦出处之靡常。","既寓情于物表兮，独思嵩之未忘。","忽有客兮鼓楫，言别我兮灵羊。","将度庾岭，沿涛江。","涉淮溯汴，入幕乎洛阳。","词气有馀，顿挫铿锵。","诚南士之颖出，然未始离乎炎荒。","请陟嵩而远览，循今古而徜徉。","矫垂天之翼，灿琼瑶之章。","于是被诏音，登玉堂。","返视乎罗浮朱明，如弃鱼目而怀夜光也。"]},{"t":"王逢原哀词","f":"楚辞体","c":["追彷佛兮，故国之高丘。","与子之相遇兮，听其言而若秋。","雍雍而肆兮，严严而收。","乐我之心兮，以遨以游。","予将娶兮，于南州。","莫克从子兮，翻自省以幽幽。","川陆兮沉浮，日月兮再周。","云子之长逝兮，怆我之深忧。","子不可见兮，道将谁求。","彼苍者天兮，胡惨胡仇。","夺子之速兮，使不位于公侯。","虽穷德之特立兮，弗与世以绸缪。","嗟坎水之未盈兮，竟何泽以休休。","瘖予之声兮，血予之眸。","犹不足以止兮，灵何在而荐羞。","惟永绝兮奈何，怅平昔兮悠悠。"]},{"t":"徐孺兴哀词","f":"楚辞体","c":["嗟乎孺兴之不幸兮，上有高堂白发之慈亲。","孝不克以自信兮，魂将逝而复返。","目冥冥而莫胜兮，顾天命之予短。","业修修兮志与道配，寂不少振兮遽沉幽而终蹇。","兰未芳兮先凋，月将升兮俄陨。","孺人嚣嚣兮，追话言之弗足。","梦悠悠兮，魂去来而数蹙。","抚稚子兮秋夜长，暗明珰兮摧腕玉。","魂何知兮，兴予之哀。","体与道化兮，岁月徂而屡周。","情缠绵兮，若俱往则已矣。","词不足以尽寄兮，托馀思于江流。"]},{"t":"留君仪哀词","f":"楚辞体","c":["怀伊人兮，漳水之湄。","爰结好之初兮，予方出乎陷阱之羁縻。","彼知予之横罹兮，眷茕茕而弗支。","氛侵侵而袭人兮，子独赠我以兰芝。","芳芬芬而爽吾衷兮，虽厄穷而弗疑。","言涓涓而洗吾耳兮，寂尘听而凄其。","炊嘉黍而纳吾腹兮，使朝则忘饥。","采薜荔为予之服兮，慨前修之可追。","脂吾车而秣吾驷兮，造仙的之幽奇。","煮甘溜而茗酌兮，珍盘进乎离支。","唱则和兮，迭指摘其醇醨。","同底于道兮，遵圣渚为之归。","聊容与以卒岁兮，曾弗察乎白驹之骛驰。","泊中吉而启行兮，觞桂浆以违离。","惕南北之缅邈兮，蹇形影之颓衰。","歌激扬而再发兮，泪浪浪以沾衣。","马悲鸣而仰顾，仆弛负以增欷。","行云住而黯惨，去鸟返而低迷。","岁聘介而一至兮，孰敢为之后期。","幸再往而再复兮，释予心之思也。","忽承讣以踯躅兮，行不知其所之也。","嗟若人之蕴美兮，天其夺之速也。","蹇松柏之枯折兮，恶植则滋以荣也。","考大空之役物兮，必善抟而化之也。","将为麟为凤兮，对明世而出也。","将为兰为荪兮，芬馨香而荐上帝也。","将为江为河以济舟也，将为雨为露而泽物也。","将复为人兮，英华于士林也。","将为仙为神兮，自适于逍遥之境也。","呜呼，以甚塞之怀兮，测乎无涯之眹。","以有限之情兮，导乎无穷之悲。","呜呼，其有知乎，其无知乎？","吾其能久乎，吾将从子于重泉之游乎，吾又何词之哀乎。"]},{"t":"山中乐","f":"楚辞体","c":["归乎乐哉，山中之乐兮，其乐无穷。","蔼葱苍而杳巑丛兮，眷青瑶之诸峰。","琉璃一碧兮，湖波止而溶溶。","层楼相望，曲径相通。","鱼龙转影于汀澜之际，钟梵答响于烟云之中。","鸟嘤日暖兮，花气濛濛。","搴密叶而成幄兮，风飒飒而吹松。","岩谷玲珑，霜木落也。","玉宇浮空，冰澌凝也。","天高月朗兮，定省乎华严之境。","雷奔雨骤兮，作新乎水墨之宫。","达僧拟王孙之葬，逸士蹑渊明之踪。","方尔祖之得名兮，考其言于庐陵之醉翁。","曰嗟世之人兮，曷不归来乎山中。","山中之乐不可见，今予其往兮谁逢。","后四十年，尔复好吟。","远游不返，求我之从。","劝尔之归兮，栖老乎山中。","尔之材兮甚良，当自适其无庸之庸。","违世绝俗，黜明塞聪。","山中之乐兮乃可以久，非我与尔兮谁同。"]},{"t":"石室游","f":"楚辞体","c":["端城之北，径五六里。","有石室兮洞开，其上则七山建斗司天之喉舌，其下则渊泉不流渟碧一杯。","窥之则肌发冰，酌之则烦心灰。","四傍则石乳玲珑，中敞圆盖。","窈窈万丈，莫穷其厓。","孰纳忠兮，嗟肺肝之已露。","孰止戈兮，束兵仗而相挨。","俨卫士之行列，肃庭臣之序排。","纷披披兮蒂萼，粲枞枞兮条枚。","安而不可动者为梁为栋，奔而不可止者为虎为豺。","龟闯首兮屏息，虬奋鳞兮抟雷。","怪怪奇奇兮，千变万态。","愈视愈久兮，惚恍惊猜。","何人境之俯近而仙宇之秘异如此者哉。","萝卷风兮窈窕，春渍芳兮不回。","或命佳客，或寓幽怀。","考二李之劲笔，皆一时之遗材。","援玉琴以写咏，怅夕阳之易颓。","方谢事以言返，眷兹室而徘徊。","云愀容兮泱漭，鸟送音兮悲哀。","况百年之将尽，邈夫万里奚复来。"]},{"t":"逍遥园","f":"楚辞体","c":["逍遥有水一溪，有竹三亩。","兰芬菊芳，松老石瘦。","堂居其中，亭列左右。","菲菲兮春荣，阴阴兮夏茂。","孤猿啸兮秋夜长，空桑嗥兮冬雪昼。","山之名兮人莫知，公为主兮天所授。","其或要佳宾，酌醇酎。","清吟得韵兮，非人世之丝篁。","属笔成篇兮，发天机之锦绣。","方且登高台，挹远岫。","俯仰群仙，咨询遐寿。","脱轮蹄之萦，服烟霞之秀。","于斯时也，一举九万兮，吾不知其为用。","嗒焉自丧兮，吾不知其为偶。","翛兮窅兮，非无之无。","寂兮息兮，非有之有。","无何亦何得而名，有窍则窍遽能久。","至若听出于垣，观入于牖。","此鄙士之常习，又安得与夫逍遥主人而为之友也哉。"]},{"t":"孤云寄潘延之先生","f":"楚辞体","c":["望孤云兮山之巅，漭弗雨兮何油然。","送孤鸿兮海之涘，高举翼兮游无边。","彼君子之如似兮，脱世俗以不返。","奚无闷而止兮，又放意以穷年。","川有航兮陆有马，园有佳木兮池有芳莲。","坐卧兮白日，笑歌兮朱弦。","客至止兮，乐我之乐。","岂公侯之下兮，曾弗择乎愚贤。","仆夫以耕兮，妾女以织。","恬弗愧兮，我衣我食。","神仙之逍遥兮，固不得以见之。","君子之宴息兮，举斯世以谁敌。","嗟世人之自徇兮，莫知其求。","势得而傲兮，势失而囚。","靡后先之思兮，孰进退之由。","苟岁月之徙兮，托冠带以包羞。","惟勇子之从兮，贫未足以自周。","匪妻子之累兮，实吾亲之忧。","慨负重兮执热，慕坦跣兮临流。"]},{"t":"采薇山之巅赠张无梦先生","f":"楚辞体","c":["先生曰采薇山之巅兮，吾非求为之仙。","吾无一亩之宅，一丘之田。","饥食山之薇，渴饮山之泉。","岩为吾居兮，鹿为吾马。","吾岂不足兮，翱翔乎山之间。","彼世俗之混混兮，嗟苦短之白日。","此一身之悠悠兮，聊自乐以穷年。","彼尘埃之荏苒兮，此云烟之绵联。","谁谓才之大兮，慨匠氏之弗取。","吾独幸其弗取兮，森葱苍而自全。","粤吾君之为治兮，三王之圣。","而吾相之为辅兮，伊周之贤。","吾父吾母兮，皆善终以天算。","进何忧而退何憾兮，养吾气之浩然。","弟子进而赞曰：采薇山之巅兮，其乐也如此。","衣曳曳而情飘飘兮，愿执辔而往焉。"]},{"t":"游仙一十九首 其一","f":"五言律诗","c":["漠漠出寒雾，悠悠趋太清。","珠楼被重绡，灵花纷素馨。","青衣捧绿章，磨丹书姓名。","为我横玉笛，一奏雌龙声。"]},{"t":"游仙一十九首 其二","f":"五言律诗","c":["非尘复非烟，氲氲散紫清。","乃知泠风御，翛翛恣游行。","忽逢黄金阙，云是玉帝京。","逍遥侍御者，不假精锐兵。"]},{"t":"游仙一十九首 其三","f":"五言律诗","c":["扶桑并咸池，窅窅殊在下。","真阳涵素光，无昼亦无夜。","神体当自保，不与物俱化。","运龄从此长，尘缘顿消谢。"]},{"t":"游仙一十九首 其四","f":"五言律诗","c":["至道不由学，颓龄安可住。","宿命无纤罹，重玄乃遐悟。","鲜明女萝裙，致我火浣布。","稽首存至诚，欣会如所度。"]},{"t":"游仙一十九首 其五","f":"五言律诗","c":["至音非乐音，玲珑闻自然。","殊绝洞房景，亦超郁罗天。","灵嫔下鹤驭，问我来何缘。","却惊与世隔，一别三千年。"]},{"t":"游仙一十九首 其六","f":"五言律诗","c":["澡心华池液，薰手玉楼香。","一披宝神经，众真共来翔。","七言咏良遇，至音迭琅琅。","珍重卫夫人，行草记瑶章。"]},{"t":"游仙一十九首 其七","f":"五言律诗","c":["太微无烈风，紫台多灵露。","逍遥三五客，披衣纵高步。","回首笑复歌，游此今几度。","却嗟寰中人，枉为死所误。"]},{"t":"游仙一十九首 其八","f":"五言律诗","c":["仙家无四时，瑶草常芬芳。","五岳倏来尔，玉鞭驱凤凰。","得道迭相度，不闻嫉贤良。","所以心无邪，人人自年长。"]},{"t":"游仙一十九首 其九","f":"五言律诗","c":["妙景素无杂，玉界涵虚明。","妙声清不淫，洞歌奏金铃。","真遇非遐想，忘心乃全生。","噫哉百年内，得失安足营。"]},{"t":"游仙一十九首 其十","f":"五言律诗","c":["峨峨金精巾，飘飘清霞裙。","手持紫毛节，身乘三素云。","驾言欲何适，上朝玉宸君。","隐书谢所赐，洞明道之根。"]},{"t":"游仙一十九首 其十一","f":"五言律诗","c":["翛然乘一气，来往游太空。","閒歌内景章，遂登蕊珠宫。","华英不知名，激齿甘液浓。","此乐无忧衅，固非侯与公。"]},{"t":"游仙一十九首 其十二","f":"五言律诗","c":["投真落人世，倏经四九年。","睹纷未尝竞，内顾净且渊。","果逢飞行羽，得披紫微仙。","携手浮绛波，绛波春渺然。"]},{"t":"游仙一十九首 其十三","f":"五言律诗","c":["攀沿日月窟，遂观天地枢。","捣金铸豪英，抟糟酝庸愚。","校量宿所造，报应无差铢。","丁宁与世言，安分勿浪图。"]},{"t":"游仙一十九首 其十四","f":"五言律诗","c":["在天不择友，天人皆正一。","云汉共翱翔，隐耀无固必。","岂同浊世游，自谓胶投漆。","毫端利害分，白眼永相失。"]},{"t":"游仙一十九首 其十五","f":"五言律诗","c":["款逢九华妃，授我磨镜石。","一磨日月朗，万古永不蚀。","缄之紫锦囊，匪同赵氏璧。","才落猛士手，睨柱曾莫惜。"]},{"t":"游仙一十九首 其十六","f":"五言律诗","c":["二景结良匹，曾非尘虑侵。","欣欣启皓齿，玉佩扬清音。","碧河并绛实，采濯期追寻。","言舒意亦散，双好永齐心。"]},{"t":"游仙一十九首 其十七","f":"五言律诗","c":["神凝光自生，洞房玄照映。","青丝散垂腰，目采流玉镜。","共谈上清事，精微寄馀咏。","乐酣会既分，双驾还霄岭。"]},{"t":"游仙一十九首 其十八","f":"五言律诗","c":["清僚真可慕，振衣愿所归。","既绝世上缘，吾宁抱愁悲。","云韶自相谐，虚听方达微。","是将跨灵羽，逸麟复攀追。"]},{"t":"游仙一十九首 其十九","f":"五言律诗","c":["窥天见天根，步玄入玄门。","素光流一气，默默复浑浑。","挥手散馀景，至心揖灵尊。","从今乃忘言，大道多子孙。"]},{"t":"春日独酌十首 其三","f":"五言古诗","c":["平生最嗜酒，况复就花饮。","明月正照人，吴姬安得寝。","更起尽馀杯，击碎珊瑚枕。"]},{"t":"春日独酌十首 其四","f":"五言古诗","c":["芳华无十日，自劝频举杯。","素发易凋落，青春难再来。","林间黄鸟啭，日下浮云开。","吴歌梁尘飞，越舞白雪回。","英雄既长往，珠金安在哉。","仅存一丘土，石麟卧蒿莱。","谁曾将浊酒，为君倾夜台。"]},{"t":"春日独酌十首 其五","f":"五言古诗","c":["醉去卧兰茝，安用张蜀锦。","何必黄金杯，瘿杓亦足饮。","物理不可齐，好恶乃天禀。","真精既洞达，空无仍谛审。","所以陶渊明，北窗自攲枕。","起作无弦弹，此音殊妙甚。"]},{"t":"春日独酌十首 其六","f":"五言律诗","c":["雷声散阳气，晴景醉长天。","绿从何处来，染我山下泉。","汲泉酿醇酒，举杯复颓然。","寄谢伯夷辈，饿名安用传。"]},{"t":"春日独酌十首 其七","f":"五言古诗","c":["春日何迟迟，万物涵阳晖。","君看源上桃，并蒂花满枝。","双双梁间燕，营巢知所归。","凌霄附长松，托根亦有依。","馀生如不饮，无以谢芳菲。"]},{"t":"春日独酌十首 其八","f":"五言古诗","c":["不羞双鬓雪，折花向林间。","念此光景速，未能身世閒。","满酌金熨斗，遥望谢公山。","迹欲扁舟渡，心先高鸟还。","今朝不酩酊，何以破愁颜。"]},{"t":"春日独酌十首 其九","f":"五言古诗","c":["几日待春光，春光易衰歇。","流年信密移，谁能保肌发。","何须秉蜡炬，今夕值明月。","但愿海变酒，拍浮长出没。","归来归去来，蓬山有仙阙。"]},{"t":"春日独酌十首 其十","f":"五言律诗","c":["海棠微雨湿，枝上残红泣。","山鸟啼向人，春光一何急。","浊酒注我肠，免使新愁入。","却欲买扁舟，渔竿荷蓑笠。"]},{"t":"田家四时 其一","f":"五言律诗","c":["田田时雨足，鞭牛务深耕。","选种随土宜，播掷糯与粳。","条桑去蠹枝，柔柔待春荣。","春事不可缓，春鸟亦已鸣。"]},{"t":"田家四时 其二","f":"五言律诗","c":["麻麦闻熟刈，蚕成缲莫迟。","更看田中禾，莨莠时去之。","幸此赤日长，农事岂敢违。","愿言一岁稔，不受三冬饥。"]},{"t":"田家四时 其三","f":"五言律诗","c":["开塍放馀水，经霜谷将实。","更黎原上畴，坎麦亦云毕。","老叟呼儿童，敲林收橡栗。","乃知田家勤，卒岁无閒日。"]},{"t":"田家四时 其四","f":"五言律诗","c":["田事今云休，官输亦已足。","刈禾既盈囷，采薪又盈屋。","牛羊各蕃衍，御冬多旨蓄。","何以介眉寿，瓮中酒新熟。"]},{"t":"朝登北山头二首 其一","f":"五言律诗","c":["朝登北山头，千里入平望。","本欲寄吾怀，胡为返惆怅。","晴云随白日，西去没青嶂。","素丝行满头，吾年安可壮。"]},{"t":"朝登北山头二首 其二","f":"五言律诗","c":["朝登北山头，悠悠望江水。","水流无还期，人老行已矣。","劝君把一樽，聊用置悲喜。","生无死何有，原终乃知始。"]},{"t":"感春二首 其一","f":"五言律诗","c":["高枝花自舞，低枝花自笑。","上有浓露濯，下有清溪照。","开落十日间，谁识春工妙。","一杯亦颓然，独醒时所诮。"]},{"t":"感春二首 其二","f":"五言律诗","c":["盎盎酒杯绿，披披花萼笑。","虽无同心客，幸有白日照。","趋时性已拙，悲歌声不妙。","素发未能归，猿鸟应相诮。"]},{"t":"同阮时中秀才食笋二首 其一","f":"五言古诗","c":["苍崖长龙孙，头角露已甚。","呼丁恣庖割，移榻就浓荫。","恍疑羽林枪，罗列在紫禁。","馀鞭横瘦蛇，密箨若纫纴。","亭亭风势匀，节节泉脉沁。","藩垣谨藏护，宁使暴客闯。","烹调众云美，剪伐吾亦任。","绕齿嚼冰澌，毛发寒以澿。","閒心本猿鸟，世咏嗟毒鸩。","野逸谁所怜，愁思肠胃渗。","诗才君独勇，辨舌予久噤。","酒行且莫辞，醉胆沧溟浸。","况逢尧舜治，面内来左衽。","熙熙冠盖游，落落饱食饮。","鸾凤自横飞，燕雀蒙广荫。","徘徊食笋谣，明发扁舟赁。"]},{"t":"同阮时中秀才食笋二首 其二","f":"五言古诗","c":["予生本无羁，缪为兹县尹。","日长公事馀，佳客车接轸。","入林安所食，烹庖就肥笋。","森森苍龙孙，头角遭束窘。","金刀仆争割，紫箨手亲陨。","草火尤相宜，狼藉亦残忍。","聊为一饷乐，得酒辄满引。","喧呼棋屡胜，惨淡诗不敏。","予腹既便便，从君莞而哂。"]},{"t":"追和李太白姑熟十咏 其一 姑熟溪","f":"五言律诗","c":["源从丹湖来，奔流朝北极。","双桥跨长虹，千艘济民食。","日华动清晓，岸柳摇行色。","文王未出猎，垂竿人莫识。"]},{"t":"追和李太白姑熟十咏 其二 丹阳湖","f":"五言律诗","c":["湖广际长天，永日微风止。","菱歌一舟去，雪阵群鸥起。","荷香迷近远，秋色瑩表里。","试问贺季真，何如镜湖水。"]},{"t":"追和李太白姑熟十咏 其三 谢公宅","f":"五言律诗","c":["山腰存废址，昔是玄晖宅。","林藏幽鸟声，月弄野棠白。","高贤百年尽，遗事千古积。","此兴欲谁论，摩挲问磐石。"]},{"t":"追和李太白姑熟十咏 其四 凌敲台","f":"五言律诗","c":["高台筑千寻，胜景供远目。","云烟护城郭，吴楚接川陆。","不知歌舞散，雌凤叫空竹。","鬼火照残碑，应有精灵读。"]},{"t":"追和李太白姑熟十咏 其五 桓公井","f":"五言律诗","c":["环营凿九井，井深泉不竭。","旧甃缺琼瑶，新苔荒岁月。","重吟太白题，兴自柏公发。","我欲唤常娥，团圆伴澄澈。"]},{"t":"追和李太白姑熟十咏 其六 慈姥竹","f":"五言律诗","c":["一种碧琅玕，攒根绕苍岛。","浓阴不透日，密幄得春早。","笙随缑氏仙，钓入磻溪好。","欲识化龙蛇，唯应雪霜保。"]},{"t":"追和李太白姑熟十咏 其七 望夫山","f":"五言律诗","c":["登高望天涯，化石与君别。","秋鬓霜露深，春衫薜萝发。","旅雁只空飞，悲咽长不绝。","行客归去来，芳心可休歇。"]},{"t":"追和李太白姑熟十咏 其八 牛渚矶","f":"五言律诗","c":["长江泻危矶，雷怒安可向。","烟云忽藏月，鲸鲵互喷浪。","朱衣叱犀火，丹青岂能状。","引杯聊醉吟，径卧巨鳌上。"]},{"t":"追和李太白姑熟十咏 其九 灵墟山","f":"五言律诗","c":["仙人赴金阙，灵墟蹑高路。","空见白云飞，想乘黄鹤去。","月冷步虚坛，苔深炼丹处。","尘寰欲何为，光阴等閒度。"]},{"t":"追和李太白姑熟十咏 其十 天门山","f":"五言律诗","c":["巨灵擘苍山，势分金阙对。","月引晓岚交，江翻寒影碎。","双凫落人间，千帆出天外。","我欲往高吟，凌虚踏烟霭。"]},{"t":"追和李白秋浦歌十七首 其一","f":"五言古诗","c":["碧水碧如淀，染成秋浦愁。","长桥通驿道，危堞起朱楼。","荡桨谁家女，菱歌自风流。","江心雪浪涌，知解渡江不。","却羡云中雁，低飞过北州。"]},{"t":"追和李白秋浦歌十七首 其二","f":"五言律诗","c":["此夕宿秋浦，萧萧古岸头。","白云和月散，江水晴空流。","不及水中鸟，随波上下游。","客情须自遣，知命适虚舟。"]},{"t":"追和李白秋浦歌十七首 其三","f":"五言绝句","c":["水晚舟楫止，山寒猿狖稀。","虽怜秋浦好，未敢濯征衣。"]},{"t":"追和李白秋浦歌十七首 其四","f":"五言绝句","c":["霜落荻洲晚，水残鱼市衰。","唯逢采荷女，素手理轻丝。"]},{"t":"追和李白秋浦歌十七首 其五","f":"五言绝句","c":["莫听猿夜啼，莫看芦花雪。","倦客多少愁，离家八九月。"]},{"t":"追和李白秋浦歌十七首 其六","f":"五言绝句","c":["水有锦驼鸟，山多杜宇花。","扁舟投夜泊，来自长风沙。"]},{"t":"追和李白秋浦歌十七首 其七","f":"五言绝句","c":["秋水适瀰漫，宁分马与牛。","酒楼翻擅价，不当白狐裘。"]},{"t":"追和李白秋浦歌十七首 其八","f":"五言绝句","c":["秋浦试北望，参天九峰奇。","缘何谪仙客，名作碧莲枝。"]},{"t":"追和李白秋浦歌十七首 其九","f":"五言绝句","c":["万丈水车岭，还如九叠屏。","北风来不断，六月亦冰生。"]},{"t":"追和李白秋浦歌十七首 其十","f":"五言古诗","c":["舍楫乘蓝舆，十里穿松林。","悲风西北至，千千龙凤吟。","史君如杜牡，方有爱山心。"]},{"t":"追和李白秋浦歌十七首 其十一","f":"五言绝句","c":["齐山一百洞，咫尺接危梁。","雨过频登望，逼人松桧香。"]},{"t":"追和李白秋浦歌十七首 其十二","f":"五言绝句","c":["清溪十里岸，芦花八月天。","不惜锦袍湿，应须棹钓船。"]},{"t":"追和李白秋浦歌十七首 其十三","f":"五言绝句","c":["秋浦胜姑熟，白鹇无数飞。","谪仙如得句，须换一双归。"]},{"t":"追和李白秋浦歌十七首 其十四","f":"五言绝句","c":["老谢夺秋景，横卷披云烟。","寓目不知远，何须家辋川。"]},{"t":"追和李白秋浦歌十七首 其十五","f":"五言绝句","c":["镜潭弄秋月，始知秋兴长。","金龟能换酒，客鬓不嫌霜。"]},{"t":"追和李白秋浦歌十七首 其十六","f":"五言绝句","c":["半空紫微亭，玩月动经宿。","更待雨中来，林林看银竹。"]},{"t":"追和李白秋浦歌十七首 其十七","f":"五言绝句","c":["秋浦一何好，名因太白闻。","溪山围市井，鼓角下烟云。"]},{"t":"追和李白登金陵凤凰台二首 其一","f":"七言律诗","c":["采凤何年此地游，高台千古自风流。","寒烟淡淡笼城郭，宝器时时出冢丘。","舴艋竞归芳草渡，鹭鸶群舞碧芦洲。","重华不返箫韶断，落日秦淮添客愁。"]},{"t":"舟次新林先寄府尹安中尚书用李白寄杨江宁韵二首 其一","f":"五言古诗","c":["金陵龙虎国，况与王谢期。","挂帆须一往，愿借天风吹。","昔解徐孺榻，别来劳梦思。","钟峰当北户，浮玉出东池。","柳青白下门，鹭栖琼树枝。","但对樽中物，何嗟镜里丝。","如闻紫泥诏，起公翊明时。","霈为天下霖，一洗旱暵悲。","请歌甘棠歌，翻作新林诗。"]},{"t":"舟次新林先寄府尹安中尚书用李白寄杨江宁韵二首 其二","f":"五言古诗","c":["休居尚蒙禄，愿赴兴龙期。","况此孱病姿，感公久嘘吹。","相望止百里，株坐徒倾思。","呼僮刷鹤羽，驾言别清池。","往将投新林，新林有高枝。","仰听鸾凤音，轧轧如抽丝。","穷阴欲雪天，燕雀无声时。","接物伸妙理，运心广真悲。","如何持一杯，要我百篇诗。"]},{"t":"舟次白鹭洲再寄安中尚书用李白寄杨江宁韵 其一","f":"五言古诗","c":["白鹭飞还集，新沙没故洲。","山形龙晦角，江气蜃为楼。","欲问前朝事，空怀去国忧。","钟声万家晓，霜叶半城秋。","化值唐虞盛，人逢王谢流。","徐生思解榻，兵酝可销愁。"]},{"t":"舟次白鹭洲再寄安中尚书用李白寄杨江宁韵 其二","f":"五言古诗","c":["终朝荡双桨，夜泊碧芦洲。","重城已在望，闻公晏层楼。","华灯灿繁星，浩歌正忘忧。","宾朋集珠履，佳节临千秋。","愿言刷微羽，一饮清冷流。","举目送高凤，箫韶洗民愁。"]},{"t":"奉同安中尚书用李白留别王嵩韵送毛王仲大夫移浙漕","f":"五言古诗","c":["春岸草回绿，春江日浮金。","兰舟忽言发，芥蒂悲我心。","蔼蔼松柏友，雍雍鸾凤吟。","愿同三岁遥，毋使离别侵。","奈何千丈材，亭亭不依林。","眷为九重知，移节宣德音。","遂令帝王泽，深于太湖深。","岂同失群鹤，饮啄怜空岑。","谁将劳劳歌，一泻无瑶琴。"]},{"t":"将游宣城先寄贾太守侍御用李白寄崔侍御韵","f":"五言古诗","c":["峨峨敬亭山，玄晖有佳作。","贾公乃后身，风流今与昨。","豸冠触奸邪，分符宛陵郭。","江湖暂徘徊，烟霄必腾跃。","予方卧閒云，时或乘皓鹤。","水缩龙蜃归，霜清天宇廓。","安能坐陇亩，凄凄眷藜霍。","陈蕃有虚榻，黄埃侵断索。","能如汲黯直，定许季生诺。","往哉不可失，行闻还凤阁。"]},{"t":"追和李白宣州清溪","f":"五言律诗","c":["清溪安在哉，欲弄清溪水。","更邀琴高生，携竿会于此。","日落翠屏间，鸡鸣桃花里。","不见避秦人，谁嗟远游子。"]},{"t":"留别陈元舆待制用李白赠友人韵","f":"五言古诗","c":["沈吟涧底松，不及尧阶草。","不经君王顾，枉被风霜老。","弱羽恋一枝，敢思浴天池。","闻君有馀力，何惜一嘘吹。","青云与黄壤，回首隔追随。"]},{"t":"留别宣守贾侍御用李白赠赵悦韵","f":"五言古诗","c":["贾谊几世孙，闲邪诚所存。","一登御史府，直气壮中原。","五载三去国，出论皆腾喧。","浩养固无害，宣城况名藩。","下车究积弊，摘节仍除根。","乃迁孔子学，方庭树兰荪。","讲解得董生，思单先生恩。","轩轩慕高第，各各不窥园。","修桥济行迈，掩骼招旅魂。","萧萧囹圄空，清风时扫门。","寻山出近郭，玉船红浪翻。","谁为坐上客，能酬谢公言。","自愧翅翎短，谬参鸿与鹓。","不有瓦砾贱，那知圭璧尊。","矧曰半面雅，岁久情愈敦。","三章宠新作，词源何骏奔。","几欲效长吉，微吟谢高轩。","霜威信凛冽，即之自温温。","又如太古镜，磨开苍藓昏。","肝胆悉照彻，魑魅安敢论。","行闻紫泥诏，沙路驰归辕。","岂容隐岩子，留连爱石盆。","看君杨天翼，北溟终化鹍。","而我随白鸟，丹湖往孤鶱。"]},{"t":"追和李白郎官湖寄汉阳太守刘宜父","f":"五言古诗","c":["迁客昔登览，愁烟颓四隅。","身趋夜郎道，恋咸阳阳都。","此景古来好，此人今则无。","空馀秋夜月，素影湛平湖。","便欲凌风去，酣歌与君俱。"]},{"t":"题化城寺新公清风亭用李白元韵","f":"五言古诗","c":["唐时升老亭，剪棘今重开。","南瞻峨嵋阙，北峙凌敲台。","新公将家子，为僧亦多才。","譬彼独鹤唳，安用群鸡猜。","或弹玉轸琴，倾耳濯纤埃。","清风不知处，冷冽时时来。","吹云云窈窕，吹月月徘徊。","幽人许共赏，渴心咀珍梅。","了然得真味，尘魔屡崩摧。","令妷人豪杰，书名骇奔雷。","禅谈屡终夕，茗酌无馀杯。","还歌太白篇，事往良可哀。","古今傥同辙，浩气不寒灰。"]},{"t":"太守陈侯见要登黄山送马东玉遂用李白登黄山送族弟济赴华阴韵呈陈侯并送东玉","f":"五言古诗","c":["颍川贤大夫，虚怀蕴虹霓。","虽分铜虎符，合在帝苑栖。","邀我登黄山，攀云绝长梯。","霜林正摇落，寒鸟鸣惨悽。","金牛饮空渚，天镜开峨嵋。","尘埋宋武妓，藓剥开元碑。","谪仙送客处，魂断白日低。","松梢想独鹤，轩昂避群鸡。","还思北溟钓，赤脚蹋鲲鲵。","时穷壮士耻，思远骚人悲。","且举一杯酒，肯分云与泥。","坐有北归客，张帆震雷鼙。","往献白玉璞，不怜红粉啼。","荐章已交达，高名动朝闺。","君相必见收，烟霄速横飞。","杯停可以起，看君开羽仪。"]},{"t":"盛仲举秀才归自九华极谈胜赏亟取李白九华联句原韵作二首志之 其一","f":"五言律诗","c":["客从青阳归，为我谈九华。","雪潭昨夜宿，衣上有残霞。","鸣溜隔深木，白鹇栖翠崖。","南游岂是远，乘兴必携家。"]},{"t":"盛仲举秀才归自九华极谈胜赏亟取李白九华联句原韵作二首志之 其二","f":"五言律诗","c":["昔号九仙子，今名九莲华。","差差浮碧海，叶叶散晴霞。","积霭迷金寺，飞流溅雪崖。","开帘陪岸帻，须觅夏侯家。"]},{"t":"望九华山寄夏公酉","f":"五言古诗","c":["扁舟溯南江，群山渐秀发。","遥瞻九华峰，点点出天末。","迤逦见雄奇，平地犀尖拔。","夕阳凝紫烟，仙簪聚鸦发。","又疑碧莲花，倒插黄金阙。","想像终未工，灵襟谩超越。","矧彼山中人，了与尘事绝。","采秀既忘年，道授飞仙说。","世间名任高，物外缘皆灭。","百忧眷薄禄，我辈志已屑。","趋荣羞捷途，就卑老刚节。","雅知名山乐，勇往胡未决。","此兴待君论，青衫可偕裂。"]},{"t":"感怀赠鄂守李公择","f":"五言古诗","c":["君颜削寒冰，君心抱坚玉。","自甘正谏黜，不受公议辱。","请言会面初，遭艰守穷屋。","屋临修水阳，蓬门入深竹。","伯季止三人，群书聚头读。","野夫学孟郊，苦吟中夜哭。","公达学伊尹，经济饱胸腹。","君乃学扬雄，草玄明倚伏。","遂兼孔氏易，极变悟神速。","亭亭出林材，濯春千丈绿。","我愿从之游，旦暮同饮餗。","忠规日有益，文彩观郁郁。","不肖俄遭谗，逃形入空谷。","诸君释服起，为贫苟微禄。","君来宣城幕，众谓得杜牧。","我适游昭亭，林中骑白鹿。","时趋资深堂，遇君亦休沐。","饮酣河汉低，谈高鬼神肃。","出处二三年，于焉失羁束。","一别几何时，离群念幽独。","野夫今郎官，佐郡驰朱毂。","公达遽不幸，高名收鬼录。","君昔居谏省，上方容启沃。","忽分江夏符，善教苏弊俗。","众饥发仓赈，卖丁与金赎。","载歌奇章公，间运始来复。","顾我最飘零，尘网自投足。","遐趋僻小郡，势若羝羊触。","道出贤侯藩，菁莪闻乐育。","况当黄鹤楼，晴江春扑扑。","美人卷红绡，笛奏梅花曲。","龙行水底吟，云在山头宿。","酩酊安敢辞，念此龄运促。","君名方显显，我困已碌碌。","一为涸辙鱼，一作秋空鹄。","愁来如江河，篑障不可筑。","聊书感怀篇，泪下遂盈掬。"]},{"t":"采石峨嵋亭登览赠翰林张唐公","f":"词","c":["巨舟发长溪，箫鼓奏云汉。","史君领宾从，险绝穷壮观。","逶迤转沧洲，稍泊大江岸。","前登千丈峰，万里瞰瀰漫。","峨嵋耸双碧，斩斩天堑断。","谁驱六龙辔，事逐孤烟散。","如闻限南北，谬彼曹公叹。","宁知真人兴，遐徼服辉焕。","僭王苟馀息，窘束若鼠窜。","虹蜺渡戈甲，雷雨洗屯难。","石根有遗迹，俯首想神算。","承平逾百年，针砭决痈?。","幸兹国老贤，州事无留断。","披榛构危亭，突兀出天半。","乐成须吾曹，啸咏争璀璨。","天空纤霭没，川动日华乱。","群鸥或飞舞，缟练遗片段。","归艎鲸鬣摆，渔火星点灿。","灵犀安用燬，神理幽可赞。","翻思袁谢辈，道贵一以贯。","遇古名空传，逢今岁非晏。","我公神采瑩，皎皎白玉瓘。","言词珠内掷，肝肾锦绣烂。","平生存至诚，许与比象彖。","况当仙府间，长谣愈华奂。","原原无根涯，天马脱羁绊。","顾予亦何人，勇和不知偄。","譬彼禽之雏，敛翼自投弹。","饮阑记名姓，会稽妙挥翰。","滑磨青瑶碑，八法素常按。","点画犹生成，霜池聚鸿雁。","千载期弗讹，鉴赏永传玩。","盛事难再并，月上归兴逭。"]},{"t":"赠泗守宋子坚","f":"五言古诗","c":["忆昔始相遇，谏院吴侯家。","君颜清且少，皓雪敷琼花。","把酒听高谈，正气横镆铘。","倏别二十载，各在天一涯。","君去登朝闺，我方浮海槎。","进退自殊辙，音尘空雁驾。","朅来淮上守，政声被幽遐。","填德在风俗，馀春散禾麻。","斤斤梁栋材，葱苍蛰龙蛇。","匠石未回首，电雹无倾斜。","而我造宾榻，逢鬓吹尘沙。","欢言问往事，念此岁月赊。","开馆使休息，投文误矜誇。","伯乐虽一顾，惭非真渥洼。","功名业已晚，世路今仍差。","独既醒不容，混迹良可嗟。","清江秀山水，白酒浮月华。","深犁熟粳稻，浅钓多鱼虾。","长为避俗翁，不落猛虎牙。","愿言虽未谐，行矣君及瓜。"]},{"t":"赠元龙图子发","f":"五言古诗","c":["明公有盛名，十年怀慕向。","昨闻守桂林，清风扫蛮瘴。","否来偶迁谪，暂泊宛溪上。","斯事公议存，君命讵惆怅。","坐扃顾申卯，自忘曾帅将。","徯馀领儿孙，时时入重嶂。","遇胜寄幽怀，览古兴绝唱。","况逢谪御史，文章号宗匠。","赓酬戛金玉，侧耳听响亮。","神交付逍遥，外物随得丧。","汉庭忧乏才，贾谊岂终放。","未即登金鉴，行须复牙帐。","矧公饱经术，义足明霸王。","推忠结圣主，大业继贤相。","霈成三日霖，一慰天下望。","微生实幸会，漫刺诣高闶。","尘埃蒙弊裘，何以异罔象。","屏诎诚所宜，奖与若为当。","逢知信有时，报德亦非妄。","且陪昭亭游，昭亭春盎盎。"]},{"t":"赠夏公酉寺丞","f":"五言古诗","c":["秋浦明似镜，九华碧参天。","秀色动南斗，乃生名世贤。","卓越夏夫子，其才文武全。","一览无复遗，万卷能口传。","奏书黄金阙，坐可安二边。","功名初自许，世路多回邅。","亭亭出林干，暴为狂风缠。","乘槎往沧海，怒涛观大川。","还闻上南岳，阔步从飞仙。","解衣祝融峰，濯足天池渊。","下视白日没，九州渺苍烟。","倾罍吊屈贾，汝道吾未然。","胡为夺浩气，惨淡趋重泉。","冥心想太古，妙理追淳源。","白云起归兴，却泛千丈船。","少泊姑溪头，春林听杜鹃。","谢李迹已往，高风在遗编。","浮魂试一招，相望谁后先。","伊余亦何人，谬拍洪崖肩。","放身逍遥乡，致主知何缘。","斯时方泰熙，薰风播朱弦。","奇才森大庭，拔茅茹相连。","岂闻卞氏璧，指以微瑕捐。","愿取魋仓徒，投北首可悬。","叹息比不足，浩歌成此篇。"]},{"t":"赠二李居士","f":"五言古诗","c":["二子跨黄犊，寻春造龙眠。","身披五云装，翠发散垂肩。","群儿漫相逐，不识南昌仙。","我往一长揖，问我聊停鞭。","深林藉草坐，对酌临潺湲。","琅琅听险语，了了出爱缠。","月殿折芳桂，高名金榜悬。","掉头不回顾，息迹棦淳源。","穷幽采紫芝，长啸呼青猿。","使我慕高节，神魄方森然。","言归恨不早，白雪羞盈颠。","于时业无补，碌碌随冗员。","交趾近反逆，蚁聚浮战船。","邕廉皆失守，圣主忧南边。","上将命逵卨，睿算天所传。","虎罴十万众，干戈与云连。","倾海洗枭巢，拓境除狼烟。","怅怀炎瘴地，何日闻凯旋。","北虏恃骄黠，分疆亦逾年。","庙谟非不深，遣使皆俊贤。","此事竟未果，艰虞甚防川。","安得傅介子，万里威名宣。","不然随隐沦，渔钓求深渊。","出处两龉龃，悲歌写哀弦。","二子顾我笑，汝心殊未坚。","浩气本完洁，胡为自镵镌。","请驾逍遥车，共游方广田。","饥餐种成玉，渴饮华池泉。","我命永不灭，是身犹蜕蝉。","世纷速辞谢，来续清净缘。"]},{"t":"赠乐岳山人","f":"五言古诗","c":["乐老出三峡，骑驴访名山。","一见五老峰，笑傲遂忘还。","萧萧太古松，徙倚青崖间。","泉石托生计，云霞会追攀。","我宁求世人，世人非我闲。","鍊气得真惠，神针起疵瘝。","何时驾皓鹤，定应出尘寰。","王母如问仆，为谢今钝顽。"]},{"t":"赠辨才宗衍大师","f":"五言古诗","c":["开帆出长淮，泊舟近禅刹。","仰瞻窣云塔，俯压神物穴。","衍语如悬河，事从古先说。","欣闻佛力圣，降魔未尝杀。","尔来居几年，戒履皎霜雪。","领徒三百人，昼饭天厨说。","重重殿阁阴，清爽无六月。","固知出世缘，了与俗士别。","此生犹孤蓬，惊风畏飘瞥。","长林宿鸟尽，而我归路绝。","出处既不同，净社无由结。","三叹复何言，疏钟云外灭。"]},{"t":"赠圆通讷禅师","f":"五言古诗","c":["禅师古豪英，识之恨已晚。","浩气虽自充，灵标固天产。","琼枝玉府秀，春波镜湖满。","妙趣玄中玄，高谈简复简。","痊予万古病，金刀刮昏眼。","朗如秋月明，不害浮云生。","始知金仙教，六幽同一情。","一情亦何有，纷纷逐妍丑。","遂令世上人，浮沉嗟白首。","我愿卿相知，荐师为国师。","一言了万化，尧舜诚无为。","逢时扬至道，旷劫开群迷。","儒佛实皆圣，胡为相是非。","本亡末愈弱，行伪言空持。","呜呼可奈何，师也予同归。"]},{"t":"赠端禅师","f":"五言律诗","c":["十年不变旧，交深情愈淡。","世乐贻真羞，去若出阱陷。","故林泉石新，悠然在虚鉴。","寂寂夜香沉，无心答钟梵。"]},{"t":"赠隐静禅师","f":"五言古诗","c":["平生厌羁束，乐为名山游。","五峰数千仞，拔地凌斗牛。","山光落涧影，倒挂天河流。","灵草雾露香，老木阴翳稠。","鸟鸣春盎盎，虎啸风飗飗。","耳目两以醒，虚襟清气浮。","况有希世交，居焉治林丘。","玄谈倾醍醐，荡涤方寸愁。","出没死生际，日用诚吾由。","应嗟世俗士，俯首窥王侯。","百年聊汩汩，外物终何求。","我将脱冠带，筑室东岩陬。","长年丐香饭，师也能容不。"]},{"t":"赠利安禅伯","f":"五言古诗","c":["名山多隐者，五峰遇僧安。","屹然高世姿，眉目冰雪寒。","极谈了无迹，卷舌回惊湍。","令我愧道心，龌龊滞小官。","不能与斯人，物外振羽翰。","惜为山下别，落月在林端。"]},{"t":"寄常执中长官弃官归霅上","f":"五言古诗","c":["高飞不上云，不如栖白蘋。","屈身五斗粟，何似种松筠。","闻君将挂冠，筑室苕溪滨。","况有朱少翁，达论可相亲。","攲枕待落月，寻花送馀春。","市喧不入耳，休羡桃源人。","我亦促归计，行当趋后尘。"]},{"t":"寄清流许令","f":"五言古诗","c":["霅溪皎寒玉，霅山卧苍龙。","我方穷眺览，忽与旌阳逢。","教告非俗语，泠泠启昏蒙。","我旧骑蹇驴，君去跨冥鸿。","一别十五载，旷怀渴清风。","今闻佩县印，高凤潜衰蓬。","谁信五彩烂，卑栖能自容。","终当振羽翮，万里沧溟东。"]},{"t":"寄虔州慈云惠禅师","f":"五言古诗","c":["惟昔庐山旧，舜师称老禅。","惠也乃上足，解空无比肩。","我尝叩其说，活活如涌泉。","况复能吟哦，俯视唐皎然。","一别二十载，相望修途邅。","音信谁谓隔，月华长自圆。","嗟予困俗累，久负香火缘。","适为幕府客，远泛潇湘船。","还过庐山下，庐山安足怜。","既无故人语，顽碧徒参天。","多谢子规鸟，数声空谷传。","准拟趁汝飞，飞落赣水边。"]},{"t":"蒋颖叔要予同赋平云阁","f":"五言古诗","c":["宣城多名山，诗人旧经历。","独无平云篇，煞怯作者敌。","不然灵祇护，晦此神女色。","留与无心人，开轩初占得。","群奔万马放，片堕孤鹰击。","缕缕蚕茧抽，枞枞羽林直。","恍随片月散，又逐岚光滴。","缟带裁未成，蛟绡瑩无隔。","苍龙奋修鳞，皓鹤舒春翼。","天墀耸群玉，胡阵望鸣镝。","尤怜欲雪时，铁甲万里黑。","变化固无穷，想象岂尽识。","贤哉谪御史，注目倚寒壁。","吟非宋玉赋，心在汉皇席。","愁来把樽酒，薄咏继朝夕。","迷魂招屈贾，大句压甫白。","初屯念经纶，作解须霹雳。","终朝去为霖，未信长抱石。","卷舒能及时，慰此长太息。","诗言我枯疏，返类群儿剧。","君探骊颔珠，不惮海神惜。","更当俟来唱，研尽廷圭墨。"]},{"t":"寄题陈生九华阁","f":"五言古诗","c":["颍川有佳士，放怀慕清闲。","或游公侯门，得诗乃言还。","潇洒青松姿，俗驾何由攀。","买田数百亩，家住濡须湾。","匣有雷张琴，旋拨春醅绿。","客来留一醉，听我弹数曲。","收身趣已远，爱山心未足。","千金建危阁，遥望九华峰。","紫光射晚日，点点金芙蓉。","南风吹秀色，半落樽罍中。","酒味愈冷冽，琴声又玲珑。","飘然紫霄想，何日跨冥鸿。"]},{"t":"寄题东城耿天骘归洁堂","f":"五言古诗","c":["东城耿天骘，读书五千卷。","有义或未通，至忘寝与膳。","潜心唯丘轲，弟子并时彦。","晚从进士起，青衫落铨选。","捕贼偶诖误，差池困州县。","宁知贾马才，不上明光殿。","功名既无成，禄廪岂足恋。","归来洁其身，旧学进吾善。","构堂剪深竹，江山使对面。","秀色览天镜，毛发瑩可见。","闲情寄浮云，零落两三片。","颓然堕支体，隐几自峨弁。","有时明月来，朋簪合清宴。","狂为梁甫吟，璀错珠玉串。","夫人无妒忌，群妾美目眴。","大儿富文学，又随太守荐。","百口不忧贫，九品不为贱。","内足外亦足，此乐信无倦。","轩冕达士寄，形色圣人践。","他时采高名，犹冠儒林传。"]},{"t":"寄题吴子山孤云亭","f":"五言古诗","c":["重华不可见，曾参久为尘。","孝道遂零落，为子吟孤云。","孤云泊南山，山下藏二亲。","孤云自朝夕，坟草几冬春。","悠悠我之思，孤云浩无垠。","注视讵能揽，倾耳那得闻。","音容劳梦想，涕泪濡衣巾。","作亭坟之隅，奚止簠簋陈。","扬名与行道，勉勉期终身。","采彼孤云篇，为子书诸绅。"]},{"t":"题冶父山实际禅院","f":"楚辞体","c":["虎兮弗食子，谁谓虎性恶。","一见慈孝人，帖身不敢缚。","旧庐当绝巅，今寺据幽壑。","人虎皆已非，断碑苍藓剥。"]},{"t":"题宣州天庆观秋水阁","f":"五言古诗","c":["偶登秋水阁，静吟秋水篇。","初不辨牛马，河泊方欣然。","及见北海若，始惊大小悬。","大小不相借，致令夔爱蚿。","学者傥悟此，心忘真乃全。","白云散林表，苍山落檐前。","中有醉道士，兀兀知何年。","寒风洒面醒，暖日曝背眠。","弹琴不终曲，抚掌望青天。","谁来达渠意，勿作虚名传。"]},{"t":"题旌德虞令观妙庵","f":"五言古诗","c":["深溪彻寒鉴，苍山开翠屏。","结庵当此间，观妙题其扃。","借问观何妙，伊人养性灵。","岂为娱耳目，是将达神明。","滞有乃为病，趋无亦何营。","外感适变化，中虚藏窅冥。","夜深片月散，林鸟三四声。","寥寥太古风，吹我襟尝惺。","逍遥形骸外，浩荡天地情。","未能同子乐，聊用歌强名。"]},{"t":"题泗州龟山寺","f":"五言古诗","c":["苍山如巨龟，长淮就吞吐。","石林含霜明，爻卦俨可数。","相传有神物，在昔遭圣禹。","絷铁送潭中，作镇亘万古。","乾坤未云息，魑魅那得侮。","至今崖下潭，不敢设网罟。","迩来建佛庙，金碧烂庭户。","长廊肖深洞，夜香郁浓雾。","一读碑上文，飒尔精神聚。","悯旱截臂翁，开山即初祖。","借僧百万人，下坛三尺雨。","至尊亲赐诗，高名动寰宇。","楼阁疑化成，何年运斤斧。","洄流涨平沙，舟楫永无阻。","尤怜瞻仰地，曾是攲倾所。","王者唯好仁，佛力岂无补。","我来解征鞍，赫日正卓午。","凉风如冰霜，洒我襟上土。","仰惭云衲禅，未尝倦行旅。","还思治水功，冥寞今何许。"]},{"t":"题抱黄洞景德观","f":"五言古诗","c":["晋道昔纷乱，志士多学仙。","乃愿脱尘网，毕身飞绛烟。","卓彼抱黄子，遗迹兹山巅。","地灵无恶木，杉松碧参天。","四时不变春，脩脩女萝鲜。","下有白鹿卧，上有青猿悬。","微风五音奏，不假朱丝弦。","来者迭宏构，深门秘真筵。","馀芳考金刻，眇末期羌肩。","回念时运泰，岩谷无逃贤。","寓游足以乐，携壶谩思玄。","黄冠四五辈，达者余所怜。","未尝诣州府，白发犹侵颠。","而况尘中人，欲以永岁年。","聊书一日事，继之逍遥篇。"]},{"t":"题雨华台","f":"五言古诗","c":["云公说法时，诸天雨名花。","此事古老传，岂为虚语誇。","至今数亩地，长松肖龙蛇。","下不生蔓草，上不存栖鸦。","夜或散瑞光，烂若赤城霞。","沿崖仅可到，狭径宁容车。","严严渤海公，好古心无涯。","携筇徐步至，极眺频吁嗟。","不唯古佛迹，绝景来幽遐。","城郭如钩环，井庐杂禾麻。","青山断绿野，白水连平沙。","翔帆出天镜，叠鼓传掺挝。","又复听归橹，大泽鸣雁驾。","云烟失浦溆，霜雪摧蒹葭。","顾瞻指掌间，千里无毫差。","中天二龙飞，此邦恃犬牙。","纳士业已缓，何殊井中蛙。","神兵半夜集，城裂如剖瓜。","唯仁乃无敌，四海同一家。","我公乘闲来，式宴宾亦嘉。","作亭当旧址，海月浮窗纱。","举杯莫辞酒，越女弹琵琶。","为我谢云公，亦有三春葩。","真法忌拣择，岂校静与哗。","酩酊上马归，鬓发从纱纱。"]},{"t":"太平观","f":"五言古诗","c":["下马携瘦筇，凌晨极幽赏。","腾身孤峰半，纵目浮云上。","严严洞天路，霭霭灵气王。","古木藏春容，飞流落天幌。","断崖倾郁萝，深宫秘真像。","坛心綵虹贯，幡脚仙飙飏。","老鹤时一鸣，众鸟不敢傍。","人寰杳何处，仕路险已忘。","高歌乐逍遥，抚掌遗得丧。","长生岂无术，静理聊自放。","独醒世不容，苟合情辄枉。","咄嗟胡为乎，兹焉卜长往。"]},{"t":"寻真观","f":"五言古诗","c":["苍崖犹积雪，冻林春未归。","石径稍可通，决决泉声迟。","薄游欲何适，携筇负阳晖。","览胜辄长啸，世事吾何羁。","忽到仙人家，楼殿势欲飞。","皓鹤向人舞，青猿攀树啼。","屏风叠苍玉，深潭瑩琉璃。","谁云蛰龙卧，朗咏前人诗。","飕飗太古风，会生松桂枝。","回首归兴遥，日暮青云低。"]},{"t":"水磨","f":"五言古诗","c":["盘石琢深齿，贯轮激清陂。","运动无昼夜，柄任谁与持。","霹雳驾飞雪，盛夏移冬威。","功成给众食，势转随圆机。","翻思兵家言，千仞俯可窥。","又想对明月，大壑投珠玑。","睥睨巧匠手，不使差毫釐。","牛驴免穿领，僮仆逃胼胝。","利用固已博，沉吟岂虚辞。","愿将水磨篇，荐之调鼎司。"]},{"t":"同蔡持正长官观齐景茜虞部家藏远祖成公监修国史诰","f":"五言古诗","c":["禀禀齐成业，得之权公碑。","逢时初多难，退密安庭闱。","深怀经纶策，起佐虎罴师。","省郎拜侍御，出赈关中饥。","俄登谏诤列，忤旨领一麾。","徐迁河南府，法令严张施。","宿奸即诛殄，和气回霜威。","德宗治勤劳，器公达精微。","付之元化柄，庶绩几纯熙。","兼职在国史，直笔信不疑。","皇皇君臣际，忠孝世所推。","宜其源流长，千载尚弗遗。","于今见远孙，大雅敦形仪。","银章佩县印，白玉涵山辉。","丈人与先翁，登科实同时。","相逢进馀烈，语讫及祖基。","家传唐相诰，绨袭常亲携。","焚香俾一读，令我增叹嘻。","玺文俨如新，是亦权公词。","顾郑崔许辈，其名各亲题。","邈然想高风，拂拂云雾披。","芬芳一何远，阴德未少隳。","几经兵火馀，定有神物持。","不落他人家，后嗣贤可知。","请令妙绝手，模将刻瑶琪。","传之固无穷，永作来孙规。"]},{"t":"观柳殿丞家藏竹柏图","f":"五言古诗","c":["君实名卿孙，妙画箧所聚。","壁间四幅画，收尽苍洲趣。","瘦柏盘大石，雪霜迥不惧。","举斧挥栋材，未辨在缣素。","离披老竹梢，直裂见枯处。","凤凰欲来巢，俯视犹屡顾。","壮观殊未已，白日去还暮。","愁怀起窗壁，注目乱烟雾。","烦君灯烛张，免我颜色沮。","乃知顷刻意，直有千载寓。"]},{"t":"李公择学士出示胡九龄归牧图","f":"五言古诗","c":["横披五尺素，中有万叠山。","山卜千丈溪，恍疑泻潺潺。","西风偃古木，惨淡秋色顽。","蓼红菱荇碧，缺岸如破环。","小舟半阁沙，茅屋深无关。","三牛行啮草，一犊随母还。","牧儿掣牛鼻，望家喜生颜。","欲知田家乐，此趣何由攀。","而况画手妙，意思能馀闲。","远出物象外，不在粉墨间。","临之发孤兴，飘忽辞尘寰。"]},{"t":"谢许栖默道士手写黄庭经见寄","f":"五言古诗","c":["与君有前期，共为名山乐。","十宿太上家，百骸失尘缚。","夜半瞻星辰，离离半空阁。","香氲结盖网，华灯焕朱琧。","金钟击清霜，远响答玄壑。","太霞无别境，洞章自酬酢。","君虽潜贱贫，志意在寥廓。","暂为处群鸡，曾是横空鹤。","一别几何时，又见圆蟾落。","长须俄及门，金石重然诺。","手写黄庭经，寄我辟邪恶。","我方闭空屋，隐几效南郭。","为君兴一读，玉液泻河洛。","何当结长游，相伴趋恬寞。"]},{"t":"蒋颖叔招游琅琊以马病不赴","f":"五言古诗","c":["一别隔千里，梦寐期追寻。","闻君宿琅琊，浩气酬云林。","雪霁望明月，山光如缕金。","天高归鸟尽，海冻诸峰沉。","骑鲸人已去，玉溜扬清音。","君当继绝唱，老凤霜梧吟。","释彼猿鹤怨，解此尘坌襟。","驽马鞭不行，空负希骥心。"]},{"t":"与柳丞夜话庐山","f":"五言古诗","c":["君家庐山下，我昔庐山游。","芜阴偶会合，共忆林泉幽。","山脚仙佛居，宝阁连琼楼。","客子多所至，未足勤吾求。","最爱山北冈，鸟道通岩陬。","其初惠远辈，遗芳至今留。","嵬峨定心石，欲脱如簪抽。","下视千仞溪，半空五云浮。","石门扼危磴，天瀑垂还收。","微风仙籁奏，灵草香气柔。","龙吟万壑响，桂子落三秋。","安栖虽未能，历览稍已周。","一别几三年，万事何悠悠。","日月随转目，霜雪易满头。","饥将无稻粮，寒亦乏衣裘。","虽非圣贤耻，自起妻儿羞。","慨欲携锄犁，为君耕旧丘。","经年饱蔬粟，吾道从休休。"]},{"t":"蒋颖叔席上","f":"五言古诗","c":["春风归未归，白日一何速。","偶陪御史骢，逶迤傍林麓。","名花结深洞，繁枝缀寒玉。","疏青爱老柏，壮节咏孤竹。","诸君皆俊贤，笑傲失羁束。","何生家最穷，昨日旋籴粟。","尚能邀我饮，盘馔逮张烛。","今夕宁须辞，酩酊固所欲。","醉则骑马归，官长定不辱。","酒行姑徐之，聊用讲心曲。"]},{"t":"自适","f":"五言古诗","c":["积忧避纷谤，杜门甘贱贫。","破屋败风雨，荒蹊绝车轮。","幸无尘坌集，静与凫雁邻。","吾年半已过，空花眷馀春。","往来犹康庄，安用烦距欣。","念此良自适，浩歌洗忧屯。"]},{"t":"溪上闲居 其一","f":"五言律诗","c":["溪头守穷屋，白昼常静卧。","唯闻鸟雀喧，岂有车马过。","苔沿土阶绿，风尖纸窗破。","遗编对古人，千载默相和。"]},{"t":"溪上闲居 其二","f":"五言律诗","c":["爱此城南静，穷年守茅舍。","无能聊自安，有智必趋诈。","红蕖笑池面，白鹭时时下。","呼儿补疏篱，选吉得天赦。"]},{"t":"溪上闲居 其三","f":"五言律诗","c":["衡茅颇幽独，物景资所好。","脩篁清风来，远渚晓烟冒。","才短难趋时，囊空不忧盗。","静几无纤尘，焚香读真诰。"]},{"t":"与内饮有赠","f":"五言古诗","c":["瓮中有浊酒，畦中多美蔬。","呼童取大网，更向溪中渔。","鱍鱍得鲜鳞，斫脍选肥鲈。","君生不能织，我生不能锄。","儿孙无白丁，生理已有馀。","陶然共一醉，隙间驰白驹。","倏忽各已死，体化委虫蛆。"]},{"t":"送湖南运判蔡如晦赴阙","f":"五言古诗","c":["鹗飞不在泥，决有青云趣。","凤凰不妄出，恐为时所误。","桓桓南都贤，幸遭明主顾。","垂绅正手板，磊落奏治具。","源流出无穷，胸胆豁以露。","帝曰卿良哉，予僚汝之父。","果见麒麟儿，腾骧蹈前步。","擢为东宫允，往漕八州赋。","予将观汝能，慎勿惮细故。","朅来重湖南，君恩密宣布。","拔才惟俊明，逐吏皆狡蠹。","朝廷方更化，免役出金助。","深沉详施为，委曲善告谕。","有司绝诛求，比屋乐农务。","贫富一以均，歌颂喧道路。","七月新书成，入奏驰骏驭。","君来万家春，君去秋色暮。","清湘似君心，偏使丑影惧。","何时到金阙，显用期必遇。","成法无瑕玼，后效有程度。","皇皇太上圣，赫赫师尹辅。","大业日愈新，虚怀未尝饫。","谏垣将峻陟，使节岂还付。","却忆仁祖朝，天下复庠序。","南都最为盛，万里英材聚。","严严高平公，明堂真栋柱。","尚书继踵来，两献仲舒疏。","君家有大阮，敛缩未腾翥。","名声晚乃达，霖雨今仍霪。","信哉颜渊氏，必用孔子铸。","邦家不乏才，社稷永盘固。","伊予亦何人，不异罝中兔。","时命适大谬，与物竟多迕。","卑栖邵陵幕，窃禄饱婴孺。","不才甘委置，朽木费吹嘘。","一朝逢知己，拔茅冀连茹。","翻思刷羽翰，翩翩厕鸳鹭。","不然弃已归，筑室幽闲处。","吐纳元和津，万事不挂虑。","韩子亦尝云，岂肯居沮洳。"]},{"t":"湘西四绝堂再送蔡如晦 其一","f":"五言古诗","c":["长城截湘江，盘盘据天险。","承平逾百年，民富德泽渐。","层居出云汉，门户当翠琰。","尤爱湘西山，佛寺金碧俨。","引泉甃深池，因崖起危广。","长松争嵯峨，众木就退敛。","远思秦汉间，疑此藏玉检。","盘石可径卧，苔发滑胜簟。","方塘才俯窥，引手取莲芡。","四绝校重轻，欧沈信已忝。","卓然韩杜诗，光焰不可掩。","大羹味全醇，美玉灭瑕点。","悄若蓬莱峰，夜浪岂忧飐。","又如上帝箓，默诵破群魇。","惟惊落俗口，一读一遭贬。","知音希世逢，谁谓此言谄。","穷奇须竟欢，忧来热吾脸。","不得陪俊游，自知冗官玷。","论情既霄壤，咫尺隔秦陕。","不为谢安侈，应慕杨绾俭。","赓酬继前唱，岩壁俟镌剡。","去为经世霖，慰此楚封歉。","离杯空酣酣，离恨犹冉冉。","雁鸣洞庭阔，霜雪鬓毛染。","行矣无淹留，路转双旌睒。"]},{"t":"湘西四绝堂再送蔡如晦 其二","f":"五言古诗","c":["尝读大易辞，可止戒遇险。","麓山俯城郭，盘盘进以渐。","重岗如连环，斗起若圭琰。","佛宫敞金碧，儒舍陋茅广。","修篁万兵肃，老柏壮士俨。","独鹤时一鸣，众鸟归翼敛。","兰风新麝裂，芰雨真珠飐。","虚堂群动寂，冠缨堕枕簟。","颓然委支体，清梦竟无魇。","引坑酌醇醑，激齿碎圆芡。","载歌少陵篇，一重复一掩。","桃源归路隔，回首惊俗检。","不唯纵逍遥，且喜远邪谄。","清湘稚子浴，其乐吾与点。","况闻长老言，了悟生理忝。","心如碧莲花，忍使红尘染。","又爱御史碑，白玉不可玷。","能忘迁谪忧，直笔正褒贬。","清旷终何为，名迹漫镌剡。","吾君方更化，凡百务节俭。","楚封劳贤侯，重地比二陕。","施为若霖雨，一饱苍生歉。","新法持以归，恋山休荏苒。","想当奏御时，和气动舜脸。","拜恩明光殿，日射腰金睒。"]},{"t":"高鸿送唐彦范司勋移苏守","f":"五言古诗","c":["高鸿方冥飞，万里不回首。","况当移杪时，霜露湿星斗。","鼓翼无何乡，永避网罗咎。","君子重出处，此义安可负。","嶷嶷潭府公，清誉比琼玖。","节制临八州，时命非不偶。","胡为请分务，念念在林薮。","切尝听公言，三朝禄食久。","四十有五年，数为漕与守。","慎事无纤瑕，收身养吾寿。","儿孙皆赏延，君恩诚已厚。","朝廷新法度，利害喧众口。","纷驰使者车，必行无可否。","嗟予力已疲，何以为父母。","不待老有请，连章至八九。","君相惜其才，符竹今仍剖。","苏台古名邦，震泽当户牖。","拜恩臣岂邀，客贺但挥手。","便道将径归，辞疾上印绶。","家园瞰西湖，云月是邻友。","翛然一榻外，长物复何有。","隐几悟僧禅，颓形若陵阜。","不学陶朱公，反为利端诱。","不学陶渊明，区区爱琴酒。","文王如搜贤，肯弃渭川叟。","行己无固必，资深逢左右。","重来作霖雨，一洗苍生垢。","信哉孟轲氏，和任著伊柳。","独善名易灭，兼济垂不朽。","噫嘻高鸿篇，在理或可取。"]},{"t":"送宋景瞻秘校赴选","f":"五言古诗","c":["我欲渡湖湘，君乃赴京阙。","官期安可常，念此千里别。","人生几何时，倏忽变华发。","难成唯功名，易往嗟日月。","在贵勿外矜，抱穷岂中热。","顾彼四老人，未尝事干谒。","一朝扶太子，千载名不灭。","安之命与时，为君颇详说。","西风吹月华，冷静若冰雪。","何处望乡关，乡关此时节。"]},{"t":"送郑说道太博监内法酒库","f":"五言古诗","c":["故人京洛来，共话十年别。","朱颜虽未彫，颇有鬓间雪。","夫君起文学，今乃官曲糵。","虽云屈雄才，犹喜待金阙。","朝政今更新，百执勇施设。","愿言慎所职，法酿务精洁。","上方祭祀馀，一饮兹以悦。","云霄即横飞，勉勉著勋烈。","行将鸳鹭群，何暇笑跛鳖。","跛鳖亦自知，中心冷如铁。"]},{"t":"寄别朱复之郎中","f":"五言古诗","c":["我昔发溪口，君来具华筵。","烛光射酒色，四座凝春烟。","饮阑赠嘉唱，响韵胜弹弦。","闻君今解印，念我簿书挛。","不及姑溪流，会随千丈船。","君才世无双，君名天下传。","五十试一州，治术如颍川。","上方争政务，下诏稽汉宣。","谁能荐此人，惟贤乃知贤。","聃聃范文正，道德诸公先。","辟君登幕府，师友金石坚。","大匠忽云逝，美璞畴敢镌。","古来出林秀，多为风雨缠。","明主往自结，献书玉墀前。","功名期待达，况当未衰年。"]},{"t":"留别受禅师","f":"五言古诗","c":["长沙多禅翁，受也予所慕。","清犹玉潭冰，不著纤垢污。","坚如岁寒柏，不入蝼蚁蠹。","一听玄谈玄，银潢自天注。","源流何其长，涌绝曹溪路。","请陈会面初，赤白照窗户。","短鞭驱瘦马，一蹶复一步。","北趋林下门，解榻欣我遇。","圆瓜剖青瑶，激齿寒浆聚。","支筇拈古语，法乐过韶濩。","廓然外生死，头角白牛露。","师云三百年，儒者莫尔悟。","自兹往游数，道合忘细故。","倏忽捧边徼，狡穴首招谕。","微功有司奏，一命金阙赴。","扁舟泊沙尾，行色业已具。","惆怅难再留，何以慰心素。","日月若驰駃，报体孰坚固。","愿期圆照中，生生迭相度。","回首欲无言，月上潇湘渡。"]},{"t":"送宝觉大师怀义还湖南","f":"五言古诗","c":["云收岳麓静，月渡湘水明。","独鹤唳空谷，哀笳奏重城。","巾屦尘坌远，怀抱冰霜清。","云何别彼土，忽作中州行。","中州七八载，浪得丹青名。","归心故岁发，白鬓新年生。","客帆欣所托，何时经洞庭。","逸笔写秋色，烟岚吹素屏。","殷勤远相寄，万里鸿冥冥。"]},{"t":"送僧白","f":"五言古诗","c":["我有高世想，喜逢高世人。","谈诗何所极，元化浩无垠。","物象不得晦，丹青亦通神。","逃名出京洛，寓迹遗埃尘。","锡飞天柱月，杯泛洞庭春。","问我别来久，请吟佳句新。","便欲结幽社，静栖还本真。","陶潜须一醉，宁起远公嗔。"]},{"t":"送僧琏","f":"五言律诗","c":["释从白云来，衣上白云湿。","借问来何勤，道师碑未立。","文言予岂能，孝节尔谁及。","却返旧山中，猿啼暮风急。"]},{"t":"送吴景山宫教供职","f":"五言古诗","c":["先生辞太学，得邑治阳羡。","仁义稍施设，浇浮遂丕变。","讼庭寂无事，案几闲笔砚。","青山落樽酒，白鸟聚畦甸。","长桥跨空碧，溪光拖晴练。","追随斩蛟处，想象昔人见。","高吟壮魂魄，老句掣惊电。","休焉聊自放，性理还吾善。","忽闻新天子，下诏罗俊彦。","教由宗族先，六经咨讲辨。","先生应诏起，肝胆露万卷。","制度惟日新，渐磨岂闻倦。","长苗忌速揠，良金务多鍊。","杳杳青云衢，阔步从兹践。","朝登诸王府，暮侍金銮殿。","勿兴山水思，固有夔卨愿。","寄声阳羡人，棠阴有馀恋。"]},{"t":"送周泳主簿","f":"五言古诗","c":["东风不肯住，发尽梅花白。","又着柳梢黄，摇摇向行客。","客行无时休，何以销客忧。","今古一樽酒，酩酊江上楼。","黄鹄飞青云，误随秋雁群。","网罗千万里，泾渭欲谁分。","诗思阳春发，平湖望明月。","若遇北归人，芳音无我绝。"]},{"t":"送钱公瑾长官","f":"五言古诗","c":["群山凌皓雪，修途无点尘。","寒梅数枝发，持送北归人。","人归向瑶阙，头角屈以伸。","十年困尘滓，一旦乘风云。","大用多晚年，请看钓渭滨。","又如四公子，长揖取名勋。","其馀琐细辈，为君何足陈。","我忝交君印，俯颜愧斯民。","疲驽追逸骥，浇漓杂醲醇。","物理有屯泰，贤愚固难伦。","感君重然诺，西郊待归轮。","非君肯卑屈，谁复许相亲。"]},{"t":"送陶秀才二首 其一","f":"五言古诗","c":["我爱陶渊明，隐不群异学。","今朝识其孙，璨璨真玉璞。","森然家风在，辩说倾电雹。","江头偶逢我，笑我何龊龊。","恨不从君去，高飞同饮啄。","顾此翅翎短，岂能超五岳。","我止愁复愁，君行乐其乐。"]},{"t":"送陶秀才二首 其二","f":"五言律诗","c":["江天九旬雨，江路三尺泥。","扶家遂远适，羸马正难骑。","传舍野烟中，子规连夜啼。","乡园归得到，应已血沾衣。"]},{"t":"送朱伯原秘校","f":"五言古诗","c":["泠泠皖溪水，悠悠天柱云。","云行水光动，水洗云影分。","幽人坐卧吟，孤绝迥出群。","资彼云水秀，释此尘垢纷。","胡为倏言别，扁舟连夜发。","往登姑苏台，而望太湖月。","却寻史迁迹，但见苍烟灭。","览古竟论今，治具校工拙。","有才不得施，著书贻后世。","何必腰黄金，自享千载贵。","鲈鱼秋正熟，云泉味尤美。","若逢吴市门，更访长生理。"]},{"t":"同蒋颖叔游丁山彰教寺","f":"五言古诗","c":["北风方苦寒，冰霜昼未消。","偶倾御史盖，同上丁山椒。","空崖白云宿，拱木猕猴跳。","碑皴龟腹裂，泉活龙尾摇。","枯松起幽籁，中天奏云韶。","苔深鸦发翠，石立壮土翘。","荒坟瘗参军，沉魄谁与招。","却读乐安词，惨淡窥泬寥。","矧复见犹子，危言动清朝。","甘心脱豸冠，窜迹投冗寮。","公议在后世，美才无吝骄。","六经收满腹，辨析皆有条。","登山听君语，淙淙碎琼瑶。","但惊白日落，归驭不可邀。","明发余亦往，安得同渔樵。"]},{"t":"招蒋颖叔游丁山彰教寺","f":"五言古诗","c":["閒心乐名山，景象恣吟剽。","昭亭西南隅，乱峰最青峭。","盘盘得修径，豁豁渐明眺。","一读道旁碑，古兴恣雅要。","知有金仙家，即往不俟召。","平田转回塘，飞瓦接危峤。","东边卧石虎，徐王旧坟兆。","但惊深藓晦，不见金碧耀。","图形半残缺，冷榻孤灯照。","深篁归鸟没，空岩雪风叫。","敕书刊翠琰，灵迹获猎烧。","寒潭多蛰鳞，佛子忌渔钓。","动活各遂性，蕃衍理可校。","馀晖初月散，幽籁发玄窍。","中有无心人，禅禅自相绍。","问年踰耳顺，肤色尚如少。","翻令念达人，鸿蒙首频掉。","时平冠佩繁，往往属不肖。","岂如弃以归，林泉自投跳。","卓彼蒋夫子，诗辞极精妙。","能来同我游，险绝共长啸。","终当为君诵，古律变新调。","更评江南事，僣迹又足悼。","不能降真人，卒用焚祖庙。","训狐啼老木，愁烟起荒藋。","复有贰卿碑，曾为参军吊。","勇为手势吟，一助玉瓶釂。"]},{"t":"同蒋颖叔殿院游昭亭山广教寺","f":"五言古诗","c":["晴光散馀翳，佳辰值清和。","联车不辞远，共登昭亭阿。","步夷惬苍石，缘险扪修萝。","迥出白云上，俯瞰飞鸟过。","凌霄插危观，裂地注明河。","微风解兰芷，广陂浴凫鹅。","潭潭紫华君，左右森矛戈。","雷电在呼吸，玉帛荐牲牺。","庙食溢千载，祐民理无讹。","崔碑梦恊吉，谢守诗载歌。","却憩林下寺，裴颜迹尤多。","丹青业已晦，长髯但皤皤。","笔画肖家法，燕尾无偏颇。","览古发遐想，缘情还独哦。","逢时不荣达，憔悴同苫蓑。","嗒焉姑自丧，安之如命何。","彼美蒋御史，道术追雄轲。","眄予委泥涸，有意倾馀波。","荐士古来重，披剑今则那。","书为昭亭篇，昭亭崖可磨。"]},{"t":"同许栖默游华阳洞","f":"五言古诗","c":["春归白昼永，庭虚民事退。","寻幽何所之，佳宾幸同载。","出门十馀里，仙者馀迹在。","非实固难评，洞壑茅可爱。","绿萝垂长帘，秘景得藏晦。","造深揭苇火，陟险汗渐背。","中宽稍可休，仰视覆圆盖。","石乳忘岁年，物象千万态。","龙泓绀澄碧，溢溜渐飞洒。","阴森毛骨寒，志往力殊怠。","磨崖记名姓，斯游定难再。","人生足离合，世役异屯泰。","清风起林杪，萧瑟动天籁。","归欤亦何求，盈筐采兰艾。"]},{"t":"同刘继邺秀才游岳麓登法华台呈如水长老","f":"五言古诗","c":["南出长沙城，西渡潇湘水。","谁铺碧鲛绡，迥透黄金底。","中分橘直洲，隐若鳌背起。","府邑古称雄，地势信少比。","苟非仁义图，畴将甲兵洗。","晚色烟雾开，人家明镜里。","斯须舍舟楫，纵步踏兰芷。","遥遥望松门，物象愈奇伟。","枝叶既不繁，霜雪讵能毁。","传云陶将军，屯营手植此。","至今凌云气，犹如大君子。","才过清风峡，路转不容跬。","尘寰自此隔，佛界朗瞻跂。","层梯上重门，绘塑光炜炜。","皓鹤去无踪，寒泉但清泚。","遂登法华台，平目瞰千里。","返惊人世卑，堑壁徒为耳。","连甍十万户，罗列在案几。","想当韩杜时，荆棘晦遗址。","不见湘西篇，惟誇道林美。","幸同刘子来，纵视眼不眯。","作诗君勿谦，前辈尚可拟。","挥笔方争豪，求心翻自鄙。","请看梁上题，半是泉中鬼。","白发缠利名，何由外生死。","道师深悟禅，软语听亹亹。","明驱三乘车，济我岸超彼。","台名将谓何，此喻有深理。","香色存天然，了不染泥滓。","救物运真悲，得法终日喜。"]},{"t":"游云盖寺","f":"五言古诗","c":["名山寺多占，此寺山尤名。","妙云镇弥覆，层层结缦缨。","日光昼微开，灿射黄金城。","木老枝叶简，水长音韵清。","五峰如绀莲，中有楼殿横。","是必龙华宫，禅禅悟无生。","一灯破群暗，众灯迭相明。","纷空素葩坠，悲晚孤猿惊。","予方困邅途，寓宿骨已轻。","愿言永栖此，读尽宝藏经。","顾盼适所适，了绝物外营。","马秣仆亦饭，奈何催北征。"]},{"t":"游鹿苑寺","f":"五言古诗","c":["游遍湘西山，晚至鹿苑寺。","平冈列城郭，长松肖兵卫。","入门尤清凉，读碑辨往事。","乃知阿育王，曾此藏舍利。","浮屠当殿阴，令人竦瞻视。","宝网敷金云，倏忽变苍翠。","僧云秋杪时，月静甘露坠。","大觉去无踪，山祗自灵异。","白鹿不我逢，残花在岩际。","居者多寿老，安禅信无累。","筇衲为生涯，心不坠情伪。","源源听法语，陶陶袭和气。","簪绅胡为乎，顶踵缚忧愧。","愿从彼上人，预闻第一义。","烦心沃醍醐，顿悟超十地。","聊为鹿苑吟，清梦不成寐。"]},{"t":"游华阳洞阻雨","f":"五言古诗","c":["此洞昔无闻，人迹固稀到。","一昨紫微游，刻石记所好。","遂令天下知，游者争欲造。","我方佩县印，事閒慕高蹈。","联镳二三子，并坚松柏操。","樽罍薄携持，丁壮却前导。","行行逼崖巅，紫翠射襟帽。","方疑攀郁萝，又若堆海潦。","石门未及窥，忽值山雨暴。","风云暗衢路，雷电拆岩峤。","苍黄仆夫语，踊跃猿猱叫。","黄泥濡衣裳，安得白日照。","初游成欢愉，中险触愤懊。","佛舍距几何，望望目睛眊。","击镫促疲马，十步九攲倒。","登堂亟就榻，释子数相劳。","寻幽尚龃龉，处世信难料。","暂眠稍苏息，起坐复悲啸。","宁非山鬼护，不使俗客眺。","桓桓翠琰文，愈读愈精妙。","名由今日新，迹入万古耀。","骐骥步莫追，驽骀志弥劭。","犹期六月来，散发避炎燎。","一雨路阻绝，何以为壮少。","归欤歌芜词，聊为起同调。"]},{"t":"夏日游环碧亭","f":"五言古诗","c":["登山得斯亭，佳宾幸过从。","取笋苍玉林，置酒黄金钟。","愿言寿而康，泰运宁易逢。","孔孟陟三事，尧舜乘六龙。","民财皆辨析，田壤仍登丰。","关关禽声和，剪剪木影浓。","濯足就绿水，披衣揽清风。","微吟百忧散，达道千古同。","诸君况才豪，如罴复如熊。","莫辞烂醉归，皓月还生东。"]},{"t":"和颖叔丁山黯字","f":"五言古诗","c":["寒日少晶光，山色亦惨惨。","瀑泉冻不飞，啼鸟声顿减。","传呼绣衣来，僧鼓击坎坎。","石坐无毡裀，团团织蒲菼。","比为泉石游，固已慕清淡。","爱君神采瑩，皎若白玉鉴。","一登林际亭，毫发无遗瞰。","勇起发孤唱，四坐噤莫阚。","君辞如太羹，我语效盐咸。","卷旗促降敌，贤将释不斩。","虽生已包羞，铅刀竟谁錾。","却读道旁碑，往事增新感。","功名能几何，回首岁时暂。","胡为夺浩气，百忧煎一胆。","趋时既迍邅，独往固勇敢。","白云无人争，皓月从我揽。","开樽直一醉，莫惊别袖掺。","明发何所思，龙断坐汲黯。"]},{"t":"和梅谦叔丁山吃字","f":"五言古诗","c":["腊月衣未绵，两股冻成疾。","谁复为我扶，平步时时蹶。","文章那更论，精魄恐坠失。","缘何御史君，相招傍寒日。","迤逦造林泉，尘坌为披拂。","霓幡云外垂，石虎草间出。","深门窥泬漻，拱木递萧瑟。","丹青与老碑，遗事知彷佛。","僣迹已榛芜，新游论胶漆。","主人才何如，骥足千里逸。","梅君南昌后，襟韵犹凄溧。","刘子亦可奇，彖象久精诘。","顾予最空疏，百辨今已吃。","谤言来戈矛，自量几不密。","终甘首阳饿，岂效操瓢乞。"]},{"t":"酬颖叔见寄","f":"五言古诗","c":["铿铿南华经，语意妙复妙。","高能出苍旻，卑不厌藜藋。","阴静偶暂处，影迹两莫吊。","息踵真人徒，息喉愚者绍。","方同造物言，万变领枢要。","既能无怛化，勿凿混沌窍。","百家拾其馀，所得及遗溺。","至音听以气，世或昧此调。","不见杏坛讲，犹为渔父诮。","君看泰山顶，半夜日先照。","惟逢蒋颖叔，沉默造玄窔。","落笔逾万言，严密若诰诏。","嗟予久聋瘖，此道雅未剽。","一昨闻君谈，神悟百骸疗。","人忘道术游，鱼忘江海跳。","昭亭果见期，为子发长啸。"]},{"t":"秋水阁席上呈颖叔原道","f":"五言古诗","c":["吾爱秋水阁，水影照采椽。","瑩碧不知极，定与银汉连。","荷花十丈开，白藕想如船。","双鹤时一鸣，寒霄下回旋。","况复对羽客，岂异蓬莱仙。","便当沽玉液，猛饮明月前。","人生不嗜此，何物能逃年。","请君倾醉耳，松风奏薰弦。","身世能两忘，安用养浩然。","梦觉事已殊，此道谁能全。","驰驱冠剑徒，百岁犹倒悬。","深深下于地，冥冥高出天。","君语达已达，君歌玄复玄。","大笑问刘子，细穷秋水源。","秋水源可到，更寄琳琅篇。"]},{"t":"酬耿天骘见寄","f":"五言古诗","c":["追维平昔游，十几丧六七。","与君虽尚在，踸踔各衰疾。","功名无几何，岁月忽已失。","伻来辱新诗，欲和久阁笔。","文章老愈精，光彩烂星日。","市门果神仙，参军真俊逸。","又如窥沙漠，铁骑万馀匹。","一战孰与当，百胜得深术。","有过惧不闻，愚恶志所嫉。","言归洁其身，天命能自诘。","知音我愈寡，深谷讵敢出。","相望止一江，高议容接膝。","请观商山皓，宁终守蓬荜。","众人拉其华，君子俟其实。","定当卜邻去，携手藏于密。"]},{"t":"酬李公择谢予赠范李猿獐","f":"五言古诗","c":["黄獐雄领雌，青猿母抱子。","一落罝网中，城市就生死。","不如图画上，山深石泉美。","永无罝网忧，精神自全耳。","爱之写横轴，容易披案几。","动静适自感，物我忘表里。","犹疑跳踯去，毫端讵能止。","易生名独擅，斯人嗟往矣。","后来称李范，赠君君勿鄙。","纵令笔未妙，犹胜负涂豕。"]},{"t":"同陈公彦推官登峨嵋亭","f":"五言古诗","c":["新亭彼谁搆，名因翰林揭。","惟南极空旷，朗咏佳兴发。","倾盖忘形骸，辄莫叹华发。","归帆天外低，渡鸟云端没。","中原峥嵘际，天堑限楚越。","宁知承平来，但见山花歇。","君相方圣贤，胡为念京阙。","但穷林泉乐，蹑屐上崷崒。","酒量孰先降，樽罍未云竭。","欲寻太白坟，草间迷断碣。","神交无古今，清风来飘忽。","征辔还催人，东峰挂寒月。"]},{"t":"颖叔见招赴何秀才家饮","f":"五言古诗","c":["鞭驴赴君招，十步九蹶促。","相逢即忘劳，深围坐重褥。","恍疑出尘寰，气象豁双目。","名花散天香，仙露浥柔玉。","寄乐方寸间，岂必待华屋。","脱屣远市朝，散发免羁束。","更闻诵新作，字字芝兰馥。","堆盘樱实红，满斝酦醅渌。","幽欢未言归，酒令不须督。","平时常卷舌，动静畏险俗。","玄谈今尽倾，我难惬君欲。","朝闻夕可死，悟矣无迟速。","感君倾醍醐，洒我久饥腹。","又如旱田禾，沛然甘雨沃。","主人意殷勤，呼儿具灯烛。","谁家有斯客，贳衣心亦足。","明朝得长篇，调险不可续。"]},{"t":"和公择观李煜书法喜禅师碑","f":"五言古诗","c":["五代迭凋丧，江南最偷安。","三世弄翰墨，煜札尤可观。","禅林榜法喜，妙势如飞鸾。","尘埃一藏晦，皴斮脱羽翰。","适逢集仙守，好古将模刊。","振襟自披拂，涂饰粉与丹。","呼僧辨遗像，彷佛存纤纨。","作书究本末，风雨生毫端。","精神还故物，霹雳惊蛰蟠。","幽光亦焕发，令我复长叹。","念彼士君子，穷年抱饥寒。","不及稽古踪，泯默知遇难。"]},{"t":"和樊希韩解元","f":"五言古诗","c":["君马一足病，琐琐阻行迈。","况复梅雨天，坐卧不能快。","空山无大脔，何以具君嘬。","墙根采肥杞，湖漘买鲜鲙。","开樽荐浊酒，高论幸忘惫。","寸心拔茅塞，两耳抉双聩。","文醇潜大和，诗险露幽怪。","联吟极物象，君胜我屡败。","东野久龙钟，多惭退之拜。","奇才必自重，虽黜愈勿懈。","卞璧未遇时，在璞岂能坏。","鉴赏一日逢，青紫信如芥。","君行且迟留，马病愿未差。","贳衣亦何辞，庶用接嘉话。"]},{"t":"和公择游寿圣院啜茶题名","f":"五言古诗","c":["史君尚清净，携客无杯肴。","茗酌诵佛经，尘缘顿沉抛。","疏云堕檐际，微风汎林梢。","吾心已皎皎，我学岂譊譊。","濡毫题名姓，识此逍遥交。"]},{"t":"和法宗上人月下怀故人","f":"五言律诗","c":["山沉江海阔，月行天中央。","游子宿何许，只应归梦长。","浮云且莫生，星河助馀光。","徘徊问孤影，惆怅安可忘。"]},{"t":"酬耿天骘见寄","f":"五言古诗","c":["我思昔人言，处世犹大梦。","尘编堆床头，抚事聊一诵。","兴衰系时运，贾谊尔何恸。","又思东方朔，为鼠知不用。","谁怜胯下儿，能领百万众。","势去竞诋排，功成乃歌颂。","人情岂相远，此理古今共。","桓桓耿夫子，策射金榜中。","老彼涧底松，未作明堂栋。","暂来令句曲，寻仙造深洞。","摩挲瑶琪花，借问谁所种。","开落既忘年，一奏熏风弄。","诗言此归隐，不恋五斗俸。","何时定挂冠，我愿为仆从。"]},{"t":"和韩求仁推官","f":"五言律诗","c":["终日汩城市，閒心眷犁锄。","故登原上亭，解此尘中裾。","芬香采薇蕨，驯狎怜麋狙。","却愿物理变，四角生我车。"]},{"t":"樊山","f":"五言古诗","c":["汉室火符熄，群雄起纵横。","两京荡为墟，万里无农耕。","曹操劫神器，欲窃禅让名。","吴蜀耻北面，鼎峙方战争。","杀人如鲙鱼，天地厌血腥。","至今武昌邑，尚传吴主城。","长江吞八极，圆坛窥杳冥。","想当禋郊时，志勇扫搀抢。","燔柴封玉牒，冠弁罗公卿。","登山锡宴喜，日光烂旗旌。","宁知后嗣弱，壮业竟无成。","空馀旧基址，千载未攲倾。","常时屡掩卷，每读涕泗盈。","而况泊舟楫，披榛自径行。","霸图何所见，芳草与云平。","晚浪淙石脚，犹疑兵甲声。"]},{"t":"观怡亭序铭","f":"五言古诗","c":["有唐三百年，绝出阳冰篆。","最怜怡亭序，笔画兼众善。","磨崖深云间，人迹到应鲜。","亦如大君子，隐晦久而显。","裂素印麝煤，字字未讹舛。","冰冻垂瓦石，犀尖利刀剸。","连环不可解，虬尾勇自卷。","谁云模以刻，曾是玉工碾。","铭辞志尤宏，云翼待风展。","琳琅谐八音，雅重参二典。","英豪逢一时，江山供广宴。","遗踪逐飞鸟，旧址没榛藓。","良朋信稀遇，古兴浩难遣。","吾宋垂百年，教化固非浅。","人人擅文翰，比唐殊媚软。","作诗聊自惊，中道尚可勉。"]},{"t":"殊亭","f":"五言古诗","c":["昔人才行殊，亭名至今在。","何年复基构，势压鲸鳌背。","中间鄙俗令，元碑遭睚眦。","豺狼尔何营，龟螭手亲碎。","甚哉憎疾心，曾不校异代。","我将掇其馀，补刻尚可再。","仰瞻天宇宽，俯视江流大。","危危一叶舟，故欲万里迈。","差池想遗风，云山有殊态。"]},{"t":"怡亭","f":"五言古诗","c":["英才欣会遇，旷怀各无瑕。","二李妙分篆，裴铭语尤嘉。","盘盘虬奋鳞，灼灼月吐华。","天影望不尽，雁行飞屡斜。","晴云依晚岫，芳草接平沙。","东溟与西塞，吾宁辨渚涯。"]},{"t":"石门","f":"五言律诗","c":["双崖屹然起，剔藓认题识。","乃知贤令尹，曾同漫叟醉。","落景正西尽，长川自东逝。","唯此两石门，不开亦不闭。"]},{"t":"郎官湖","f":"五言古诗","c":["张公昔爱湖，湖名自公始。","寥寥三百年，逢秋愈清泚。","移船菱荇香，游鱼数赪尾。","回望武昌郭，楼台碧天里。","石照泻灵光，湖波皓如洗。","此景绝世无，爱之心不已。","缅怀昔贤期，林表清风起。","终当归结网，来此养衰鄙。"]},{"t":"峰顶","f":"五言律诗","c":["登山不辞险，探景须穷幽。","行彻五千仞，回首视九州。","人寰莽何处，大野苍烟浮。","更酌天池泉，古意空悠悠。"]},{"t":"醉石","f":"五言古诗","c":["裂嶂飞寒涧，绝壁散明珠。","盘石偃中坞，修林阴翳敷。","世道纷莫救，逸人此提壶。","一酌寄乾坤，回首忘车书。","山花谩相笑，山鸟徒相呼。","更逢山月来，夜响真笙竽。","粹灵淘耳目，幽独宁贤愚。","留踪千载间，游子空踟蹰。","清风起木末，馀凉生坐隅。","浩歌歌去来，逸韵凌遥虚。"]},{"t":"洞庭阻风","f":"五言古诗","c":["南风吹炎蒸，岁望固已休。","怒涛掀洞庭，信宿留归舟。","沙场万马放，大壑群龙投。","阴灵孰尔职，曾无与天谋。","崩山作深潭，深潭变高丘。","上天有号令，岂汝可自由。","朝蝇徒咂咂，暮蚊况啾啾。","归兴邈以阻，触绪增新愁。","安得跨白鹿，山行肆悠悠。","谁能守荒浦，泛险终何求。"]},{"t":"濡须山头亭子","f":"五言古诗","c":["孤亭压危峰，绝景入平眺。","双崖控巢水，禹力万古耀。","林倾乾象辟，涛淙地轴掉。","茅茨数椽屋，噫哉魏武庙。","心殊岐山伯，迹异甘棠召。","荒戍传遗灵，血食岂亡诮。","吞吴势虽壮，晋起国旋剽。","楼船战士去，沧浪尽鱼钓。","平时欲何为，览古谩长啸。","愁烟起孤壑，白鸟聚残照。","谁令五月来，不见万山烧。","又复想大雪，下上玉岩峤。","重游莫能期，将归且停趬。","诗辞搜亦苦，物状竟难肖。","终篇写亭壁，翻惭画师妙。"]},{"t":"谒桐乡张府君庙","f":"五言古诗","c":["桐乡富山水，此地最深秀。","诸峰合屏围，二冈屹龙斗。","谷暖禽语滑，岸束溪声逗。","老木如巨贤，森卫备前后。","神功金刻存，庙古何年构。","衣冠近唐人，名字嗟莫究。","悯旱鞭怒蛟，深潭此身仆。","明诚动苍天，雷雨洗白昼。","至今福斯民，血食固宜厚。","予生本屯贱，窃位忧致寇。","约身既多缺，何以抚耆旧。","况瞻贤达迹，彼美松柏茂。","芳醪荐樽爵，馨蔬实笾豆。","悠悠神之思，馀光破昏愗。","归欤歌芜辞，聊用答灵祐。"]},{"t":"大风","f":"五言古诗","c":["一鸟忽惊鸣，众鸟高下噪。","飘风自南至，汹汹结阴瀑。","须臾江涛翻，石裂巨木倒。","禾麻安愗论，畦陇漭若扫。","苍天本好仁，孰使风伯暴。","有叟重咨嗟，吾年行已耄。","此风未尝见，神理所诫告。","我因谕彼侬，天地广覆焘。","噫气亦偶然，何必泥应报。","掉头不吾顾，植杖复悲悼。"]},{"t":"兰陵请雨","f":"五言古诗","c":["夜半何所适，请雨之名山。","兰陵古仙府，妙迹殊可攀。","秘文呼蛰龙，舒雁荐层坛。","屏气注诚想，百灵启玄关。","绿章封事奏，金阙承恩还。","林风生泠泠，涧溜添潺潺。","遥峰霭冥雾，倏歘迷区寰。","殷雷无猛威，激雨增微澜。","宁独濡枯焦，永愿清尘烦。"]},{"t":"观雨","f":"五言古诗","c":["不雨九十日，火气流郊郛。","空山渴虎兕，涸泥困龙鱼。","农事固骚屑，令人但长吁。","渺思真宰意，反复竟何如。","去岁百川溢，园田变江湖。","南民遂乏食，十九弃路衢。","那闻今秋旱，性命当无馀。","祀龙稽往法，击鼓烦群巫。","殷殷百里雷，奋自东南隅。","阴云随电合，密雨应时须。","驰驱苍黄际，惨淡气色苏。","登楼注远目，百忧聊涤除。","银浪彻平地，玉绳迷太虚。","日月洗尘坌，山川改焦枯。","法宫朝大舜，冠佩皆鸿儒。","况当礼乐新，百灵共持扶。","和气自兹肇，风雨安敢逾。","欲传千岁音，咏言愧蘼芜。"]},{"t":"春日怀桐乡旧游","f":"五言古诗","c":["二年桐乡邑，乘春览荣芳。","日日绕花树，与客倾壶觞。","况有青涧泉，潺潺穿北墙。","容为方广池，白虹卧危梁。","谁磨青铜镜，朗照红粉妆。","唯恐浮云来，遮我逍遥场。","舞娥回皓雪，笛叟鸣凤凰。","醉则卧花下，所惜徂春阳。","作诗数十篇，素壁挥琳琅。","诏书徙幕府，笼鸟无高翔。","却治历川狱，幽忧坐空堂。","有女杀其母，逆气凌穹苍。","郡县失实辞，吏侮争持赃。","辟刑固无赦，何以来嘉祥。","高垣密阍禁，但觉白日长。","茫然思旧游，今成参与商。","世网未能脱，乐事安可常。","咄嗟勿重陈，昏昏灯烛光。"]},{"t":"东望","f":"五言古诗","c":["历阳望姑熟，抚掌衣带隔。","却瞻天门山，落日一双碧。","不如云中鸟，自在鼓两翼。","冠裳漫羁绁，发绿今已白。","功名随浮烟，所得乃禄食。","天兵下安南，獠穴须灭迹。","腾山吼豺虎，跨海轰霹雳。","杀气暗南溟，万古一洗涤。","借令伏波在，缩手定叹息。","男儿逢此时，弗往荷矛戟。","胡为守文法，铢铢较朝夕。","终当解官去，大舰挂长席。","乘风捲云涛，载月奏玉笛。","不作凌烟人，犹为钓鳌客。","谁能对乡关，跬步归未得。"]},{"t":"把镜","f":"五言古诗","c":["念念递迁谢，新新来未停。","把镜览素发，不觉今年生。","生世能几何，焰长烛愈短。","劝吾杯中物，到手莫辞满。","阳春才烂漫，花片已飞舞。","纷如晴后雪，半作燕巢土。","尧舜竟何在，楚汉空战争。","胜负一日事，寂寥千载名。","隐几聊自悲，悲竟复长啸。","真体元空无，谁与我同调。"]},{"t":"望白纻山","f":"五言古诗","c":["隔江望白纻，葱苍压牛渚。","却忆跨黄犊，渡桥溪东去。","悠悠登此山，直待圆蟾午。","汗漫丹湖水，万顷浸天宇。","北斗酌不乾，光烱反吞吐。","诸峰若案几，白云俯可取。","览景壮我怀，长谣念前古。","传闻桓将军，致酒领歌舞。","雄风回秋霜，英声散鼍鼓。","宁知千载后，荒榛老狐鼠。","男儿及时乐，一饷亦足许。","前年翰林公，绝顶构堂庑。","我方客沅湘，盛事未能睹。","及今佐肥幕，治狱历阳府。","注目聊独吟，何时达庭户。"]},{"t":"合肥何公桧部使者杨公潜古命予赋之","f":"五言古诗","c":["合肥有老桧，得名自何公。","何公何代人，名迹了莫穷。","高枝偃羽盖，低枝卧苍龙。","盘根彻厚地，疏影落寒空。","荏苒九天碧，仍为烟雾濛。","相传魏武帝，解甲休铁骢。","尝坐此桧下，吞吴未成功。","至今晦暝夕，往往扬英风。","我公心好古，清标耸千峰。","鉴赏挥巨笔，丹青孰为工。","璨璨发明玉，琤琤叩丝桐。","谈笑走兵役，垣墙密泥封。","拂拭枯折干，一助春风融。","愿回拔山力，移植明光宫。"]},{"t":"怀平云阁兼简明惠大师仙公","f":"五言古诗","c":["跨空起高阁，北望敬亭山。","白云无根蒂，舒卷随风还。","或堕溪水上，却萦松石间。","就之既明灭，了然不可攀。","谢公赛雨诗，千秋泻潺潺。","李白弄月处，寒光湛清湾。","神交自冥合，彷佛眉睫间。","使我恋此境，每来终日閒。","如何一挥手，失势落尘寰。","功业复未就，但惊须鬓斑。","沧浪不可濯，执热长汗颜。","缅怀大道师，焚香坐玄关。","悲心度群苦，振锡鸣金镮。","行当禀慈诲，惠照开昏顽。"]},{"t":"和耿天骘见寄二首 其一","f":"五言古诗","c":["熠熠阳气动，春事不可禦。","君家富林园，宴豆乐宾主。","况当解官归，精魄还六腑。","或乘青板船，纵缆东溪浒。","溪光如碧玉，皓月无人取。","信哉浴乎沂，点也丘所与。","又闻全于天，卓越庄周语。","我方治幽狱，归期日日数。","读君新诗章，对面若吴楚。"]},{"t":"和耿天骘见寄二首 其二","f":"楚辞体","c":["猛风卷长江，惊湍势莫禦。","虬龙元喷薄，阴怪岂无主。","扁舟未能往，何以慰心腑。","想君东城居，林花烂溪浒。","浊醪初酦醅，豚鲚又新取。","论诗予素降，泛爱君独与。","一闻韶濩奏，卷舌欲无语。","却瞻项籍祠，绘画安足数。","怅然歌虞兮，炎汉已得楚。"]},{"t":"对酒爱月示客","f":"五言律诗","c":["谁云月无私，那知月有情。","我住月亦住，君行月亦行。","致此一壶酒，都忘千岁名。","胸中各有月，莫遣暗云生。"]},{"t":"望牛渚有感三首 其一","f":"五言律诗","c":["身滞历阳浦，心倾牛渚云。","圣人开六合，于此渡三军。","霸气扫无迹，神功千载闻。","明朝有归兴，石上洗尘纷。"]},{"t":"望牛渚有感三首 其二","f":"五言律诗","c":["遥怜牛渚矶，柳带拖春绿。","归思无时阑，断弦声自续。","更听渔父吟，悠扬写心曲。","何日效斯人，烟波洗双足。"]},{"t":"望牛渚有感三首 其三","f":"五言律诗","c":["江迥偏留月，山空不住云。","遥怜李太白，曾忆谢将军。","帆影随潮上，樵声隔岸闻。","柳花迷客眼，三月雪纷纷。"]},{"t":"毂毂","f":"五言古诗","c":["毂毂复毂毂，怪禽安用啼。","杏花已烂漫，月色正相宜。","提壶取新酒，酌我金屈卮。","行恐风雨来，乱红辞旧枝。","尚恨碧城锁，阻邀白雪姬。","耳边无清歌，素饮方自怡。","尔何骋鸣声，弹射不肯飞。","初亦厌尔聒，既久不复疑。","但能怖愚俗，又足惊童儿。","天翁造尔躯，无乃私自欺。","爪吻异雕鹗，安能司祸机。","又不似群乌，凶报吉亦随。","白日窜深棘，夜鸣殊不栖。","劝尔勿毂毂，凤凰倏来仪。"]},{"t":"登历阳城望凌歊台","f":"五言古诗","c":["平昔登凌歊，西望历阳岸。","江空芦苇阔，日落烟雾散。","倏然别乡国，三载客淮甸。","赏心无复有，离渚但纷乱。","迩来治冤狱，文字堆几案。","置之步城堞，山川却对面。","崔嵬浮图出，巨笔插天半。","秀色凌丹青，长毫蘸河汉。","翻思宋武帝，此地尝壮观。","美人厌烦暑，挥衣待霜霰。","流芳千岁间，陵谷未云变。","碑阴杜牧题，缺玉稍可辨。","归魂招不得，旧土常情恋。","时作梁甫吟，清风忽吹断。"]},{"t":"怀当涂石城寺","f":"五言古诗","c":["城东二十里，寺有古石城。","过尽绿桑野，还依流水行。","水穷山亦合，老木一区平。","藓留虎豹迹，岩多猿狖鸣。","楼殿横涧阴，像塑铅黄剥。","庭中有高花，碧叶抱丹渥。","不知何岁年，舂容镇柔濯。","山僧亦庞眉，发语颇真朴。","却读罗泰碑，始知征战场。","赤谷纳箭血，夜鬼嗥冷创。","云雾第黯黪，英雄今则亡。","谁建大法宇，救援弘津梁。","每来即忘还，览古恣吟眺。","沿崖采菖蒲，兴发辄长啸。","偶随辟书起，末路遂难料。","十年未能归，应为山僧诮。"]},{"t":"昨游寄徐子美学正","f":"五言古诗","c":["念昔未弱冠，与君昆弟游。","各怀经纶业，壮气凌阳秋。","知音得袁宰，鉴赏称琳璆。","君家天地崩，泣血城南陬。","释服就乡举，名姓必见收。","数为礼部黜，考命宁怨尤。","子山仅五十，感疾遽不瘳。","子美如孤鸿，哀鸣大江头。","其声最酸楚，闻者皆涕流。","有才多困蒙，此理不可求。","我初佐星子，老守如素仇。","避之拂衣去，寓迹昭亭幽。","篇章自此富，写咏穷欢忧。","慈母待禄养，复尉湓浦州。","随辟宰环峰，碌碌三载周。","才归遭酷罚，五体戕戈矛。","旦夕期殒灭，馀生安敢偷。","粗能襄事毕，寒饿妻儿羞。","复入湖外幕，万里浮扁舟。","几葬江鱼腹，迍邅百端愁。","到官未三月，开疆预参谋。","招降五万户，给田使锄耰。","论功辄第一，谤语达冕旒。","得邑敢自诉，断木当沉沟。","儿女相继死，泣多昏两眸。","脱去殊未能，游鳞已吞钩。","春风吹瘦颊，黄尘蒙弊裘。","才趋合肥府，又鞫历阳囚。","荒庭忘岁月，忽见花枝柔。","清明动乡思，一水嗟滞留。","却忆藏云会，雕盘荐珍羞。","高吟凌李杜，猛饮咍阮刘。","野寺想如昨，游人今白头。","倏忽三十年，老大功名休。","日毂不暂止，吾生信如沤。","有酒尚可醉，馀事皆悠悠。"]},{"t":"送宋前之赴调","f":"五言古诗","c":["东冈送终毕，北堂待荣养。","短箠跨羸驴，西风吹祖帐。","玉盘堆鲙缕，金船倒新酿。","劝君当勇去，回首勿悽怆。","胸中五千卷，立事须少壮。","扬名永不灭，孝节乃可尚。","长安集纷华，出处慎所向。","肯为声色惑，一婢百金偿。","不知粉黛蠹，血气迷凋丧。","胡为发斯言，期予以相将。"]},{"t":"浪士歌","f":"五言律诗","c":["江上浪如屋，海中浪如山。","浪士乘浪舟，兀兀在浪间。","浪头几时息，士心殊自閒。","死生生死尔，浪歌聊破颜。"]},{"t":"戴氏鹿峰亭二首呈同游 其一","f":"五言古诗","c":["开亭面鹿峰，白鹿每经过。","忽衔落花去，还来卧青莎。","仙者不可见，孤峰但嵯峨。","疏篁映秀木，好鸟鸣相和。","飞泉洒天窗，六月凉气多。","宾朋四五辈，饮酒朱颜酡。","璆琳粲明质，芝术芬长哦。","皆为廊庙器，偶会林泉阿。","磻溪与桐庐，回旋竟如何。","却笑晋右军，弄笔怜白鹅。"]},{"t":"戴氏鹿峰亭二首呈同游 其二","f":"五言古诗","c":["未能骑黄鹤，高飞出尘寰。","且来跨白鹿，隐见苍崖间。","谁为鹿峰亭，名闻戴氏园。","仙者去已远，捲帘对青山。","秀木染深坞，鸣泉挂危栏。","春风吹绿鬓，皓月颓朱颜。","宾朋合簪履，昆季芬芝兰。","黄鹤安足骑，白鹿不须跨。","但愿有浊酒，长啸此峰下。","醉醒醒复醉，黄金任高价。"]},{"t":"陈安止迁居三首 其一","f":"五言古诗","c":["陈子勇于退，退无十椽屋。","邻家颇好事，借宅并山隩。","堂庑稍宽静，垣墙亦新筑。","春渠涨朝雨，涓涓漱寒玉。","呼童种瓜果，教仆洗松竹。","身虽在城郭，志实寓溪谷。","诵持方广经，一餐止蔬粟。","所喜远膻腥，佛事要清肃。","弗学陶长官，持杯媚秋菊。","弗学屈大夫，含悲葬鱼腹。","唯慕金粟老，不二常具足。","若许浪士游，时时跨黄犊。"]},{"t":"陈安止迁居三首 其二","f":"五言古诗","c":["陈子贫无居，东家借茅屋。","达士宁羞贫，四方所居隩。","平台荔阴下，天匠资尔筑。","青分一畦兰，绿种万竿玉。","幸遭文明运，志岂效孤竹。","又非远人音，欲以逃空谷。","翛然置藤榻，示疾肖金粟。","咒饭施诸鬼，夜半风肃肃。","嗟予在罗网，未暇亲杞菊。","忧愁无端来，刀剑搅胸腹。","渺思泛沧浪，期君濯双足。","时或临大野，泥耕看健犊。"]},{"t":"陈安止迁居三首 其三","f":"五言古诗","c":["彼美隐官隐，苍林映深屋。","俗驾远庭除，佛像镇堂隩。","兰芷稍扶疏，荆榛已锄筑。","沉思第一义，修持若砻玉。","觉城开迷云，魔军当破竹。","接人有馀地，拔我出坑谷。","斋羞复招要，甘香蒸黍粟。","永与膻荤辞，既饱精神肃。","石坐衬枯蒲，茶瓯泛新菊。","醍醐灌诸顶，饥火灭空腹。","昔闻居士饭，一钵万人足。","君若乘三车，愿为车下犊。"]},{"t":"喜雨","f":"五言古诗","c":["阴云海上来，飘风亦随至。","填空翻猛雨，溢溜迸平地。","岂惟滋稼穑，高视扫瘴疠。","群山各藏晦，万壑恣吞噬。","蚊蝇暂驱除，草木起憔悴。","榕枝碧如染，荔子红欲坠。","呼儿索杯盘，四体袭凉气。","丰年固有兆，此雨信嘉瑞。","一人尧舜圣，三公夔卨备。","阴阳兹调和，乐饮真吾事。"]},{"t":"月下怀留二君仪","f":"五言律诗","c":["默坐两股痹，幽行整头簪。","无家不成寐，有酒何处斟。","山色九秋静，月华中夜深。","遥想端居人，焚香哦妙音。"]},{"t":"寄题留二君仪田园基石亭二首 其一","f":"五言古诗","c":["磐石发天巧，新亭君所营。","席展瑶琪滑，坐久寒阴生。","远瀑曳修幔，他山列苍屏。","水田白鹭下，霜树青猿鸣。","回首同安县，残阳楼观横。","不逢车马来，时爱牛羊经。","童仆种刈毕，父老樽罍倾。","升平信难遇，欢笑聊舒情。","况攻李杜吟，字字无淫声。","春来成几章，想有基石铭。"]},{"t":"寄题留二君仪田园基石亭二首 其二","f":"五言古诗","c":["人世无百岁，尘劳枉营营。","岂如田园乐，歌啸送馀生。","况同盘石上，开亭石为屏。","卷帘春雨足，洗耳松风鸣。","孤鸟望中没，淡烟山际横。","时复命儿息，讲道或传经。","经罢哦五言，珠玑沧海倾。","嗟我无羽翼，往适幽忧情。"]},{"t":"同萧英伯登陈安止啸堂","f":"五言古诗","c":["食讫雨初霁，相将陟高台。","缥缈临诸峰，幔卷浓云开。","秀特不可掩，擎天碧崔嵬。","漳流欲赴海，澎湃西南来。","阴阴荔子木，合抱何年栽。","幽鸟转枝语，清风与春回。","佛宫四面出，绀碧疑蓬莱。","寓隐得斯地，足以摅君怀。","方庭有兰芷，近郭无虎豺。","万事不挂虑，长年效僧斋。","一为孙登啸，而与数子谐。","顾我病且老，况复时运乖。","儿归半道死，旅棺未葬埋。","破甑已弃物，乃非君子侪。","从游得无玷，泯默甘摈排。"]},{"t":"送广东漕孙知损失官归汶上","f":"五言古诗","c":["平生爱东州，土厚人不罄。","见公惜已晚，达论耸予听。","五驰使者车，中道罹陷阱。","开怀无怨尤，得失两以正。","归程万馀里，翛然一烟艇。","乡关今非遥，踊跃理三径。","进则仗忠义，退则乐温凊。","高卧固无必，求才尧舜圣。","亭亭南涧松，愈老节愈劲。","柔柔水中蒲，涵春自严静。","百年未阖棺，安之吾有命。"]},{"t":"读陶渊明传二首 其一","f":"五言古诗","c":["我爱陶渊明，超然遗世想。","一奏无弦琴，妙曲寄玄响。","翛然听以气，万籁应诸掌。","舟车就所便，丘壑信孤往。","泉涓木欣欣，酌酒助俯仰。","酣醉颓云烟，舒啸逸罗网。","斯人孰可见，梦寐期佛彷。","兀如南山松，亭亭植千丈。"]},{"t":"读陶渊明传二首 其二","f":"五言古诗","c":["陶潜真达道，何以避俗翁。","萧然守环堵，褐穿瓢屡空。","粱肉不妄受，菊杞欣所从。","一琴既无弦，妙音默相通。","造饮醉则返，赋诗乐何穷。","密网悬众鸟，孤云送冥鸿。","寂寥千载事，抚卷思冲融。","使遇宣尼圣，故应颜子同。"]},{"t":"普利寺自周上人高明轩","f":"五言古诗","c":["世人孰无累，贵彼方外人。","超然云霞趣，迥脱生死轮。","周也漳南释，开轩瞰漳滨。","山光并水影，二物长清新。","尤爱明月夕，苍林变金银。","焚香坐轩上，时或要静宾。","幸无歌吟喧，得与麋鹿驯。","尝茶煮山药，长养菩提因。","岂慕富且贵，宁忧贱与贫。","我来勿厌数，从尔陶天真。"]},{"t":"同留二君仪登高明轩","f":"五言古诗","c":["羁客厌卑湿，登轩喜高明。","红日檐下度，白云窗半生。","并吞山川秀，映带楼殿平。","舟航济吴楚，笑语落蓬瀛。","春风时一来，百鸟相和鸣。","隔墙酒可沽，千金为君倾。","既绝世上趣，雅遂林中情。","勿云暮霭合，更望孤蟾升。"]},{"t":"同陈安止登高明轩","f":"五言古诗","c":["有客学清净，喜为林下游。","兹轩高且明，驻策同其休。","目界既朗彻，心官欣自由。","弃禄慕居士，读经亲比丘。","云树樵声远，石层春水流。","鸟羽瑩可数，花光暖争浮。","已知隔人寰，日落山更幽。","适此悟无生，馀事安足求。"]},{"t":"题净惠院","f":"五言古诗","c":["方塘水未涨，荷芰新展绿。","游子惬轻衣，步与孤云逐。","初临寺外桥，已听钟声肃。","徐登山后亭，葱苍翳松竹。","诸峰却罗列，龙蛇互奔触。","红绡卷晴霞，白云落孤鹜。","了然身世忘，岂念冠带束。","平时谬持节，善地甘厚禄。","更穷泉石乐，曾未伸启沃。","何以报君恩，尧天漫凝目。"]},{"t":"题净众院赠蒙禅伯","f":"五言古诗","c":["南州三百寺，此寺最辉焕。","石开千丈渠，泉飞日华乱。","供僧无定员，连床接云汉。","经营始十载，物物悉已换。","上人固多才，不独悟禅观。","其师老黄蘖，简肃众所惮。","承音既亲切，妙顶醍醐灌。","登门已清凉，定步济彼岸。","融融接软语，群疑自消泮。","每游即忘还，微风洒尘汗。"]},{"t":"题月渊亭","f":"五言古诗","c":["仰攀明月轮，俯瞰沧海渊。","乾坤惜形胜，此池何其偏。","灵溪九龙跃，仙山一峰圆。","微红散晴绮，远碧衬瑶烟。","幽香发野秀，接语皆老禅。","缘何近城郭，了无人世諠。","邂逅摄邦守，所乐多林泉。","唯忧代者至，不得经残年。","老矣宁复来，吟哦强留连。","他时考陈迹，不灭斯亭篇。"]},{"t":"送范端仲推官","f":"五言古诗","c":["范君建阳客，读书过万卷。","下笔又神速，数预贤能荐。","省闼复擅场，声名动海县。","一投红莲幕，阻上金銮殿。","志气老不衰，苦柏冒霜霰。","当涂少知已，薄禄势所恋。","君子困下僚，佞士即华选。","顾我驽散才，摄守颇优便。","公庭可罗雀，云山复对面。","坐卧临清风，吟哦挥羽扇。","相逢始相乐，瞥去若惊电。","君行我幽独，送君聊自谚。"]},{"t":"池上晚景分得上字","f":"五言古诗","c":["秋风何处来，萧然洗炎瘴。","时要二三子，临池倒嘉酿。","逢辰既升平，览景又清旷。","寂无人世喧，颇觉神魄王。","雪鹭集沧洲，金乌没青嶂。","悠悠渔笛还，漫漫潮痕涨。","黄蜂立莲叶，赪鲤吹萍浪。","始信庄生言，观鱼乐濠上。"]},{"t":"漳南书事","f":"五言古诗","c":["元丰五年秋，七月十九日。","猛风终夜发，拔木坏庐室。","须臾海涛翻，倒注九溪溢。","湍流崩重城，万户竞仓卒。","万牛岂复辨，涯渚恍已失。","婴老相携扶，回首但悽慄。","忧心漫如焚，救疹竟无术。","忆昨摄印初，岁望颇云吉。","田畴时雨足，粳糯各秀实。","胡为兆阴怪，平地遭潏汨。","尤嗟梁栋材，中道摧折毕。","日月有常度，金行正萧瑟。","畴咨风雨师，残害皆天物。","天心本好仁，忍视久不恤。","况今大上圣，治具严且密。","骑马藏民间，教兵授神笔。","四夷还旧疆，百辟奉新律。","固宜集和气，祥瑞为时出。","缘何漳南民，憔悴抱愁疾。","终当呼长鲸，一吸见蓬荜。"]},{"t":"临漳亭观水分得大字","f":"五言古诗","c":["忧民登危亭，注视万里外。","溟濛云气浮，势与江海汇。","苍山恐低沉，况复问畎浍。","禾麻安更论，老稚念颠狈。","蛟鼍自出没，牛马失向背。","雨师恣侵凌，人理亦可罪。","殷殷非雷声，远近屋庐坏。","君臣正逢时，上下宜交泰。","驱云清白日，朗彻照幽怪。","一雨即瀰漫，孰谓乾坤大。"]},{"t":"送孙公素朝奉还台","f":"五言古诗","c":["暑雨正郁陶，流汗坐深甑。","忽闻公素来，清风先满径。","高谈别后事，琳琅发吾听。","听之复何如，五月冰雪瑩。","况逢至治朝，日月开二圣。","大臣用老成，群辟要方正。","如公亦几人，尚未擢谏诤。","浮舟每经年，山川寓幽兴。","皇皇岁华晚，曳屣漫吟咏。","行矣勿徘徊，金门待新命。"]},{"t":"题妙胜院西轩并赠权师","f":"五言古诗","c":["老木不知年，苍藤已垂地。","高枝生晚阴，低枝散凉气。","好鸟时复来，鸣声似弦吹。","道人开小轩，幽庭增广庇。","庬眉霜雪顶，休焉释尘累。","馀功又及物，丹砂和灵剂。","一粒愈沉疴，求者四方至。","应接运真悲，平等均我施。","相逢惜已晚，残光念如寄。","何当择深山，同师乐禅味。"]},{"t":"清江台致酒赠范希远龙图","f":"五言古诗","c":["行手出烟雾，致酒清江台。","水浅横沙露，林疏远山来。","白鸟一双落，青猿三叫哀。","谁展摩诘图，而把渊明杯。","妙娥始七岁，弹筝殷晴雷。","或如鸾凤吟，唤得阳春回。","主人亚父孙，卓荦王佐才。","高谈使我听，明珠欲倾怀。","爽魄超太虚，月窟无飞埃。","一饮不知醉，浩歌忘草莱。","迟明系双棹，回首安在哉。","尺水公自养，以待天门开。"]},{"t":"赠陈师道判官","f":"五言古诗","c":["自从梅老死，诗言失平淡。","我欲回众航，力弱不可缆。","栖迟二十年，时时漫孤啖。","忽逢陈夫子，两目海水湛。","为我聊一吟，粹芳超俗艳。","又如赵氏璧，毫发绝瑕玷。","愈多愈精好，璀璀摘骊颔。","借令李杜在，决敌未应敢。","低头亟趋降，吞声就诛贬。","招来君尚谦，且曰吾与点。","穷朝把樽酒，金斝红浪飐。","胡为眷幕府，半百尚壈坎。","幽兰没萧艾，明珠混野芡。","何当叩相阁，斯人愿收敛。","置之翰林中，万丈看光焰。"]},{"t":"凤凰驿","f":"五言古诗","c":["晚泊凤凰驿，得名知谓何。","凤凰不可见，篁竹空婆娑。","四傍俱石崖，一径萦云萝。","惨惨阴欲雨，淙淙涧跳波。","驿吏指英州，两舍皆平坡。","久寒无瘴疠，虚市饶鸡鹅。","我行既已远，乐少忧常多。","过江红叶舞，度岭黄鹂歌。","时序逼衰老，羽翰惊网罗。","一夕得佳处，休焉聊独哦。"]},{"t":"轮石","f":"五言古诗","c":["轮石如车轮，削立万丈壁。","湍流走其根，倒影翠雾滴。","天公不推去，此意人莫识。","虽无载挽功，免有圆转迹。","隔江欲登临，赁舟终不得。","既乏官长威，人事轻远客。","胡为秀绝姿，往往在幽僻。","童仆惊日晚，策马苦相逼。","哀哉携妻子，未暇往栖息。","沉吟复回首，舍旃欲何适。"]},{"t":"题清远峡广庆寺壁","f":"五言古诗","c":["平明下碧落，晚投清远峡。","银潢注地来，翠壁连天插。","中含五峰秀，寺载三车法。","龙归石有痕，犀跃无遗柙。","直钓谁得鱼，危矶待鸥狎。","长廊览前题，习之最为甲。","物理求其全，用材无乃狭。","浑诗亦可取，小雨才一霎。","未能臻甫白，源长流不乏。","持杯聊酌茗，清风为停箑。","超然望日下，岚翠忽颓压。","忍涕上孤舟，低头随雁鸭。"]},{"t":"次韵颖叔修撰游朱明及字","f":"五言古诗","c":["朱明洞天门，元戎要客入。","谁云蓬莱远，浮丘果相挹。","如超顿地禅，曾不假梯级。","绿篁隔葱茜，沆瀣朗呼吸。","玉山有嘉禾，凤凰乃来集。","桃李尔何知，濯濯红露泣。","应嗟尘世人，窗间白驹急。","行乐如之何，不乐嗟何及。"]},{"t":"五仙谣","f":"词","c":["番禺五仙人，骑羊各一色。","手持六秬穗，翱翱绕城壁。","翩然去乘云，诸羊化为石。","至今留空祠，异像犹可识。","曾闻经猛火，毫发无痕迹。","五仙宁复来，三说颇难测。","只忧风雨至，半夜随霹雳。","君不见羌庐刘越之洞天，万象森罗无一尺。"]},{"t":"志游呈蒋帅颖叔","f":"五言古诗","c":["焚香瞻五仙，登楼瞰沧海。","题轩名双林，却酒饭蔬菜。","还趋法性寺，烂漫发幽晦。","房公润经处，兰茝遗芳在。","老木已千年，成林播佳话。","危坛半颓缺，曾传祖师戒。","达多与药止，古像各潇洒。","归时已残阳，心渊生沆瀣。","兰亭世俗饮，尚足传异代。","佛境清净缘，浩劫永不坏。","聊志一日游，结交向方外。"]},{"t":"再和颖叔志游","f":"五言古诗","c":["君为五羊仙，我效退之拜。","默契如来禅，安用传画绘。","沧海虽云阔，万里有限际。","请从造物论，一瞬即破碎。","灵龟胡为乎，钻灼烂腹背。","生能发幽冤，神理助奇怪。","晚投古寺食，荤味不如菜。","摩挲庭下碑，百岁苍藓晦。","忽逢润经处，房公俨如在。","度人要成林，今已播禅话。","忽为杀盗淫，佛敕所告戒。","种子积无明，应须法雨洒。","幸陪莲社缘，彼此吸清瀣。","噫嗟絷轩冕，憔悴尘垢态。","一朝趋地狱，苦恼孰肯代。","瑩如摩尼珠，谁使浊水坏。","与公志斯游，浩荡形骸外。"]},{"t":"独游药洲怀颖叔修撰","f":"五言古诗","c":["驱车何所适，独往观药洲。","荒芦喧鸟雀，怪石森龙虬。","大亭插层城，玉虹跨深沟。","双门控西渚，九星聚中流。","其名何壮哉，像貌俨可求。","鋹王卷国去，故物惟此留。","沧溟霸气灭，落日孤烟浮。","空畦已无药，草蔓春柔柔。","常年一百五，载酒倾城游。","炎炎二圣作，德泽覃海陬。","大帅用文儒，静镇十五州。","诸公握鸿笔，刬藓挥戈矛。","仍要水宫月，一笑挹浮丘。","蓬莱自兹往，稳踏金鳌头。"]},{"t":"九曜石奉呈同游蒋帅颖叔吴漕翼道","f":"五言古诗","c":["番禺西城偏，九石名九曜。","危根插沧浪，古魄镇临眺。","何人试巧手，凿此混沌窍。","森森毛发散，伟伟仪形肖。","葱苍翠雾湿，玲珑秋月照。","痕添海潮上，声酸朔风叫。","龙归忧利剑，鳌泣怖长钓。","曾非借霹雳，安得离岩峤。","菱溪与太湖，所得信未妙。","谁将置濠隍，我愿植廊庙。","坚贞以类举，邪僻令遁跳。","濡毫勒阴崖，卑语君莫诮。"]},{"t":"和颖叔游浮丘观","f":"五言古诗","c":["潭潭洞天门，孰出朱明右。","突疑云翼张，竦见冰骨瘦。","飞仙时往来，别有通海窦。","此事仅传闻，世人岂能觏。","攲檐榛棘合，坏壁青红旧。","汲泉炼丹处，颓废无完甃。","不逢博物人，妙迹谁复究。","黄冠禀使者，乘时力营构。","飞阁凌沧波，诛林逐群狖。","松萝翠欲滴，兰茝芬可嗅。","秋蟾助馀魄，蓬岛分小岫。","披披宿霭散，泠泠诸籁奏。","超然俗虑息，挥手出宇宙。","况逢老集仙，气夺天下秀。","落笔诚千言，霹雳震白昼。","于兹惜分携，作恶须掺袖。"]},{"t":"颖叔招饮吴圃","f":"五言古诗","c":["五鼓开画戟，平明出重闉。","小桥分野径，吴圃会众宾。","番禺二月尾，落花已无春。","唯有蔷薇水，衣襟四时薰。","短垣乃浮丘，楼观何斩新。","我公发幽晦，输金走车轮。","蓬莱飞一岛，云外拖晴绅。","此景在眉睫，图绘未必匀。","从来不弹弋，傍砌鸟雀驯。","寄语北海若，停风护松筠。","负才诗傲敌，纵酒吞湖漘。","酩酊安足辞，不饮终成尘。","逍遥一日事，浮脆百年身。","何须跨黄鹤，追彼瑶池人。","但当听公歌，卖交斥张陈。","达道齐生死，笔端真有神。","挥洒十八韵，一一无价珍。","老彼杜工部，玄哉扬子云。"]},{"t":"鹄奔亭呈帅漕二公","f":"五言古诗","c":["新江自南来，西与端江汇。","寒光入灵羊，一碧浸罗带。","屹然鹄奔亭，遗音溢千载。","羽仪莫可见，窈窕想姝态。","遭戕瘗同坎，襦布久不坏。","诉冤如生平，隐显一何怪。","雠人阖户戮，化质抟风快。","且将忧患辞，浩荡烟霄外。","舄飞并剑跃，类与神灵会。","物变固难穷，抚事增感慨。","周侯昔行部，美绩此尤最。","江生引为言，建平平捐罪。","宋兴跨唐虞，乾坤正交泰。","皇华命俊哲，枉横无纤芥。","琳琅斯亭篇，證古欲陈戒。","杀人贵灭口，覆族竟自败。","奸谀诛既死，潜德发幽晦。","坚珉可磨镌，荣光庶长在。"]},{"t":"端州逢故人刘炜光道致酒鹄奔亭作","f":"五言古诗","c":["贵池昔分袂，端江复倾盖。","屈指十六秋，华发惊老大。","云霄邈功名，荆榛森患害。","众人皆欲戮，出门即有碍。","咄哉不复道，致酒强高会。","苍梧帝魂寂，鹄化遗亭在。","翠葆撄玉簪，金鳞跃罗带。","风澄岚霭散，棹击天影碎。","往古悉已空，来今竟何待。","劳形百年间，投足万里内。","秋水正瀰漫，醉胆逐澎湃。","一丝携六鳌，猛掷沧溟外。"]},{"t":"将归三首 其一","f":"五言古诗","c":["春田岂不美，春园亦可佳。","田水流决决，园禽语喈喈。","荷笠复携锄，动作颇自谐。","邻叟三五辈，击壤欢无涯。","禄仕四十年，志运良已乖。","许国既无补，陷阱几沈埋。","皇恩湛昭洗，印绶蒙优差。","内循齿发衰，愧彼英俊偕。","休焉保其终，飞章乞残骸。","将归乐复乐，清风扫孤怀。"]},{"t":"将归三首 其二","f":"五言古诗","c":["结庐谢山下，门荒萝径深。","寂无车马迹，而有猿鸟音。","高峰落日尽，远壑归云沉。","死生一吾趣，长啸亡头簪。","勇往复此乐，俛仰安可任。"]},{"t":"将归三首 其三","f":"五言古诗","c":["垂老度庾岭，西江守端州。","逾年忝禄食，归思忽惊秋。","结庐丹湖边，种朮果屡收。","挂冠已不早，玄花随两眸。","休休保残龄，击壤歌皇猷。","有儿集吏选，馀事复何求。","回首天地恩，瞑目终难酬。"]},{"t":"赠上蓝晋禅师","f":"五言古诗","c":["泐潭月公晦，其禅妙诸方。","传之晋伯明，独步入豫章。","一登上蓝座，日月迥辉光。","问法瞻丈室，方广不可量。","人人得甘露，灌顶心清凉。","又通世俗书，落笔皆文章。","众鸟难悉名，卓然唯凤凰。","羽仪下云霄，五色在山冈。","先帝昔临御，京城开宝坊。","明诏求法才，众老争低昂。","惟师不妄念，安之如太行。","乃知北远师，驾幸不下床。","所传信匪讹，千载两相望。","篁竹架清风，乔松裛寒霜。","回心剃须发，永愿陪翱翔。"]},{"t":"望庐山怀陶渊明","f":"五言古诗","c":["羌庐初在望，复忆柴桑翁。","醉来卧磐石，闷默天地通。","不入惠远社，自弹无弦桐。","悠悠出谷云，漠漠栖林风。","傍岩片月白，落磴寒泉洪。","此意非眺听，遥知与君同。"]},{"t":"追和韦应物庐山西涧瀑布下作","f":"五言古诗","c":["徘徊西涧下，听泉濯烦襟。","烦襟遂萧爽，妙音非世音。","不知岐路绝，贪玩烟萝深。","斧斤未尝入，高材自成林。","鹤鸣岂有怨，云去本无心。","寥寥陵涧寂，古意难追寻。"]},{"t":"宿栖贤寺","f":"五言古诗","c":["遥怜李太白，吟望瀑布水。","不知三峡流，翠洒虚烟里。","雄声雷雨骤，远响松风靡。","谁留千丈虹，长在云根倚。","遂令车马来，朗瞻楼殿启。","明明银色界，浩浩蟾波洗。","居中梵天众，闻思悟玄理。","长老乃摩诘，取供在弹指。","普薰毛孔香，真宝超凡鄙。","病夫寄一榻，清泠濯心耳。","飘然睡乡去，策杖中夜起。","不能跨鲸鱼，挥笔信非美。"]},{"t":"宿归宗寺","f":"五言古诗","c":["旷怀王逸少，宅地如翔鸾。","池水至今黑，云是墨未乾。","施作金仙宫，楼殿排羽翰。","银榜留飞乌，玉蜃吐惊湍。","耶舍宝塔近，笔插青云端。","贝叶五千书，两藏龙鳞蟠。","钟磬递虚籁，松杉扶岁寒。","护持不变灭，炉烟昼漫漫。","暂游寄僧榻，翛然心界宽。","愧无惊绝草，付与苍崖刊。"]},{"t":"新昌吟寄颖叔待制","f":"五言古诗","c":["元祐丙寅冬，新昌有狂寇。","名探其姓岑，厥初善巫咒。","南民欣尚鬼，来者争辐辏。","经年惑群众，诡术遂潜构。","摧城止三阚，作蜂唯撒豆。","竹竿变鎗旗，锐兵莫吾斗。","此事古未闻，造意无乃陋。","蚩蚩彼何知，丁壮拥前后。","长驱向城郭，尘土翳白昼。","刺史亟闭户，神理默垂祐。","城头无百兵，坐待五羊救。","贼中众所见，戢戢罗甲胄。","须臾薄寒阴，冻立多僵仆。","平明若鸟散，贼本未遑究。","权帅计仓卒，遣将速诛蹂。","贪功恣杀戮，原野民血溜。","婴儿与妇女，屠割仅遗脰。","传报及南昌，新帅若烟走。","入境亟止杀，渠恶用机购。","逾旬果获探，腰斩馀悉宥。","朝廷方好仁，帅略寔能副。","台章请褒赏，诏语优以懋。","抚绥聊借才，侍从尔来复。","身居江湖上，名近日月右。","麟儿随飞龙，阴骘资贵富。","彼美南山松，落落千丈秀。","终为廊庙器，未许连城售。","吴毛持漕节，文彩烂锦绣。","发为新昌行，洪钟待谁扣。","我将磨苍珉，为公悉镵镂。"]},{"t":"送许栖墨道士","f":"五言古诗","c":["结庐守亲冢，淡食毕丧制。","焚香诵宝经，倾悲拔冥滞。","神明扶孝思，肌发保阳气。","支离仅不死，邻里为歔欷。","倏然叩予门，殷勤谢铭志。","袖携一幅图，离坎备形势。","明堂正丘穴，松槚列新翠。","身虽离冢旁，披图即流涕。","拿舟遽言别，讳曰仲春至。","酌水采嘉蔬，藉草具严祭。","又言广栽植，薄取岁时利。","事死如事生，终焉达斯志。","儒者似君稀，况复褐冠类。","谁为孝子传，吾诗信无伪。"]},{"t":"送胡推官赴无锡丞","f":"五言古诗","c":["爱山不离山，君来访山间。","山间只欠水，听君语潺潺。","滋我山色秀，洗我尘心烦。","如何遽言别，鸾骖欲翩翻。","试才得佳邑，割鸡鸣刀镮。","双亲尚未老，伯氏趋朝班。","蓝田玉一双，浮出濡须湾。","天作王者瑞，宁独名乡关。","自怜困已甚，风流邈难攀。","新诗倘可寄，秋雁无空还。"]},{"t":"送胡与几被召赴阙","f":"五言古诗","c":["嗟我老已疲，挂冠归旧庐。","素乏二顷田，无可把犁锄。","穷年小山下，独伴千卷书。","作止随古人，襟怀稍欣如。","又无樽中酒，能延故人车。","感君数相过，气豁眉宇疏。","天马出月窟，回薄万里馀。","其才无不宜，禄仕犹拘拘。","忽闻明廷诏，一节驰轻舆。","往必陟台省，公言壮皇图。","潜心救世弊，肯意为身谟。","法密吏愈偷，食众财益虚。","末大本渐弱，岂在专防胡。","指瑕一二人，此事尤可吁。","细碎何足论，纲举网不踰。","譬彼脉已病，其身尚膏腴。","要当速内究，珍丸应时须。","良医望数公，润泽回焦枯。","愿如范文正，挺持真丈夫。","老死见太平，委弃甘路衢。"]},{"t":"送马东玉朝散还朝","f":"五言古诗","c":["秋空若明镜，云物瑩可数。","临高送远发，况复瞰牛渚。","崔嵬水帝宫，半出燃犀浦。","桥基插波澜，王气逐龙虎。","归艎岂能留，两浆几欲舞。","重光瞻舜日，群材入天罟。","聃聃马东玉，松柏耐寒暑。","五载佐吾邦，大匠善规矩。","仁民而爱物，巨细各有补。","宴閒集宾朋，风流照樽俎。","能诗又敏速，往往造险语。","交章久荐达，名声动寰宇。","胸中蟠虹蜺，行矣须一吐。","伊予百无堪，投老尚好古。","垂竿鱼未食，茹檗口忘苦。","唯君最相知，称谓等鲍庾。","君归我何适，形影守溪浒。","时寄一行书，焦枯望霖雨。"]},{"t":"谢泾川宋宰惠近诗","f":"词","c":["不到泾上邑，倏忽二十载。","环山敞楼阁，金碧想未改。","长溪拖翠玉，洗月发光彩。","秋声咽松杉，夜气馥兰茝。","白鸟自成群，黄猿行作队。","仙人控鲤去，岩下遗迹在。","犹疑深云中，弹琴尚相待。","唐儒工翰墨，石壁露璀璨。","意有神明怜，尘藓不得浼。","地胜来俊哲，宋子今出宰。","公馀缀吟笔，烂漫排珠琲。","又如崆峒兵，百万森甲铠。","寄我数十篇，翛然起沉痗。","胸中强搜抉，旧学久荒馁。","欲追天马踪，蹇蹶竟难逮。","抚卷怀昔游，魂魄飞?叆。","何当裂云笺，看君吐江海。"]},{"t":"寄杭州天竺辨才大师","f":"五言古诗","c":["我闻辨才师，解空称第一。","病子得摩顶，其疾顿若失。","救物运真悲，了心非幻术。","声名动寰宇，退身性愈密。","峨峨龙井峰，篁竹不透日。","终朝无来宾，筇枝自横膝。","此道何寥寥，差肩佛摩诘。","无生无不生，一以贯禅律。","安得两羽翰，归飞参丈室。","稽首慕高风，天地相终毕。"]},{"t":"送外甥法真一师","f":"五言古诗","c":["仕禄不及养，勇往学金仙。","弃家如脱屣，坏衣披稻田。","见汝若见母，令我涕泗涟。","我方龀龆时，巨狱遭摧颠。","汝母挈我往，西江赴临川。","爱育比其儿，衣食无颇偏。","追随二三载，思亲我言还。","是时汝未产，顾今三十年。","汝壮我已老，死者归重泉。","悠悠记昨梦，幻妄真可怜。","汝能逃世累，趣尚固已贤。","京华勿久栖，还当择深渊。","返穷生死本，勿为言句缠。","拭我衣上泪，赠汝金石篇。"]},{"t":"送甥沈济秀才下第南归","f":"五言古诗","c":["炎风吹黄尘，去兴不可止。","丈夫固有命，得失致悲喜。","何当永相将，锡山酌泉水。"]},{"t":"送胡子企大夫还台","f":"五言古诗","c":["联镳出梅山，倏然二十载。","君尝佐天府，我遂泛云海。","音书鱼雁绝，梦寐想风采。","营车忽来过，笑语珠璀璀。","故交悉相忘，而君独不改。","天王尧舜资，化柄付良宰。","网罗收鸿鹄，台阁茂兰茝。","君归必殊显，发策救民痗。","形容入凌烟，丹青永无浼。","使我观太平，白首甘冻馁。"]},{"t":"投宿繁昌徐氏水阁","f":"五言古诗","c":["东池种莲子，西池养肥鱼。","盈缸酿美酒，满盘具新蔬。","客来径一醉，疑是桃源图。","此事未足议，弟兄皆业儒。","大弟已登科，高名动乡闾。","季弟复连荐，豹变应时须。","长兄恬自养，云卧随卷舒。","物至我则应，隐德良有馀。","客有醉吟叟，六月骑蹇驴。","避暑寻名山，遂登君子居。","饮弄池上月，一宿能清虚。","相看不相厌，欲去且踟蹰。"]},{"t":"和姜伯辉见赠醉吟画诗","f":"五言古诗","c":["苍崖一万丈，中写白玉泉。","飞鸟度不得，而我长攀缘。","洗尽心地垢，吟成元化篇。","更复有何物，一樽当我前。","忽逢姜伯辉，爽量涵水渊。","开谈了无迹，所得全于天。","便欲脱青衫，泛我江东船。","结交要终始，相忘复颓然。","径呼妙手画，秋江霜景全。","冰轮正卓午，照影无颇偏。","谁能骑蹇驴，世路空流连。","咄哉可以往，挥手从飞仙。"]},{"t":"观唐植夫所藏古墨","f":"五言古诗","c":["黑龙蟠黑云，久蛰黄金阙。","缘何落人间，数饼若古月。","虾蟆不敢蚀，利刀岂能截。","温润比方玉，芬香麝脐裂。","乃知廷圭名，桓桓久不灭。","植夫名世俊，所蓄号奇绝。","护以紫锦囊，箧之复扃鐍。","渺思五季乱，江南颇偷逸。","三主皆能书，拨镫耸瘦骨。","一朝归大明，流散馀故物。","金华座右铭，清凉自题佛。","二宝藏予家，时时一披拂。","及观植夫墨，清风愈飘忽。","异国想尘劳，精灵岂沉没。","聊为识古篇，分手各萧瑟。"]},{"t":"酬富仲容朝散见赠因以送之","f":"五言古诗","c":["牧之吟齐天，太白咏秋浦。","至今三百年，光焰不埋土。","我朝文愈盛，往往出前古。","仲容生相门，璨然凤凰羽。","作镇薄书閒，盈编金玉吐。","牧之何足论，白也真尔汝。","一朝解符归，暂泊采江浒。","肩舆过蓬荜，高谈辰及午。","洗我尘坌听，不觉欢欲舞。","又如熟黄粱，连餐释饥苦。","昔闻郑国公，片言戢狂虏。","庙食配神宗，昭昭仲山甫。","今逢族弟贤，家法中规矩。","郎省宁淹回，往自结明主。","不惟唐萧家，继踵登相府。","请驱千里云，时作三日雨。"]},{"t":"宿钟山赠泉禅师","f":"五言古诗","c":["夜半松柏响，绕岩鸾凤音。","披衣送遐盼，明月方庭深。","楼殿遍瑶层，宝塔楼中岑。","定分付赤刀，世故仍痴淫。","六朝遗破冢，四圣崇幽林。","香厨饭玉粒，千岁闻于今。","况逢大道师，妙传诸佛心。","其徒五百人，坐忘静沈沈。","宝光泳琉璃，永无尘垢侵。","何以明归仰，顿首兴微吟。"]},{"t":"送倪敦复往池州决狱","f":"五言古诗","c":["忽领外台檄，离家不辞艰。","破雪陟远道，侵星出重关。","提刀聊四顾，决狱谈笑间。","旦经五峰寺，遂发九华山。","朗饮云泉秀，妙依松石闲。","琳琅如得句，先寄南风还。"]},{"t":"送敦复至观音寺再用前韵祝别","f":"五言古诗","c":["太道既如砥，安舆宁险艰。","通沟水决决，出林鸟关关。","紫诏下天外，黄气生眉间。","归当趋玉陛，岂容眷名山。","接物齐彼分，存诚肃吾闲。","我心如路草，愿君与春还。"]},{"t":"陶然轩呈孔掾","f":"五言古诗","c":["我醉不在酒，心常醉于天。","出处无固必，四时任陶然。","世网谁拘拘，冥鸿自翩翩。","隐凡乐吾乐，陶然名此轩。","采掇富菊杞，芬香籍兰荃。","啼鸟助春喜，相呼语涓涓。","好风集清微，时写朱丝弦。","秋月瑩池上，腊雪堆檐前。","客来亦把酒，客去醉还眠。","为君发短调，意将千载传。"]},{"t":"安中尚书见招同诸公登雨华台","f":"五言古诗","c":["城南五里近，驱车稍停休。","层台临古刹，欣陪清净游。","凭高送远目，考古思名流。","更读琳琅篇，叙事何其周。","尸黎与法云，接迹居岩幽。","趣将金仙谐，行匪邪径由。","至今手植松，千丈腾龙虬。","悟发特异众，妙龄已依刘。","天华无根蒂，应讲来飞浮。","帝释昔举手，此理谁可侔。","迩来表前踪，新亭压鳌头。","空渚栖古月，大江浴清秋。","旷怀出十地，壮气横九州。","三山连天门，水府卧金牛。","故国罗绮灭，深宫榛莽留。","兴亡千岁间，愁绪如缲抽。","惟馀北岭云，无心自悠悠。","高鸿正飞冥，网罗安得收。","公等真丈夫，问学皆渊丘。","不应持使旄，归合登瀛洲。","桓桓鼎鼐司，落落金马俦。","君臣若尧舜，明良互赓酬。","胡为慕瞿聃，玄微解而优。","愿舒三日霖，慰此旱岁求。","乾坤涵润泽，使我醉两眸。","咄嗟勿重陈，玉树后庭讴。"]},{"t":"送李嘉甫朝散还台","f":"五言古诗","c":["春风连作恶，吹雪深尺五。","元宵无灯火，闭关与谁语。","忽闻营从过，倾盖挹眉宇。","相亲如故人，坐久加循抚。","蓬茅只数间，馀无一丘土。","半俸足以饱，未尝诣州府。","白云寓远目，清溪照灵腑。","趋閒已忘忧，浩歌唯汲古。","明公志方壮，富贵何可取。","高才孰能当，如罴亦如虎。","致君为唐虞，泽民作霖雨。","功名垂乾坤，儿孙列簪组。","于予一何辽，而能强相与。","聊书送行章，欲以明出处。"]},{"t":"前春雪","f":"五言古诗","c":["玄冥夺春令，连旬雪塞屋。","嗷嗷何物声，云是饥民哭。","来请义仓米，奈何久空腹。","寒威如戈矛，命尽须臾速。","忆昨去年水，云涛卷平陆。","高村既无麦，低田又无谷。","民间已乏食，租税仍未足。","县令欲逃责，催科峻鞭朴。","嗟哉吾邦民，何以保骨肉。","昂头诉苍苍，和气待春育。","春工本好生，此雪无乃酷。","谁家敞园馆，草树变琼玉。","美人学回风，欢笑列灯烛。","不如万户寒，唯忧五更促。","世无采诗官，悲歌寄鸿鹄。"]},{"t":"后春雪","f":"五言古诗","c":["前雪深尺五，后雪深五尺。","动地北风恶，连天冻云塞。","通逵绝行人，万物同一色。","烛龙爪生冰，阳乌觜插翼。","牛羊何足论，虎豹饿无食。","此雪昔未有，父老均叹息。","况当长养时，玄冥翻怒赫。","我欲请雷车，夜半轰霹雳。","斗杓斡春阳，和气随甲拆。","溶为大田水，青发龙头麦。","南民少苏醒，白骨免堆积。","朝廷方体仁，乾坤应合德。","有酒不敢饮，独乐神所责。","悲歌闭空屋，写慰同心客。"]},{"t":"送黄吉老察院","f":"五言古诗","c":["积学久未遇，忠言今可施。","请君略细故，吐出胸中奇。","悉救当世弊，自结明主知。","不唯振宪纲，进当司鼎彝。","用广财已乏，官冗人愈卑。","政宽法不举，将偄边无威。","家家侈声乐，淳源变浇漓。","土木绚金碧，佛仙竞新祠。","此乃腹心疾，岂止为疮痍。","言者曾未及，虽言多恚私。","苟非大奸邪，恶足求瑕玼。","举朝无完人，何以禆明时。","尝读喜似篇，左右皆宜之。","乃知荆山璧，天地终不遗。","去垩无变容，诚明达神祗。","我方卧岩谷，所友鹿与麋。","感君营从过，枯木春风吹。","又如得黄粱，慰我久苦饥。","承诏不敢留，欢言遽暌违。","殷勤何以报，报君以芜辞。"]},{"t":"和敦复留题池州弄水序","f":"五言古诗","c":["我寄江南隐，数为弄水游。","读君弄水篇，感慨攀巢由。","赤脚踏云雨，投竿玩汀洲。","鸥鸟不见猜，飞舞相应酬。","谁倾百斛珠，跳踯无复收。","一发海客秘，烂副贫家求。","李杜缩光焰，王谢惭风流。","开卷起予兴，飘欲乘桴浮。","如观秋浦图，晚景入两眸。","爱之不能舍，饥鱼适吞钩。","尝置几案间，出没窥岩幽。","一别几何时，岁月已十周。","迹滞若匣剑，绣涩不可抽。","何当随君车，吟哦与君侔。"]},{"t":"谢胡丞寄锡泉十瓶","f":"五言古诗","c":["怜我酷嗜茗，远分名山泉。","兹山固多锡，泉味甘尤偏。","幸遇佳客便，十缸附轻船。","开缸漱清泠，不待同茗煎。","想君民事休，时时造泉边。","入碾龙凤碎，浮瓯乳花圆。","一啜未能止，七杯誇玉川。","两腋生清风，飞逐蓬莱仙。","江心与谷帘，较之孰为妍。","欲报吾子惠，仍思陆生贤。"]},{"t":"谢魏户曹惠酒","f":"五言古诗","c":["官醪不许买，兵酝未尝得。","愁杀避俗翁，甘为独醒客。","缘何魏夫子，心仁生悯恻。","双壶辄分送，涸鳞被甘泽。","铛杓再施设，并欲醉君德。","百川供长虹，叱吒天地窄。","尽从秋水来，大笑问河伯。","胡为辨牛马，滟滟浮月魄。"]},{"t":"川涨","f":"五言古诗","c":["朱夏久不雨，川源条然涨。","三潮渺相连，狂风蹴高浪。","蛟龙递出没，鱼鳖随浩荡。","群山悄低徊，阡陌失背向。","嗟嗟圩中田，一埂安可障。","去年已大潦，十户九凋丧。","幸赖官廪实，嚣嚣命所仰。","官廪今已空，农事未敢望。","理水竟无术，祈祷俟灵贶。","退寸复进尺，潮势颇难量。","彼苍罪斯民，杀戮不以杖。","令人思禹功，巍巍百王上。"]},{"t":"答魏掾招饮","f":"五言古诗","c":["我欲招魏子，小山尝白醪。","月华虽未满，已觉秋风高。","何物佑樽酌，肥鲈并蟹螯。","一饮洗百忧，轩冕稍可逃。","此语未及发，辱君先见要。","乃知志趣同，盍簪皆俊僚。","亦应唤舞娥，红云欲飞飘。","不然避谤伤，谈话倾渔樵。","期归一酩酊，世事如芭蕉。"]},{"t":"酬彭法曹留题小山用次来韵","f":"五言古诗","c":["读君小山诗，语势欲飞舞。","乃知甘与贾，年少心则古。","又如东方生，用之必为虎。","予方坐空谷，屏息避烦暑。","开缄揖清风，不觉生毛羽。","携之出人间，瑶池赠王母。"]},{"t":"送黄彦发还台","f":"五言古诗","c":["予方寓小山，感君忽相过。","风标夺瑩玉，气语排悬河。","君初佩金印，治蛮真有科。","彼侮我即斩，威行济之和。","使知朝廷尊，帖帖无愆讹。","圣主方求才，四海张网罗。","麒麟并凤凰，所获宁为多。","如君必见取，为君吟菁莪。"]},{"t":"酬陈掾留题小山二首用次来韵 其一","f":"五言古诗","c":["我爱小山石，翩翩鸾凤姿。","胡为不飞去，似与幽人期。","志泽未及物，收身聊自嬉。","不教三径荒，宁歌吾意词。","旧交安在哉，岁晏逢子知。","殷勤结惠好，琅玕分一枝。"]},{"t":"酬陈掾留题小山二首用次来韵 其二","f":"五言古诗","c":["兹山何亭亭，郁有高人姿。","朝容白云过，夜与明月期。","幽兰翠碧秀，好鸟鸣声嬉。","更逢佳客来，惠好留美词。","遂令一丘乐，能垂千载知。","殷勤谢陈子，蒹葭倚琼枝。"]},{"t":"和陈掾效陶斋","f":"五言古诗","c":["君欲效陶潜，超然异今趣。","开斋即吾庐，欣欣同所慕。","潜鱼不群游，栖鸟不返顾。","无意亦无我，何思复何虑。","遂趋羲皇上，日息自休裕。","百年能几何，不知岁云暮。","终当随白云，悠悠此山去。"]},{"t":"喜钟山泉禅师见过","f":"五言律诗","c":["闻师飞锡来，七日远荤饮。","欣谐清净谈，中夜未能寝。","师提宝公刀，为我裁古锦。","言归不须忙，溪上冰雪凛。"]},{"t":"送魏掾赴调","f":"五言古诗","c":["龆龀已承禄，资赋况超迈。","三年瑩无玼，一日忻有代。","芳洲清风微，夕浦寒烟䨴。","翩翩莫能留，逡巡远山外。","浮生离合际，志士怀耿介。","渺思岁月往，俯视天壤隘。","人惊甘罗少，帝忆贾生对。","竟言若为期，充实光辉大。"]},{"t":"送喻明仲朝请还台","f":"五言古诗","c":["出驰使者星，岁月一何久。","巨航始北归，华发已盈首。","读书过五车，满腹藏琼玖。","行行赴金阙，朝帝见太母。","乾坤运元气，斟酌须北斗。","愿如范文正，上疏发纩黈。","明明纳忠谏，圣作古无有。","道行且寄书，慰我穷老叟。"]},{"t":"送倪敦复朝奉还台","f":"五言古诗","c":["有力乃致远，中道力不任。","言归闭空屋，敢复求知音。","君来监郡务，猥巷一见临。","称褒借阳春，片砾成寸金。","觞酌每追随，啸咏舒悰襟。","不觉三岁过，启棹离江南。","君怀有玉宝，未尝献于今。","于今不往献，千岁惜湮沈。","流景良可悲，须雪来侵侵。","前途渐就窄，后会安可寻。","屋梁见落月，殷忧存我心。","犹期泽万物，霈然作商霖。"]},{"t":"邀敦复小酌为别","f":"五言古诗","c":["三年同赏梅，梅花烂晴雪。","一日言北归，梅黄雨初歇。","谁将金弹丸，缀在绿枝上。","结实胜开花，邀君更同赏。","食梅齿牙软，衔杯奈离忧。","过江桃李熟，回首忆梅不。"]},{"t":"送杨缜供备还京","f":"五言古诗","c":["伯玉弘农后，轩轩真丈夫。","首虽峨武弁，满腹藏诗书。","三年监郡兵，一日云解符。","考之闾井言，公廉卒如初。","未尝害一物，纵舍乃有馀。","我方卧空屋，袒跣与世疏。","感君数相过，晨坐定及晡。","新诗并美酒，问遗无时无。","老境重可惜，远别复何如。","羡君五福全，客官奚拘拘。","子孙俱禄仕，京城富园闾。","精神趁强健，优游早悬车。","祝君可以归，为君吟归欤。"]},{"t":"听惠守钱承议谈罗浮山因以赠之","f":"五言古诗","c":["久忆观沧海，喜君语罗浮。","浮从会稽来，与罗相献酬。","谁欲通两山，铁桥跨山头。","笙箫响瑶台，佛仙栖石楼。","灵光烛商舶，七星被林幽。","飞泉难悉名，异草香气柔。","危峰聚白鹿，深坞眠青牛。","葛洪安期生，遗踪尚绸缪。","攀巅瞰海水，湛碧才一瓯。","不见波涛翻，飓风驾龙虬。","又云朱明天，飘然落遐陬。","方广吞五岳，盘纡临十洲。","不得预封禅，自起烟云羞。","此理固莫测，胜境输君游。","君语洗我耳，我诗瑩君眸。","罗浮杳何许，为我商声讴。"]},{"t":"送钱节七承议还台","f":"五言古诗","c":["平昔未识面，已景才业殊。","及来公诩家，把酒情忻如。","分携八换岁，益闻峻名誉。","我方姑熟隐，君解惠国符。","鹢舟始云泊，驾言过茅庐。","倾谈洗尘听，积忧令我舒。","凤窼无凡毛，龙窟多美珠。","朝家正清明，往矣涉亨衢。","泽民冀姚宋，致主优唐虞。","史笔采循吏，非君复谁书。"]},{"t":"自释二首 其一","f":"五言古诗","c":["去日不可追，来日已无多。","衰颓复自念，迁谢当奈何。","贤达并贱愚，百岁同消磨。","不如泳觞酌，徘徊眄庭柯。","流翠自成幄，好风时经过。","憎爱理兼忘，虚淡神所和。","运尽即随尽，葬骨南山坡。"]},{"t":"自释二首 其二","f":"五言古诗","c":["遭时如尧舜，击壤欢且歌。","归田尚叨禄，天宠固已多。","敢复邀长年，寓景随流波。","有酒即觞酌，风日眷清和。","俯悲秦晋士，含饥避干戈。"]},{"t":"怀友二首 其一","f":"五言古诗","c":["夕阳在窗户，凉气何处来。","微风泛庭柯，萧萧历空阶。","抱琴一写之，冰霜溅孤怀。","但惜对樽酌，而无良友偕。","聊将幽独思，滔滔寄长淮。"]},{"t":"怀友二首 其二","f":"五言古诗","c":["晚坐庭树下，凉飔经我怀。","亦有樽中物，佳人殊未来。","佳人隔重城，谁复为之侪。","瞻云云行天，步月月满阶。","想闻诵声作，崩腾泻江淮。"]},{"t":"七月八日要阎公达承议晚酌二首 其一","f":"五言古诗","c":["河桥散灵鹊，曜景逾佳期。","池华延舒月，尚可倾一卮。","欲以要良宾，秋事言凄其。","岁往岂再得，绿发含霜滋。","寓意不在饮，营驾君莫辞。"]},{"t":"七月八日要阎公达承议晚酌二首 其二","f":"五言古诗","c":["营驾君莫辞，寓饮不在酒。","得酒亦可喜，话情庶延久。","鹭白不翳尘，山光含美璞。","霞绮映池葩，条蝉嘶露渥。","时平无横愁，身退兹馀裕。","弹琴来薰风，高轩良可伫。"]},{"t":"严氏西斋","f":"五言古诗","c":["立屋聚群经，执经授诸儿。","趋善务深畜，言行蹈前规。","譬欲种嘉禾，春膏力锄犁。","一朝秀而实，刈熟当如坻。","遂为道德饱，用济斯民饥。","庭木岂不美，凉阴奉遨嬉。","池水岂不深，濯热临清漪。","作止既可乐，左右皆宜之。","瑶琴谁为弹，倚声奏吾诗。"]},{"t":"志士吟二首 其一","f":"五言古诗","c":["群材欣向荣，志士寂无托。","独鸟千里飞，天末孤云泊。","越女殊西子，秦声异别鹤。","守贞不辞贫，怡怡内常乐。","高歌戛金玉，其声震寥廓。"]},{"t":"志士吟二首 其二","f":"五言古诗","c":["岁华忽已晚，志士将奈何。","摧车眷前修，停泽无馀波。","知命守穷贱，脱屣南山阿。","出从麋鹿游，坐与猿鸟歌。","采菊复采薇，聊以养天和。"]},{"t":"闻砧","f":"五言古诗","c":["天潢转斜白，庭菊汎团露。","纨扇辞玉纤，云幄含幽素。","湿萤递疏牖，寒螀鸣外户。","南邻发砧响，凉夕敢虚度。","不作舞衣裳，为君理缯絮。","边碛多苦寒，先秋寄征戍。"]},{"t":"秋扇","f":"五言古诗","c":["轻素裁团扇，投君掌握中。","为君却烦暑，动摇挹凉风。","一朝霜飙至，罗帏衾被重。","辞君且屏迹，弃置随断蓬。","物理古如此，用舍安可穷。","愿君千万寿，执热还相逢。"]},{"t":"庭竹","f":"五言古诗","c":["眷此庭中竹，罗生横十寻。","疏疏挺高节，密密敷清阴。","好风每相过，流尘讵能侵。","其下无蔓草，其傍远脩林。","结根自得所，非高亦非深。","谁复采笙箫，玉宇思和音。"]},{"t":"赏莲","f":"五言古诗","c":["濯濯水中华，香艳胜蘋藻。","英英泥中根，絜素常自保。","房实又堪食，无一不为好。","乃知金仙经，譬喻肆论讨。","游宴集宾僚，赏咏固宜早。","一朝霜飙至，茎叶变枯槁。","抑亦如佳人，妍媚忽衰老。","顾眄岂复怜，弃置不足道。","幽怀向君开，芳樽为倾倒。","木末谁能搴，愁烟起孤岛。"]},{"t":"将至金陵谒曾子开侍郎","f":"五言古诗","c":["秋空久不雨，漠漠风卷沙。","胡为起高兴，昨夜辞山家。","明投金陵郭，府观凌紫霞。","公解豫章榻，我停银汉槎。","一倾别后言，电雹鸣交加。","借公口中春，发我枝上花。","又如出地雷，空山走龙蛇。","公能结明主，我亦思无邪。","但惊歧路别，进退各有涯。","浮生能几时，鬓发忽已华。","会合岂易得，兵厨酒仍佳。","慎勿学谢安，扪涕空戚嗟。"]},{"t":"双泉轩赠太平守梁正叔","f":"五言古诗","c":["开池得双泉，因泉构华屋。","池中种菱荇，池上列花竹。","与春蘸新红，遇风摇净绿。","轻鸥自飞舞，纤鳞随出缩。","操舟往江海，端忧龙蜃触。","卷衣入山林，而防虎狼欲。","岂如一凭栏，俯仰快心目。","朝吟吟有馀，暮醉醉不足。","双泉长涓涓，比公享天禄。","公归民怀公，听我双泉曲。"]},{"t":"徐子美杨君倚李元翰小酌言旧","f":"五言古诗","c":["南方多苦热，北地尤苦寒。","徐子掾招宜，七载滨夷蛮。","杨李仕并代，毳裘霜雪残。","一朝相续归，相看涕汍澜。","扪涕唤家僮，草草罗杯盘。","念昔共庠序，垂髫竞痴顽。","及今过六十，各各嗟衰颜。","光阴信如驰，生死无百年。","妻儿半凋丧，少喜多忧患。","吾方慕陶潜，行歌眷南山。","山气日夕佳，吾庐未尝关。","猿鸟相与居，丝桐时一弹。","三子方急禄，遑遑未能閒。","努力佐州县，须防官长难。","暂当陪我醉，馀事不足言。"]},{"t":"寄题九江陶子骏佚老堂","f":"五言古诗","c":["未老已先佚，构堂名佚老。","与其宠辱惊，何似归未早。","渊明乃吾祖，此道能自保。","归来无一事，时时为酒恼。","纸帐春气融，不寐听春鸟。","关关枝上语，报我竹间晓。","我醉未能起，尔音一何好。","却笑世间人，忘忧种萱草。"]},{"t":"复雪","f":"五言古诗","c":["连朝雪复雪，吾独拥红炉。","樽中亦有酒，不为饥寒驱。","目前奚所忧，所忧在村墟。","去年旱兼水，二税多逃逋。","十家九乏食，往往死路衢。","空山嗥虎豹，深渊卧龙鱼。","飞鸟各敛翼，康庄断行车。","倚门独悲歌，阳气何时舒。"]},{"t":"将至寿阳谒朱行中龙图作","f":"五言古诗","c":["魏台公送我，春风花落尽。","寿阳我访公，萧萧朔风紧。","且复念残年，鬓发安得鬒。","高才久外补，惠爱益不泯。","聊歌古柏行，歌罢仰天哂。","长淮白鱼肥，冰壶酒堪引。"]},{"t":"暮春之月谒庐守陈元舆待制作","f":"五言古诗","c":["百年悯秋霜，念念流运歇。","一昨辞周行，于今鬓垂雪。","幽独谁为扶，寸心徒自折。","翻然驾柴车，宾闳重款谒。","与公论襟期，及此阳春月。","英英栏中花，滋露正妍发。","浊浊瓮中醪，浮醅想芬冽。","朝廷用直道，郡邑罕所阙。","嬿婉我之友，皎若环与玦。","良辰不同乐，衰暮空惜别。"]},{"t":"庐陵乐府十首 其一","f":"五言古诗","c":["妾抬纤纤手，一拂白玉琴。","琴声写三叠，寄妾万里心。","朱弦断可续，妾心常不足。","才惊枫叶丹，又见杨枝绿。","望君君未到，妾貌宁长好。","云鬓懒重梳，从教似秋草。"]},{"t":"庐陵乐府十首 其二","f":"五言古诗","c":["鸿雁殊未来，思君一弹琴。","泠泠别鹤语，折尽幽兰心。","蛛丝漫相续，难系骅骝足。","白日无时停，云鬓宁长绿。","年华要不老，不若丹青好。","对之虽无言，犹胜种萱草。"]},{"t":"庐陵乐府十首 其三","f":"五言古诗","c":["与子初执手，效彼瑟与琴。","子去既不返，谁复知我心。","宝刀能切玉，愿断金乌足。","留住枝上春，花红叶长绿。","懊恼复懊恼，憔悴变妍好。","不见庭中兰，埋没随百草。"]},{"t":"庐陵乐府十首 其四","f":"五言古诗","c":["妾身厌尘埃，专心托君子。","感君一面眄，涸辙逢秋水。","雍容未经年，结誓同生死。","胡为忽言别，短书无一纸。","愁思魂梦飞，鹊语不成喜。","岁晚君不来，红妆为君洗。"]},{"t":"庐陵乐府十首 其五","f":"五言古诗","c":["嵯峨姑射山，绰约飞行子。","绛唇启皓玉，明眸漾寒水。","方平与麻姑，相期永不死。","手披黄庭经，金字写青纸。","胡为谪人间，离合溢悲喜。","妖桃凝露珠，东风任吹洗。"]},{"t":"庐陵乐府十首 其六","f":"七言律诗","c":["庭下幽花羃寒雾，金鸭冷烟无一缕。","从君别妾驾红鸾，望断三山无觅处。","平时曲调休重举，长袖空垂不成舞。","醒眼牵愁送春去，独立残阳与谁语。"]},{"t":"庐陵乐府十首 其七","f":"五言律诗","c":["英英玉山禾，乃是凤凰食。","凤凰殊未来，禾生亦何益。","幽香眷春尽，孤根含露寂。","委弃同蒿莱，咄嗟人莫识。"]},{"t":"庐陵乐府十首 其八","f":"五言律诗","c":["自君之往矣，幽房守岁华。","眉头匀翠淡，裙带缕金斜。","魂魄空成梦，音书不到家。","凭谁度庾岭，和泪寄梅花。"]},{"t":"庐陵乐府十首 其九","f":"五言律诗","c":["粉黛元知假，丹青岂是真。","桃花初过雨，溪水暗流春。","眼眼随云断，书书托雁频。","渔郎自迷路，狂杀武陵人。"]},{"t":"庐陵乐府十首 其十","f":"五言律诗","c":["不作巫山雨，螺川久住家。","欲知冰未释，须信玉无瑕。","对局拈棋子，开窗摘杏花。","谁能谙此意，红日又西斜。"]},{"t":"妾薄命","f":"五言古诗","c":["雌凤始营巢，妖桃半敷萼。","忆昔嫁君时，相逢一何乐。","朱颜妾未变，白眼君先恶。","君恩不下济，妾意正难托。","空床春寂寥，孤灯夜萧索。","哀弦时一弹，弹终泪还落。"]},{"t":"怨别二首 其一","f":"五言古诗","c":["渡江君别妾，恨不如桃叶。","桃叶解随君，渡江不用楫。","妾既不得随，渡江楫如飞。","自怜妾命薄，江头还独归。","一步一回首，碧云凝落晖。","空将盈掬泪，和粉洒罗衣。"]},{"t":"怨别二首 其二","f":"五言古诗","c":["团扇不遮面，欲君永相见。","胡为忽别妾，船逐南风便。","君行妾独处，妾复谁为主。","正似晚春花，零落随风雨。","有情频寄书，莫令书更疏。","却羡路傍草，到处逢君车。"]},{"t":"代古相思","f":"五言古诗","c":["妾面如花开，妾心似兰死。","花开色易衰，兰死香不已。","愿持枯兰心，终焉托君子。","君行胡不归，两见秋风起。","鸿雁只空来，音书无一纸。","夜夜梦见君，朝朝懒梳洗。","不忆霜月前，丝桐为君理。","千古万古悲，悠扬逐流水。"]},{"t":"拟桃花歌","f":"词","c":["酣酣桃始花，灼灼粉面笑。","粉色射花光，夺尽丹青妙。","蓝衫马上郎，风流亦年少。","语言虽未通，精诚默相照。","敛容缓步复掩门，只见桃花不见人。","轻红浅白正含露，欲落半开将送春。","凝心驻马日渐晚，隐忍时时下前坂。","回头又不见桃花，唯有青山遮醉眼。","扬鞭击镫歌团扇，相见不如不相见。","逢人寄语问桃花，春残吹洗落谁家。"]},{"t":"怡轩吟赠番阳张孝子","f":"楚辞体","c":["古云蜀道难，蜀道之难难于上青天。","孝子寻亲不辞远，草蹻负米离番川。","西从荆州望夔国，扪萝蹑石穿林巅。","峡山愈深人迹绝，但闻悲风泠涧声潺湲。","汲溪钻火行复餐，夜宿茅屋衣裳单。","回看江南路九千，一见归客吞悲酸。","寄声吾母形骸安，慎勿为语皮皴乾。","涪州城西遇征蛮，城门防盗白昼关。","抚膺仰天涕汍澜，见亲之难难于蜀道难。","成都渐近心稍宽，踊跃可得瞻耆颜。","父昔离家子方孕，子得见父今壮年。","胡弗归兮死敢请，慰我慈母心悬悬。","三往三返又十载，孝子执辔方言还。","番人闻归竞嗟喜，夫妇白首重团圆。","诛茅立屋奉甘旨，陈侯篆榜名怡轩。","春禽提壶助春饮，綵衣自舞春风前。","腰金馔玉非我欲，但愿眉寿双松坚。","朝熙熙，暮熙熙，谁将朱丝绳，奏我怡轩诗。"]},{"t":"忆敬亭山作","f":"词","c":["忽忆敬亭山，翠碧千万寻。","白云拂地弄晴影，黄猿啸晚清人心。","桃花流水三月深，柳絮披烟辞故林。","重楼复殿据山脚，像塑制度祠非淫。","晋时谢守曾赛雨，至今石上镌遗吟。","五言雅重参二典，琅琅一诵铿璆琳。","绿潭无底白玉沈，千载何人知此音。","李白骑鲸出沧海，回鞭曾宿岧峣岑。","却泛虚舟弄溪月，紫霞之杯倾不歇。","醉来更约崔宗之，秋水玄谈清兴发。","数公逸驾何当还，怅望英风不可攀。","信道相看两不厌，古来只有敬亭山。"]},{"t":"神宗皇帝挽词二首 其一","f":"五言律诗","c":["物物皆成化，熙熙十九春。","寿觞方奏乐，法座忽流尘。","遗治前无古，称宗孰有神。","烟霄歧路别，百辟共沾巾。"]},{"t":"神宗皇帝挽词二首 其二","f":"五言律诗","c":["原庙工初毕，神游竟不还。","鼎湖龙驭远，湘岸竹枝斑。","谥号尊逾圣，陵基别有山。","九重春忽暝，四海惨愁颜。"]},{"t":"王丞相荆公挽词二首 其一","f":"五言律诗","c":["间世君臣会，中天日月圆。","裕陵龙始蛰，钟阜鹤随仙。","畜德何人绍，成书阖国传。","回头尽陈迹，麟石卧孤烟。"]},{"t":"王丞相荆公挽词二首 其二","f":"五言律诗","c":["公在神明聚，公亡泰华倾。","文章千古重，富贵一毫轻。","若圣丘非敢，犹龙耳强名。","悲风白门路，啼血送铭旌。"]},{"t":"哭梅直讲圣俞","f":"五言古诗","c":["生事念死隔，歘如过鸟飞。","长空不留迹，清叫竟何之。","死者固已矣，生者谩相思。","昭亭雪塞山，相遇忘寒饥。","解剑贳浊酒，果肴躬自携。","扫除长少分，旷荡文章期。","赠蒙以大白，自谓无复疑。","及将起草茅，谨札还先驰。","邀我采石渡，烂醉霜蟹肥。","沉吟望夫曲，朗诵天门诗。","险绝必使和，凡鱼岂龙追。","篇篇被许可，当友不当师。","凌晨挂高帆，公行我言归。","一别三四秋，音问山中稀。","去年集选曹，僮瘦马力羸。","访公国东门，问我来何时。","青刍与白饭，诸子争赍持。","论新复谈故，谓我今逾奇。","南还得长篇，万里衔光辉。","此德未云报，讣音裂肝脾。","桓桓万人英，不遇终愁羁。","一官止太学，薄命吁可悲。","所嗟吾道丧，斯文竟何为。","譬彼卞子玉，弃置污浊泥。","凤来无嘉禾，啄肉纷群鸱。","彼苍厥有主，此理安无欺。","呜呼如之何，酸嘶复酸嘶。"]},{"t":"哭夏寺丞公酉","f":"五言古诗","c":["齐山郁愁烟，镜潭坠孤月。","佳人去不还，生别成死别。","有才曾未施，负冤终莫雪。","世情多反覆，美玉不如铁。","无路攀魂车，隔江寄清血。"]},{"t":"哭子点","f":"五言古诗","c":["五岁养育恩，一朝随埃尘。","琅琅读书声，在耳犹如新。","哽哽临绝言，唤爷眉屡颦。","永痛卑栖邑，医脉非良真。","微疾遽夭殇，吾家失麒麟。","嗥天天莫知，拊地地不闻。","泪迸睛欲枯，肠断鼻愈辛。","汝卧长夜台，我孤大梦身。","后嗣复谁望，有车已摧轮。","佳雏堕危巢，异芳零短春。","黄泉无白日，青冢多愁云。","哀弦写悲歌，吊汝冥漠魂。"]},{"t":"哭宗叔致政大将军","f":"七言律诗","c":["文锋困挫离场屋，武略纵横勤冕旒。","国士传家虽有子，将军终老不封侯。","抱冰末路垂三纪，埋玉空山第一秋。","馀派江东藉云荫，载瞻遗像涕交流。"]},{"t":"故临川太守石公挽词二首 其一","f":"五言律诗","c":["忆昔江头别，悲欢失后期。","奸言诬直节，枉狱累明时。","白玉原无玷，青天孰可欺。","有儿能雪耻，泉壤释馀悲。"]},{"t":"故临川太守石公挽词二首 其二","f":"五言律诗","c":["半道逢豺虎，吞声力已穷。","命从冤狱丧，言有谏臣公。","玉树埋长夜，金鱼委断蓬。","旅魂虽获雪，千载起悲风。"]},{"t":"陈伯育承事挽词二首 其一","f":"五言律诗","c":["海鹤冰为骨，霜潭月作心。","要宾唯饮酒，焚券不论金。","相望萦离恨，何嗟得讣音。","春回坟草绿，谁伴夜台吟。"]},{"t":"陈伯育承事挽词二首 其二","f":"五言律诗","c":["二子皆攀桂，一生唯好吟。","夜台如得句，泉路孰知音。","饮态思颓玉，交情失断金。","奠刍何以报，折尽老夫心。"]},{"t":"邹宣德挽词二首 其一","f":"五言律诗","c":["忆昔姑溪上，分携岁月赊。","清标冰有骨，静德玉无瑕。","不杀居为戒，传经大厥家。","西山问仙籍，公合在烟霞。"]},{"t":"邹宣德挽词二首 其二","f":"五言律诗","c":["静乐畴能匹，翛然几杖间。","有儿专使节，无念落尘寰。","流水归何处，孤云去不还。","成仙应蜕骨，谁谓掩泉关。"]},{"t":"哭漳州蔡温老秀才","f":"七言律诗","c":["交游气概如君少，患难扶持及我多。","万里相思魂往返，一书报死泪滂沲。","文场决策终难必，旅馆捐躯可奈何。","犹得有儿传素业，几时归葬旧山坡。"]},{"t":"杨次公侍讲挽词二首 其一","f":"五言律诗","c":["力学窥前古，扶经翊太平。","乐成天地格，祧正祖宗明。","知命穷犹达，趋玄死亦生。","世无班马笔，谁为勒幽铭。"]},{"t":"杨次公侍讲挽词二首 其二","f":"五言律诗","c":["孤进终难达，文章误此生。","才趋王府讲，已梦玉楼成。","遗箧书千卷，招魂酒一觥。","空馀淮上月，不到夜台明。"]},{"t":"杨次思博士挽词","f":"五言律诗","c":["有志吞戎虏，成书达帝庭。","长江倾学术，短炬速年龄。","玉树埋蒿壤，泉台掩夜扃。","功勋何可问，不得上丹青。"]},{"t":"亡友留君仪挽词二首 其一","f":"五言律诗","c":["信报君仪讣，将如吾道何。","交游亡玉树，涕泪泻金波。","三子先凋泯，一身缠病痾。","人生谁不死，遗恨独君多。"]},{"t":"亡友留君仪挽词二首 其二","f":"五言律诗","c":["壮子皆先陨，亲丧未启攒。","病成终不愈，魂散若为安。","结义从今泯，遗编忍复看。","亭开基石处，云水想漫漫。"]},{"t":"吊故友吴延之屯田","f":"五言律诗","c":["吴老归泉后，人间未有君。","春深来阳草，月乱采江云。","孤啸猿求侣，哀鸣雁失群。","姑溪一樽酒，遥酹五峰坟。"]},{"t":"哭亡友李公达","f":"七言律诗","c":["忽得凶音泪不收，可怜英气陨荒幽。","天垂北斗夜台静，虎啸西风坟树愁。","学道未行尝自信，高名虽在复何求。","谩携一榼招魂酒，独对修江想献酬。"]},{"t":"吊黄塘寺知白上人","f":"五言律诗","c":["今日黄塘寺，昔年知白师。","悟禅兼悟律，能画亦能诗。","旧卷春涵瞑，新坟月掩悲。","馀生我何有，骑马送衰迟。"]},{"t":"吊亡友袁世弼太博","f":"五言律诗","c":["自掩斯人骨，西山秀色低。","文章惊早悟，寿夭理难齐。","绝壑沉寒玉，空江没断霓。","儿孙今卖宅，感旧只酸嘶。"]},{"t":"三亡诗","f":"五言古诗","c":["荣翁苦于学，腹实五车书。","尤明礼乐事，画就百幅图。","献之神宗朝，不报还旧庐。","白头著青衫，老愤犹欲舒。","佐邑曾未赴，瞑目忽已殂。","何子稍家富，恬不为利拘。","执笔工词章，科第学有馀。","终遭有司黜，才命诚难俱。","今闻亦长往，令我勤悲吁。","二家各有子，素业传门闾。","登科既同籍，奔丧又同途。","李君出世胄，轩轩佩琼琚。","计偕冠多士，场屋喧名誉。","晚乃乐高隐，卖药荒村墟。","愈贫愈自信，纯洁不可污。","天胡夺其龄，否极泰则无。","斯人皆旧游，想望空踟蹰。","顾我虽未死，目眊霜盈须。","近酒已先恶，趋时迹尤疏。","飞章乞残骸，轻舟下重湖。","将投永安泊，访旧相欢娱。","那知死生隔，三秀同时枯。","欲为招魂篇，悲风涕沾濡。"]},{"t":"拟挽歌五首 其一","f":"五言古诗","c":["百年苦役役，一死已休休。","惟我方自适，妻子空悲愁。","满樽奠美酒，满盘荐珍羞。","我终不可起，汝情谩悠悠。","送我入蒿里，寂寞无春秋。"]},{"t":"拟挽歌五首 其二","f":"五言古诗","c":["形坏影亦灭，有神竟何依。","漠漠空木中，岂知经四时。","以此为长年，谁人不同归。","儿孙汝勿泣，朋旧汝勿悲。","岁月易经过，冥默终相期。"]},{"t":"拟挽歌五首 其三","f":"五言律诗","c":["生前势有殊，死去分始齐。","且将耳目静，安用亲旧啼。","鸿雁任南北，日月随东西。","陵谷亦已变，道化复何为。"]},{"t":"拟挽歌五首 其四","f":"五言律诗","c":["于生动以扰，既死静且潜。","黄土假面目，青草为须髯。","荣华春风吹，憔悴秋霜沾。","回嗟在世人，不识此理兼。"]},{"t":"拟挽歌五首 其五","f":"五言古诗","c":["枯骨蝼蚁馀，空棺蔓草缠。","欲诉既无路，欲窥不见天。","休休可奈何，达道乃自然。"]},{"t":"四皓","f":"五言律诗","c":["彼美四贤老，高风万古寒。","去逃秦鼎镬，归识汉衣冠。","翼翼羽翰就，堂堂宗社安。","商山弊庐在，还入白云端。"]},{"t":"晚望","f":"五言律诗","c":["久客心尝折，登楼望转迷。","风倾蘋叶乱，雨重柳条低。","未得趋金马，何当似木鸡。","细寻乡国路，愁听暝鸦啼。"]},{"t":"即事","f":"五言律诗","c":["北户风欺幌，南桥水拍城。","柳长无嫩色，莺老有新声。","书帙看慵卷，茶瓯不厌擎。","故园何日返，此地独含情。"]},{"t":"幽居","f":"五言律诗","c":["春晚堪行乐，幽居独闭门。","忘形付诗酒，吾道委乾坤。","坏壁蜗涎乱，残经鼠迹翻。","交游今已绝，孤坐欲何言。"]},{"t":"江亭","f":"五言律诗","c":["江亭孤坐久，野望眼偏明。","映日浮云簿，摇风细柳轻。","出墙新笋熟，拍岸晚潮生。","遣仆沽春酒，幽欢取次成。"]},{"t":"遣意","f":"五言律诗","c":["发为烟岚秃，愁因患难添。","径荒无过客，笋迸任穿檐。","啅雀谁能遣，惊乌不用占。","有巾堪漉酒，聊欲效陶潜。"]},{"t":"春水","f":"五言律诗","c":["春水碧泱泱，平堤映绿杨。","田畴资灌溉，鸥鸟共徜徉。","放饵愁空掣，浮杯兴最长。","晚风吹细浪，仍送落英香。"]},{"t":"早起","f":"五言律诗","c":["客愁偏早起，衰病惬晴明。","索酒防春瘴，披衣听鸟声。","旧书慵检阅，新客懒逢迎。","何日笼樊启，再归溪上耕。"]},{"t":"初夜","f":"五言律诗","c":["初月未成魄，瘴天云雾低。","浦昏船竞入，林密鸟争栖。","褊性怜幽独，香醪自挈携。","布衾今夜冷，犹得避儿啼。"]},{"t":"可惜","f":"五言律诗","c":["可惜花飞尽，春归客未归。","艰难行路险，老大赏心稀。","翰墨谁曾问，渔樵与愿违。","江干空驻目，藜杖得相依。"]},{"t":"客禁","f":"五言律诗","c":["客禁何时释，惊魂梦里归。","深忧邻虎穴，那得并鱼矶。","草色欣欣茂，萤光个个微。","残生苦多难，搔首掩荆扉。"]},{"t":"卧柳","f":"五言律诗","c":["冉冉碧濠边，三株细柳眠。","根攲元著水，叶大镇藏烟。","不作栋梁用，岂忧斤斧先。","春风任飘泊，客意亦留连。"]},{"t":"水涨","f":"五言律诗","c":["山雨连朝注，溪流没草亭。","蛟鼍方汹汹，鸿雁自冥冥。","只恐翻河汉，终当见日星。","波澜平地作，嗟叹未曾经。"]},{"t":"水花","f":"五言律诗","c":["水畔花饶笑，攲枝映小亭。","日光烘欲醉，江色冷还醒。","浅白浑迷鹭，残红尚衬萍。","幽人颇萧索，此地要频经。"]},{"t":"西斋二首 其一","f":"五言律诗","c":["西斋吾所构，檐角颇依林。","潇洒松篁影，暄和燕雀音。","青春那肯住，白发任相侵。","稍悟渊明乐，时时抚素琴。"]},{"t":"西斋二首 其二","f":"五言律诗","c":["西斋吾所爱，一径绿萝深。","终日听新鸟，令人忘故林。","地偏无客到，山润有苔侵。","祸患须安命，优游不废吟。"]},{"t":"南楼","f":"五言律诗","c":["兀坐南楼夜，栏干俯列星。","村遥喧瓦鼓，塔近震金铃。","湿草埋昏瘴，飞虫接小萤。","物生皆有理，吾亦委颓龄。"]},{"t":"自贻","f":"五言律诗","c":["自恨心肝拙，题诗愈不工。","痴迷循磨蚁，辛苦打窗虫。","妙道知何补，多言自取穷。","不如长寂默，块尔白头翁。"]},{"t":"溪岸","f":"五言律诗","c":["溪岸逢春暮，柔条尽意攀。","轻鸥翔近渚，好鸟响空山。","小艇长攲侧，孤云自往还。","远游成底事，白首忆乡关。"]},{"t":"要客","f":"五言律诗","c":["要客来何晚，重乾漉酒巾。","玉琴虚别操，藤榻恐流尘。","山暗萧萧雨，花辞短短春。","杖藜慵缓步，愁杀独游人。"]},{"t":"城南","f":"五言律诗","c":["淡沲城南路，参差柳绊烟。","稻秧才一寸，蚕子始三眠。","曲折藏花地，暄和载酒天。","清江深有兴，只欲解归船。"]},{"t":"夜兴","f":"五言律诗","c":["日没草堂阴，收书复挂琴。","闭门人迹绝，危坐客愁深。","星汉光铓动，湖山气象沈。","嫦娥如借月，蚊蚋莫相侵。"]},{"t":"夕阳","f":"五言律诗","c":["夕阳沈谷口，海水接天南。","归鸟自成阵，暝山如半酣。","看云贪仰面，移杖忽遗簪。","幽独谁相过，人情老始谙。"]},{"t":"迁居","f":"五言律诗","c":["殊方留滞客，迁馆避諠哗。","破榻依寒竹，疏窗对晚花。","燕归疑识面，鸟噪默怀家。","囊橐无书卷，新愁有五车。"]},{"t":"交游","f":"五言律诗","c":["一作闽南客，幽忧忽过春。","交游半卿相，踪迹自埃尘。","未附垂天翼，空成涸辙鳞。","吾庐松菊在，怅望熟溪滨。"]},{"t":"微寒","f":"五言律诗","c":["广潦生寒夜，幽人独倚楼。","渚涯迷海若，灯火想渔舟。","雷鼓蛙争响，云天月暗流。","未应时序变，初夏反如秋。"]},{"t":"旅食","f":"五言律诗","c":["旋煮青芹滑，新炊白稻香。","僧居同淡泊，旅食幸康强。","未拟沉湘水，深防死耒阳。","上书终自达，圣世本虞唐。"]},{"t":"客问","f":"五言律诗","c":["来时麦未吐，今见秀盈畦。","投阱还遭石，登云孰有梯。","尔谗徒似锦，吾醉只如泥。","行止无劳问，空山杜宇啼。"]},{"t":"废阁","f":"五言律诗","c":["叠甓基犹在，排空阁已摧。","燕愁寻旧栋，蚁蠹傍新苔。","月色閒圆缺，风声自去来。","废兴何可问，劫火亦成灰。"]},{"t":"松风","f":"五言律诗","c":["夜寂松风度，魂清客枕寒。","琴声传不尽，诗句写应难。","骤雨倾瑶砌，真珠落玉盘。","隐居如可访，吾欲跨翔鸾。"]},{"t":"挥扇","f":"五言律诗","c":["四月长汀郭，晴多暑气浓。","欲眠难藉草，选荫必依松。","绿水遥思濯，青云底处逢。","西岩残照尽，挥扇待疏钟。"]},{"t":"寓馆","f":"五言律诗","c":["一径松阴合，重门院落深。","客来听鹊喜，春过惜莺吟。","风月时经槛，尘埃不到襟。","黄庭看在手，白雪任盈簪。"]},{"t":"松枥","f":"五言律诗","c":["婆娑松与枥，夹径碧濛濛。","未辨雪霜操，同沾雨露功。","低枝翻翠盖，垂叶密樊笼。","他日为梁柱，抡材合至公。"]},{"t":"立夏","f":"五言律诗","c":["岁旦辞江国，炎天客瘴乡。","浴陂群鸟白，含雾野梅黄。","恨别山随眼，消愁酒满觞。","残魂终易断，回首只茫茫。"]},{"t":"深夜","f":"五言律诗","c":["四天垂翠碧，一水湛星辰。","寂寞殊方夜，漂流片叶深。","帝乡劳梦想，客路只风尘。","钟鼓还催晓，深惭钓渭滨。"]},{"t":"竞渡","f":"五言律诗","c":["竞渡传风俗，旁观亦壮哉。","棹争飞鸟疾，标夺彩龙回。","江影浑翻锦，歌声远震雷。","轻生一饷乐，时序密相催。"]},{"t":"伤春二首 其一","f":"五言律诗","c":["腊月花开尽，中春不见花。","柳阴空拂地，草色漫平沙。","客路心常折，僧窗鬓自华。","故乡何处是，瘴海暗天涯。"]},{"t":"伤春二首 其二","f":"五言律诗","c":["春雨时时暗，春花眼未经。","生涯随过鸟，世态委浮萍。","瘴雾何由避，蛮歌不忍听。","谁家有醇酎，吾欲醉兼醒。"]},{"t":"西池","f":"五言律诗","c":["雨涨西池水，微澜拍画桥。","不愁莲芡没，唯恐栋梁漂。","扶杖防危步，移床避晚潮。","何当风日爽，一舞看纤腰。"]},{"t":"积潦","f":"五言律诗","c":["积潦连江海，舂撞说剑锋。","郡城千丈拆，民食五年凶。","雨脚悬麻直，云头泼墨浓。","忘机唯白鸟，不解避蛟龙。"]},{"t":"自笑","f":"五言律诗","c":["自笑姑溪客，还投瘴海边。","不才无进路，多病复残年。","欲种千竿竹，将求二顷田。","人生底事足，且爱酒涓涓。"]},{"t":"喜晴","f":"五言律诗","c":["瘴乡仍久雨，生事念樵渔。","江海云归尽，乾坤日上初。","短垣张浣服，幽圃理残蔬。","佐国知无术，聊欣病体舒。"]},{"t":"城上","f":"五言律诗","c":["危步欲何适，城头独杖藜。","水归沧海后，云散暮天时。","秋色长空淡，笳声迥野悲。","泥沙埋熟稻，一穗亦无遗。"]},{"t":"独醒","f":"五言律诗","c":["野性惟怜酒，无聊遂独醒。","风尘双白鬓，天地一青萍。","鵩鸟宁须赋，离骚未是经。","回头付陈迹，终欲醉冥冥。"]},{"t":"邸报","f":"五言律诗","c":["立法新三省，论材只数公。","簿书期会正，风俗见闻同。","边塞疮痍后，朝廷气概中。","不才思献赋，天路恐难通。"]},{"t":"宦情","f":"五言律诗","c":["宦情聊落甚，况在九溪边。","瘴雾易成雨，飓风偏覆船。","水残馀盗贼，村迥少人烟。","欲达中州信，迢迢路六千。"]},{"t":"自遣","f":"五言律诗","c":["骨相殊屯贱，无官只有阶。","半生萍梗过，两鬓雪霜排。","去国肠空断，求田心未谐。","新交莫相笑，中立一枝柴。"]},{"t":"西庵","f":"五言律诗","c":["一庵丹荔下，更与画桥邻。","不许尘埃到，每期风月亲。","好音闻度鸟，斜影辨疏筠。","拂拭白藤榻，攲眠稳病身。"]},{"t":"雨过","f":"五言律诗","c":["雨过添幽事，褰裳步暖沙。","竹梢含净雾，藤刺罥轻槎。","鸂鶒双随浪，蜻蜓对觅花。","老夫诗思惬，颇觉日沉车。"]},{"t":"野寺","f":"五言律诗","c":["野寺盘山腹，高秋雨霁天。","拂檐云漫漫，穿竹水涓涓。","接食怜驯鸟，支筇慕老禅。","经年无客到，门巷叠青钱。"]},{"t":"晚晴","f":"五言律诗","c":["川涨那堪雨，今朝喜晚晴。","幽花萦露重，浊水止蛙鸣。","圩稻应全刈，村醪可强倾。","吾虽无一亩，亦足慰馀生。"]},{"t":"屏迹","f":"五言律诗","c":["屏迹已恨晚，疲躯今自由。","百年无七十，一日有千忧。","觅酒开青眼，凭诗遣白头。","莫言宾客少，池上两三鸥。"]},{"t":"却卧","f":"五言律诗","c":["晓起梳头毕，开窗却卧时。","素烟收枕席，红日上藩篱。","仰面看书卷，移床近酒池。","纷纷万方事，安用老夫知。"]},{"t":"无客","f":"五言律诗","c":["病久人情厌，经旬客不来。","帘因风力卷，门待月华开。","柳上新蝉咽，城头暮角哀。","劳生随物化，孰免葬蒿莱。"]},{"t":"门巷","f":"五言律诗","c":["肃肃秋容净，萧萧门巷深。","荆榛元自合，车马少过寻。","问婢催蔬熟，呼儿取酒斟。","藤床未成寐，野鸟噪归林。"]},{"t":"赋分","f":"五言律诗","c":["赋分从来薄，明时敢妄干。","六年悲对狱，五十速休官。","水送云天净，山开洞壑寒。","一枝能息影，何暇北溟宽。"]},{"t":"农事","f":"五言律诗","c":["三岁悲农事，官仓亦已贫。","敕书虽赦狱，恩泽未苏民。","南国供输大，中宵涕泗频。","一心随草木，无复念沉沦。"]},{"t":"野望","f":"五言律诗","c":["暑雨收残候，秋云结薄阴。","山光翠兼紫，水影净还深。","竹密群鸦入，天空一雁沈。","兴来搔白首，衰飒愧儒林。"]},{"t":"日暮","f":"五言律诗","c":["倚杖孤亭久，无心辨俗讹。","暮山青扫淀，秋汉白浮波。","岸震归船鼓，村喧刈稻歌。","未收西望眼，问罪有干戈。"]},{"t":"归燕","f":"五言律诗","c":["天外秋风劲，梁间燕羽稀。","营巢雏未老，何地汝成归。","蜃泽多楼阁，茅堂无阱机。","故园春色动，还趁社前飞。"]},{"t":"遣怀","f":"五言律诗","c":["节物惊心事，抟金菊放花。","潜鱼防饵钓，高雁避城笳。","南浦秋风冷，西江夕照斜。","异乡消息断，林外更闻鸦。"]},{"t":"捣衣","f":"五言律诗","c":["清秋送残暑，隔屋忽闻砧。","远震星河夜，遥兴关塞心。","欲知针缕密，即是泪痕深。","他日功成后，逢人寄好音。"]},{"t":"植杖","f":"五言律诗","c":["独往怜渔艇，群飞爱暮鸥。","谁云天地窄，自伴水云游。","荇叶青争老，蓼花红半收。","江头人事绝，植杖我何忧。"]},{"t":"空囊","f":"五言律诗","c":["床有牛衣卧，厨供石髓餐。","此身知是幻，卒岁不为难。","冰合潜蛟冷，云深病鹤寒。","青钱无得选，空挂一囊看。"]},{"t":"秋笛","f":"五言律诗","c":["清秋闻笛弄，独立露沾衣。","天外云留住，水中龙未归。","悠扬声益苦，感激思何微。","不似前春听，梅花片片飞。"]},{"t":"黄山二首 其一","f":"五言律诗","c":["秋物已潇洒，临高念岁穷。","阵收群雁没，峰断片云空。","月色山川内，笛声关塞中。","西人未柔服，长策在诸公。"]},{"t":"黄山二首 其二","f":"五言律诗","c":["秋晚陟浮丘，西临古渡头。","钟声沉断岸，桥影散中流。","雪让芦花密，云排稻穗稠。","乾坤均帝力，草木岂能酬。"]},{"t":"柴门","f":"五言律诗","c":["水落烟村迥，柴门四五家。","晚风回断雁，寒雨侧幽花。","世事纷无已，人生自有涯。","鲸鳌真可钓，吾兴欲乘槎。"]},{"t":"复寒","f":"五言律诗","c":["三月闽南国，阴寒变惨凄。","市楼添酒价，山雨勒莺啼。","田父忧春种，商人怯路泥。","何当好风日，稚子浴清溪。"]},{"t":"元舆携酒见过三首 其一","f":"五言律诗","c":["永日门常掩，欣闻五马过。","社馀巢燕入，花散蜜蜂多。","望断千山绿，愁来两鬓皤。","肝肠思一濯，须藉酒为河。"]},{"t":"元舆携酒见过三首 其二","f":"五言律诗","c":["酒味年来美，携觞约屡过。","交情贫始见，诗思老仍多。","许国心常赤，思家发任皤。","诵君新得句，秀色揽山河。"]},{"t":"元舆携酒见过三首 其三","f":"五言律诗","c":["沉毅陈夫子，谈兵孰与过。","运筹知必胜，善将不论多。","汉阵千重黑，胡沙万里皤。","如闻洗戈甲，谁为挽天河。"]},{"t":"雨中喜君仪要温老希圣同见过二首 其一","f":"五言律诗","c":["萧萧山寺雨，漠漠暮云寒。","不恨麻衣薄，深愁酒盏乾。","离披花刺眼，容易雪冲冠。","要客能相遇，宁辞湿锦鞍。"]},{"t":"雨中喜君仪要温老希圣同见过二首 其二","f":"五言律诗","c":["万里乡园别，一春风雨多。","乱蛙声斗急，归燕舞缘何。","石榻昏苔藓，柴门暗薜萝。","橛株方自笑，忽枉故人过。"]},{"t":"谢君仪携酒要客慰唁愁寂二首 其一","f":"五言律诗","c":["佳客过穷巷，良朋复可要。","静缘棋局乱，愁逐酒杯销。","花底莺声度，林间雨点飘。","晚春频一醉，何必拟松乔。"]},{"t":"谢君仪携酒要客慰唁愁寂二首 其二","f":"五言律诗","c":["谗人未投北，君子独相亲。","岁月惊春晚，壶觞慰我贫。","松声风外急，山色雨中新。","一醉无归梦，宁论寂寞滨。"]},{"t":"白莲启日上人退避长老之命以四韵高之","f":"五言律诗","c":["结宇古城边，能诗复悟禅。","钵分摩诘饭，池种远公莲。","竹飐春烟静，禽歌夜月圆。","洁身吾有趣，回首谢尘缘。"]},{"t":"送李绛伯华户曹","f":"五言律诗","c":["国士苟微禄，携家千里行。","乡关寒食节，邮舍冷猿声。","落日和云尽，离觞与泪倾。","衔冤仍送别，何以慰浮生。"]},{"t":"和石声叔留题君仪基石亭二首 其一","f":"五言律诗","c":["高才摅远趣，凿石架危亭。","宿鸟依林白，春苗接海青。","云光随帚乱，泉响置琴听。","况得少陵句，宜镌座右屏。"]},{"t":"和石声叔留题君仪基石亭二首 其二","f":"五言律诗","c":["因山基大石，华榜揭高亭。","畦稻翻新绿，山岚浮远青。","鸟行云际度，松籁雨馀听。","安得吴生画，为予传小屏。"]},{"t":"谢君仪寄新茶二首 其一","f":"五言律诗","c":["建溪春物早，正月有新茶。","得自参军掾，分来居士家。","辗开黳玉饼，汤溅白云花。","一啜清魂魄，醇醪岂足誇。"]},{"t":"谢君仪寄新茶二首 其二","f":"五言律诗","c":["北苑藏和气，生成绝品茶。","岂宜分旅馆，只合在仙家。","点处成云蕊，看时变雪花。","琳琅得新句，又胜玉川誇。"]},{"t":"晓起闻禽寄元舆","f":"五言律诗","c":["幽鸟语清晨，窗间宅禁人。","只知添白发，不觉度青春。","救过须三省，观空止一尘。","贤交如未弃，时送浊醪醇。"]},{"t":"寒食感怀示子焘二首 其一","f":"五言律诗","c":["柳暗青春暮，莺啼静院阴。","乡关隔寒食，父子共沾襟。","未举鹏天翼，聊为鵩舍吟。","惊魂招不得，时节感人深。"]},{"t":"寒食感怀示子焘二首 其二","f":"五言律诗","c":["寒食金波泪，他乡此日心。","草连天际色，泉断陇头音。","先冢三年别，飞埃万里侵。","只凭攲枕梦，时到谢山阴。"]},{"t":"寒食元舆见要南楼把酒","f":"五言律诗","c":["五马登城堞，平分载酒船。","无家寒食客，小雨惜花天。","循抚恩何厚，飘零命最邅。","閒愁不用遣，一醉暂成仙。"]},{"t":"夜雨感怀二首 其一","f":"五言律诗","c":["夜雨霪难霁，沟塍复乱蛙。","轻寒侵病骨，馀响答空阶。","杜子嗟沾湿，庄生失渚涯。","通宵不成寐，归思泻长淮。"]},{"t":"夜雨感怀二首 其二","f":"七言绝句","c":["羽毛零落易摧伤，父子同幽瘴疠乡。","归梦不成残夜雨，空阶滴滴到愁肠。"]},{"t":"忆小子鼎","f":"五言律诗","c":["元朝别家去，音信隔三春。","读易应终卷，端居莫患贫。","定交疏燕雀，养节慕松筠。","冤狱何时辨，思儿泪满巾。"]},{"t":"排闷呈元舆","f":"五言律诗","c":["交态非今薄，人情自古难。","敝裘甘我老，雄剑请君弹。","魂逐云峰断，心依酒海宽。","百年能几许，日月似跳丸。"]},{"t":"怀天骘","f":"五言律诗","c":["筑室君先隐，穷途我正难。","流莺春谷暖，别鹤玉琴寒。","泉响经时听，云光抵暮看。","异方空泪眼，何日共幽欢。"]},{"t":"元舆三月三十日致酒","f":"五言律诗","c":["衰病仍为客，相依过一春。","和篇惊韵险，把酒沃愁频。","紫燕巢方稳，黄鹂语尚新。","何时公赴召，终欲托车轮。"]},{"t":"元舆试北苑新茗","f":"五言律诗","c":["建溪虽接壤，春末始尝茶。","旋汲邻僧水，同烹北苑芽。","月圆龙隐鬣，云散乳成花。","贡入明光殿，分来王谢家。"]},{"t":"别南楼","f":"五言律诗","c":["寄榻六十日，朝朝上碧城。","云光随近远，山色变阴晴。","濠静鱼频跃，楼空燕不惊。","他时那复到，欲去重含情。"]},{"t":"四月一日","f":"五言律诗","c":["有瘴从今始，斯须雨复晴。","草蒸蛇肆毒，榛密鵩尝鸣。","晚食宜防饱，村醪可强倾。","何时击归镫，高视叹浮生。"]},{"t":"别濠上","f":"五言律诗","c":["自得庄生乐，观鱼近碧濠。","触萍时鼓鬣，防饵不投刀。","柳挹春风静，鸥眠夜月高。","舍旃吾有适，沧海钓鲸鳌。"]},{"t":"闻旧居教乐","f":"五言律诗","c":["昔作幽人宅，今为舞女场。","燕惊弦管杂，草避绮罗香。","諠静虽殊致，兴衰自有常。","遥怜岩桂下，谁拂读书床。"]},{"t":"登清音亭二首 其一","f":"五言律诗","c":["已别城楼景，还登树杪亭。","地高邻北斗，山远接南溟。","蟾影依云断，樵歌隔浦听。","客愁安用遣，此处可忘形。"]},{"t":"登清音亭二首 其二","f":"五言律诗","c":["薄暮杳何适，高高登古亭。","地无南国瘴，帘卷半空星。","石瘦长人立，潭春皓雪停。","短才吟不就，终欲付丹青。"]},{"t":"雨中怀元舆","f":"五言律诗","c":["暂阻龙山雨，还思凤阁人。","凌云曾献赋，薄雾岂藏身。","酒酿公田秫，羹调紫豉莼。","稍晴应见过，酬唱莫辞频。"]},{"t":"雨晴都按口号呈元舆","f":"五言律诗","c":["雨为华筵止，晴牵饮兴长。","管弦随昼永，罗绮散风香。","卫仗留春碧，宫衣想赭黄。","明年今日事，归捧祝尧觞。"]},{"t":"元舆怜我复有漳南之行以曲局不可出遂置一樽托公域弟酌发眷眷之情于此可见矣以四韵谢元舆并呈公域弟","f":"五言律诗","c":["怜我万里别，南荒多瘴埃。","身为官事隔，酒托故人开。","饮德知难报，论欢默可猜。","宗家有毛女，冰洁胜寒梅。"]},{"t":"与元舆论诗而风雨骤至","f":"五言律诗","c":["一作城头饮，重论别后诗。","倏然云雨至，应有鬼神悲。","叙事公偏富，求声我最知。","赓酬三百首，馀韵付咸池。"]},{"t":"元舆近诗加妙用寄四韵","f":"五言律诗","c":["谁识子昂孙，新诗霭暮云。","体兼诸谢备，名与少陵分。","今去知无敌，从来自出群。","南山能射虎，只许李将军。"]},{"t":"谢元舆送鲜鲤煮酒","f":"五言律诗","c":["鲜鲤江湖味，香醪日月春。","抚循时有赠，饱暖遂忘贫。","玉缕空投箸，金波漫入唇。","交情今乃见，晚节共松筠。"]}]};